(window.GIM_TS=window.GIM_TS||{})["Zevachim.6"]={"from":144,"a":[["\u0003ו\u0004מכל מקום \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]\u0006 שבמקרה שנתערב איבר של בהמה בעלת מום באיברי עולה העומדים להקרבה, כגון ראש בראשים, ולכתחילה אסור להקריב אף לא אחד מהם, \u0003ר' אליעזר אומר: אם\u0004 כבר \u0003קרב הראש של אחד מהן\u0004 — \u0003יקרבו כל\u0004 שאר ה\u0003ראשים.\u0004 שכן יש לתלות ולומר שאותו הראש שקרב הוא ראשו של בעל המום. הרי איפוא, שגם איברים של שחוטים, שנדחים לגמרי, אם נדחו מהקרבה מחמת איסור שנתערב בהם — אין הם נדחים לגמרי, וכשרים בדיעבד!","ומשיבים: אין מכאן ראיה, שכן \u0003הוא\u0004 ר' אליעזר \u0003אומר\u0004 את דבריו \u0003כ\u0004שיטת \u0003חנן המצרי,\u0004 שאמר שאף שחוטים אינם נדחים. \u0003דתניא\u0004 \u0005[ש\u0006כך \u0005שנויה\u0006 ברייתא\u0005],\u0006 \u0003חנן המצרי אמר: אפילו\u0004 כבר נשחט שעיר יום הכיפורים, שמזים מדמו בקודש הקדשים, וה\u0003דם\u0004 שלו כבר נמצא \u0003ב\u0004תוך ה\u0003כוס,\u0004 ומת בן זוגו (השעיר המשתלח לעזאזל) ובאותה שעה לא ניתן לזרוק את הדם — אין הדם נדחה בכך, אלא \u0003מביא חבירו\u0004 (שעיר אחר), \u0003ומזווג\u0004 (מצרף) \u0003לו\u0004 שישמש כשעיר המשתלח לעזאזל. אך לדעת הסבורים שיש דחייה בקרבנות, הרי גם אם נאסרו לכתחילה מחמת תערובת — שוב אין הם כשרים להקרבה, וכדברי רבא.","ועוד בענין זה, \u0003אמר רב נחמן אמר רבה בר אבוה אמר רב: טבעת של עבודה זרה,\u0004 שהיא אסורה בהנאה ואינה בטילה אפילו באלף, \u0003שנתערבה במאה טבעות\u0004 של היתר, \u0003ו\u0004לאחר מכן \u0003נפלה אחת מהם לים הגדול\u0004 — \u0003הותרו כולן,\u0004 משום \u0003דאמרינן\u0004 \u0005[שאומרים אנו]:\u0006 \u0003הך דנפל היינו דאיסורא\u0004 \u0005[זו שנפלה זוהי\u0006 הטבעת \u0005של האיסור].\u0006","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבא לרב נחמן\u0004 ממה ששנינו במשנתנו: כל הזבחים שנתערבה בהם חטאת המתה או שור הנסקל, \u0003אפילו\u0004 התערבה \u0003אחת בריבוא\u0004 — נאסרה כל התערובת ו\u0003ימותו כולן.\u0004 ולשיטת רב, שתולים לומר שזה שאבד הוא האסור, \u0003אמאי\u0004 \u0005[מדוע]\u0006 ימותו כולם? נמתין שימות אחד מהם, ו\u0003נימא\u0004 \u0005[נאמר]:\u0006 זה \u0003דמית\u0004 \u0005[שמת]\u0006 — \u0003איסורא מית\u0004 \u0005[האיסור\u0006 הוא \u0005שמת],\u0006 והשאר יהיו מותרים!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן לרבא: \u0003רב\u0004 ש\u0003אומר\u0004 הלכה זו שיש לתלות שהאיסור הוא שנפל, הריהו סבור \u0003כ\u0004שיטת \u0003ר' אליעזר. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003ר' אליעזר אומר:\u0004 כשנתערבו איברים של בעל מום באיברי עולות כשרות, \u0003אם\u0004 כבר \u0003קרב הראש של אחד מהן\u0004 — \u0003יקרבו כל הראשים כולן,\u0004 משום שאנו תולים שהראש שקרב הוא הראש הפסול.","הקשה לו רבא לרב נחמן על תירוצו זה: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' אלעזר: לא התיר ר' אליעזר\u0004 את כל הראשים להקרבה \u0003אלא\u0004 רק כאשר הם מוקרבים \u0003שנים שנים,\u0004 משום שאחד מהם בודאי מותר להקרבה, \u0003אבל\u0004 להקריב אותם \u0003אחד אחד\u0004 — \u0003לא\u0004 התיר, שמא את הפסול הוא מקריב! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 גם \u0003אנא\u0004 \u0005[אני]\u0006 שאמרתי בשם רב, להתיר את כל שאר הטבעות — \u0003תרתי קאמינא\u0004 \u0005[שתים\u0006 שתים \u0005אמרתי],\u0006 שמוכר כל פעם שתי טבעות, שאז יש לומר שאחת מהם בודאי אינה של עבודה זרה.","ועוד בענין זה, \u0003אמר רב: טבעת של עבודה זרה שנתערבה במאה טבעות\u0004 של היתר, ונאסרו כולן, \u0003ו\u0004לאחר מכן \u0003פרשו ארבעים\u0004 מהן \u0003למקום אחד, ו\u0004ה\u0003ששים\u0004 האחרות פרשו \u0003למקום אחר,\u0004 והריהן עתה שתי קבוצות נפרדות של טבעות. אם \u0003פרשה\u0004 טבעת \u0003אחת מ\u0004ה\u0003ארבעים,\u0004 והתערבה בין טבעות אחרות — \u0003אינה אוסרת\u0004 אותן. אבל אם פרשה טבעת \u0003אחת מששים\u0004 האחרות, ונתערבה בטבעות אחרות — \u0003אוסרת\u0004 אותן.","ותוהים על כך: \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 \u0003אחת מארבעים\u0004 ש\u0003לא\u0004 אוסרת? משום \u0003דאמרינן\u0004 \u0005[שאנו\u0006 תולים ו\u0005אומרים]:\u0006 \u0003איסורא ברובא איתיה\u0004 \u0005[האיסור ישנו,\u0006 נמצא, \u0005ברוב]\u0006 בתוך ששים הטבעות. אם כן אף בפרשה טבעת \u0003אחת מ\u0004ה\u0003ששים נמי אמרינן\u0004 \u0005[גם כן אומרים אנו]:\u0006 \u0003איסורא ברובא איתיה\u0004 \u0005[האיסור ישנו ברוב]\u0006 בחמישים ותשע שנותרו, וטבעת זו של היתר היא! \u0003אלא\u0004 יש לתקן את לשון השמועה, וכך לומר בה: \u0003אם פרשו ארבעים כולן למקום אחד\u0004 ונתערבו שם בתוך טבעות אחרות — \u0003אין אוסרות\u0004 את אותן טבעות אחרות, ומותר לו ליטול מן התערובת, שאנו תולים ואומרים שהטבעת האסורה נמצאת בתוך קבוצת ששים הטבעות. ואולם אם פרשו \u0003ששים\u0004 הטבעות \u0003למקום אחד\u0004 ונתערבו שם בטבעות אחרות — \u0003אוסרות\u0004 את התערובת.","ואמר רב יהודה, שמסר שמועה זו של רב: \u0003כי אמריתה קמיה\u0004 \u0005[כאשר אמרתי אותה לפני]\u0006 \u0003שמואל,\u0004 שאם נפלו הארבעים למקום אחר אינן אוסרות את הטבעות שנתערבו בהן. \u0003אמר לי: הנח ל\u0004הלכה זו מלומר אותה באיסור \u0003עבודה זרה, ש\u0004איסורה חמור ו\u0003ספיקה וספק ספיקה אסורה,\u0004 ואף הלאה והלאה \u0003עד סוף העולם.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על שמואל ממה ששנינו בברייתא, \u0003ספק עבודה זרה\u0004 — \u0003אסורה, וספק ספיקה\u0004 — \u0003מותרת. כיצד? כוס של עבודה זרה שנפל לאוצר\u0004 (מחסן) \u0003מלא כוסות\u0004 — \u0003כולן אסורין, פירש אחד מהן\u0004 מהכוסות המעורבים הללו ונפל \u0003ל\u0004בין \u0003ריבוא\u0004 (עשרת אלפים) כוסות אחרים, \u0003ומ\u0004אותו \u0003ריבוא\u0004 פרש כוס אחד ונפל \u0003ל\u0004תוך \u0003ריבוא\u0004 כוסות אחרים — \u0003מותרין.\u0004 משמע שרק ספק אסור, אך ספק ספיקא מותר!","ומשיבים: הלכה זו \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא. דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יהודה אומר: רימוני באדן,\u0004 שהם חשובים במיוחד, אם היו אסורים, הריהם \u0003אוסרין\u0004 את תערובתם אפילו \u0003בכל שהוא. כיצד? נפל אחד מהן\u0004 אפילו \u0003לתוך ריבוא\u0004 רימונים של היתר, \u0003ומ\u0004אותו \u0003ריבוא\u0004 פרש רימון אחד ונפל \u0003לריבוא\u0004 רימונים אחרים — כולם \u0003אסורין,\u0004 אף שהוא ספק ספיקא.","\u0003ר' שמעון בן יהודה אומר משום\u0004 (בשם) \u0003ר' שמעון:\u0004 אם נפל אחד מן הרימונים האסורים \u0003לריבוא\u0004 — כולם \u0003אסורין,\u0004 שאינם בטלים ברוב. אבל אם נפל אחד \u0003מ\u0004ה\u0003ריבוא ל\u0004תוך \u0003שלשה, ומ\u0004ה\u0003שלשה\u0004 הללו חזר ונפל רימון אחד \u0003למקום אחר\u0004 — \u0003מותר,\u0004 משום ספק ספיקא.","ומבררים: \u0003שמואל\u0004 ש\u0003אמר\u0004 שגם ספק ספיקא של עבודה זרה אסור, \u0003כמאן\u0004 \u0005[כ\u0006דעת \u0005מי]\u0006 מהתנאים הללו הוא סבור? \u0003אי\u0004 \u0005[אם]\u0006 סבור הוא \u0003כר' יהודה,\u0004 הרי לדעתו של ר' יהודה, כל דבר שאינו בטל מפאת חשיבותו, כגון רימוני באדן, \u0003אפילו בשאר איסורים\u0004 ספק ספיקו \u0003אסור! אי\u0004 \u0005[אם]\u0006 סבור הוא \u0003כר' שמעון,\u0004 הרי לדעתו של ר' שמעון \u0003אפילו בעבודה זרה נמי שרי\u0004 \u0005[גם כן מותר]\u0006 ספק ספיקא, שהרי לא חילק בדבריו בין איסור לאיסור!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 כי אף שלא אמר כן במפורש, \u0003שאני ליה\u0004 \u0005[שונה לו]\u0006 \u0003לר' שמעון בין עבודה זרה\u0004 שהוא מחמיר בספק ספיקה, \u0003לשאר איסורים, אלא\u0004 מעתה \u0003הא דתניא\u0004 \u0005[\u0006הלכה \u0005זו ששנויה\u0006 בברייתא\u0005]:\u0006 \u0003ספק עבודה זרה\u0004 — \u0003אסורה, וספק ספיקה\u0004 — \u0003מותרת, מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]?\u0006 \u0003לא ר' יהודה ולא ר' שמעון!\u0004","ומשיבים: \u0003לעולם\u0004 ברייתא זו כשיטת \u0003ר' שמעון\u0004 היא, שמתיר ספק ספיקא בכל האיסורים, וגם בעבודה זרה, \u0003ושמואל סבר לה\u0004 \u0005[סבור]\u0006 \u0003כר' יהודה בחדא\u0004 \u0005[ב\u0006דבר \u0005אחד],\u0006 בעבודה זרה, שספק ספיקה אסור, \u0003ופליג עליה בחדא\u0004 \u0005[וחולק עליו באחד],\u0006 שאין הלכה זו נוהגת בשאר האיסורים.","ודנים עוד בברייתא זו. \u0003אמר מר\u0004 \u0005[החכם]\u0006 ר' שמעון בר' יהודה בשם ר' שמעון: אם נפל אחד \u0003מ\u0004תערובת ה\u0003ריבוא\u0004 שנאסרה \u0003ל\u0004תוך \u0003שלשה, ומ\u0004אותם \u0003שלשה\u0004 חזר ונפל אחד \u0003למקום אחר\u0004 — \u0003מותר.\u0004"],["ושואלים: \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה,\u0006 מדוע נאמר\u0005]\u0006 שהרימון נפל לתוך \u0003שלשה?\u0004 משום \u0003דאיכא רובא\u0004 \u0005[שיש רוב]\u0006 של ההיתר כנגד הרימון שנפל מן הריבוא. ואולם אם נפל ל\u0003שנים נמי איכא רובא\u0004 \u0005[גם כן יש רוב]\u0006 כנגד האחד שנפל לתוכם! ומשיבים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"שלשה\" דקתני\u0004 \u0005[ששנינו]\u0006 — \u0003תרתי\u0004 \u0005[שנים]\u0006 של ההיתר \u0003והוא\u0004 של האיסור, שביחד הריהם שלושה. ושבים לדון בדעת שמואל, שהחמיר בספק ספיקה של עבודה זרה, כדעת מי הוא סבור.","ומציעים, \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כר' אליעזר\u0004 שמצאנו כי הוא סבור כך במסכת עבודה זרה (מט,ב).","ועוד בענין של תערובת אסורה שנפל ממנה אחד, \u0003אמר ריש לקיש: חבית של תרומה\u0004 שאסורה בשתיה למי שאינו כהן, \u0003שנתערבה במאה חביות\u0004 של חולין, וכולן אסורות, שהרי חבית סתומה אינה בטלה מפני חשיבותה (לעיל זבחים עב,ב), \u0003ונפלה אחת מהן לים המלח\u0004 — \u0003הותרו\u0004 כל החביות \u0003כולן,\u0004 משום \u0003דאמרינן\u0004 \u0005[שאומרים אנו]:\u0006 \u0003הך\u0004 \u0005[זה]\u0006 ש\u0003נפל\u0004 — \u0003דאיסורא\u0004 \u0005[של איסור]\u0006 \u0003נפל.\u0004","ומעירים: \u0003ו\u0004אף שהם נראים דומים, \u0003איצטריך\u0004 \u0005[הוצרך]\u0006 מה שאמר \u0003רב נחמן\u0004 בשם רב (בעמוד הקודם), שטבעת של עבודה זרה שנתערבה במאה טבעות ונפלה אחת מהם לים הגדול — הותרו כולן, \u0003ואיצטריך\u0004 \u0005[והוצרך]\u0006 מה שאמר \u0003ריש לקיש\u0004 כאן, שאין הם למדים זה מזה. \u0003דאי\u0004 \u0005[ש\u0006כן \u0005אם]\u0006 \u0003מ\u0004דברי \u0003רב נחמן\u0004 בלבד, \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003הני מילי\u0004 \u0005[דברים אלה,\u0006 אמורים\u0005]\u0006 דווקא בתערובת \u0003עבודה זרה,\u0004 ש\u0003אין לה מתירין,\u0004 שלא ניתן להתירה בשום אופן, ולכן מקילים בה באופן זה. \u0003אבל\u0004 תערובת \u0003תרומה,\u0004 ש\u0003יש לה מתירין,\u0004 שניתן למכור את כולה לכהנים — \u0003לא\u0004 נתיר את התערובת על סמך ההנחה שהאיסור הוא זה שנפל.","\u0003ו\u0004מן הצד האחר, \u0003אי\u0004 \u0005[אם]\u0006 \u0003מ\u0004דברי \u0003ריש לקיש\u0004 בלבד, \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 דווקא ב\u0003חבית\u0004 שנפלה הקילו, משום \u0003דמינכרא\u0004 \u0005[שניכרת]\u0006 \u0003נפילתה,\u0004 וידעו הכל שבגלל שנפלה חבית אחת הותרו שאר החביות, ולא יבואו להתיר תערובת חביות שכזו אף בלא נפילה. \u0003אבל טבעת דלא מינכרא\u0004 \u0005[שאין ניכרת]\u0006 \u0003נפילה\u0004 — \u0003לא\u0004 נתיר את השאר, לכן \u0003צריכי\u0004 \u0005[צריכים]\u0006 שני הדברים להיאמר.","ומביאים בענין זה מה ש\u0003אמר רבה: לא התיר ריש לקיש אלא\u0004 ב\u0003חבית\u0004 תרומה, \u0003דמינכרא\u0004 \u0005[שניכרת]\u0006 \u0003נפילתה, אבל תאינה\u0004 שנפלה מתוך תערובת תאנים, שהיתה בהן תאנה של תרומה — \u0003לא\u0004 מתירה נפילה זו את השאר, שקטנה היא, ואין נפילתה ניכרת. \u0003ורב יוסף אמר: אפילו תאינה\u0004 שנפלה מתירה את כל התערובת, משום ש\u0003כ\u0004דרך ש\u0003נפילתה\u0004 של תאנה אחת אוסרת את כל התערובת, \u0003כך עלייתה\u0004 (יציאתה) של תאנה אחת מתוכן מתירה את הכל.","\u0003אמר ר' אלעזר: חבית\u0004 יין \u0003של תרומה\u0004 האסורה בשתיה לזרים \u0003שנפלה\u0004 ונתערבה \u0003במאה חביות\u0004 יין של חולין, אינה בטילה בהן במאה כדין תרומה, שכן חבית סתומה דבר חשוב הוא, ואינו בטל. מה יעשה? \u0003פותח אחד מהן,\u0004 כך ששוב אין בה חשיבות, ונוהג בה דין ביטול רגיל של תרומה, \u0003ונוטל הימנה\u0004 יין \u0003כדי דימועה\u0004 (תערובתה), כלומר, אחד ממאה, שהיא הכמות היחסית של התרומה שיש בתערובת החביות, ונותן לכהן, \u0003ושותה\u0004 את שאר היין שבחבית.","\u0003יתיב\u0004 \u0005[יושב\u0006 היה\u0005]\u0006 \u0003רב דימי וקאמר לה להא שמעתא\u0004 \u0005[ואומר את ההלכה הזו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן: גמע ושתי קא חזינא הכא\u0004 \u0005[גומע ושותה רואה אני כאן],\u0006 נוסח דברים אלה מורה שכך עושים לכתחילה. והרי תערובת זו אסורה היא! \u0003אלא אימא\u0004 \u0005[אמור]\u0006 כך: בדיעבד, אם \u0003נפתחה אחת מהן\u0004 — \u0003נוטל הימנה כדי דימוע, ושותה.\u0004","ועוד באותו ענין, \u0003אמר ר' אושעיא: חבית\u0004 יין \u0003של תרומה שנתערבה במאה וחמשים חביות\u0004 יין של חולין, \u0003ונפתחו מאה מהן\u0004 — \u0003נוטל הימנה\u0004 מכל חבית וחבית \u0003כדי דימועה,\u0004 ספק שיש בה. ונותנו לכהן, \u0003ושותה\u0004 את השאר. \u0003ו\u0004לאחר שנפתחו כבר מאה חביות, \u0003שאר\u0004 חמישים החביות \u0003אסורין עד שיפתחו\u0004 וינטל מהן כדי דימוע, כי \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 ש\u0003איסורא ברובא איתיה\u0004 \u0005[האיסור נמצא ברוב\u0006 במאה שנפתחו\u0005],\u0006 וזו שתיפתח היא מן הסתם מן ההיתר.","ושבים לבירור דברי משנתנו. שנינו בה: כל הזבחים שנתערבו בחטאות המתות... \u0003הרובע והנרבע,\u0004 במוקצה ונעבד, באתנן ומחיר, בכלאים ובטריפה. ושואלים: \u0003בשלמא כולהו\u0004 \u0005[נניח כולם\u0006 כל המנויים ברשימה זו\u0005]\u0006 \u0003לא ידיע\u0004 \u0005[ידוע,\u0006 ניכר\u0005]\u0006 איסורם, שהרי אין בו סימנים המלמדים על איסורו, ולכן תיתכן בהם תערובת. \u0003אלא האי\u0004 \u0005[זו]\u0006 ה\u0003טריפה\u0004 השנויה במשנתנו, \u0003היכי דמי\u0004 \u0005[כיצד בדיוק מדובר]?\u0006 \u0003אי ידיע ליה\u0004 \u0005[אם\u0006 הוא \u0005מכיר אותו]\u0006 את בעל החיים הטריפה שנתערב, שניכר הפגם שאירע בו — \u0003ליתי ולישקליה\u0004 \u0005[שיבוא ויקח אותו]\u0006 משם, ויהיו כולם מותרים! \u0003אי לא ידע ליה\u0004 \u0005[אם אינו מכיר אותו]\u0006 — \u0003מנא ידע דאיערב\u0004 \u0005[מנין\u0006 הוא \u0005יודע\u0006 בכלל \u0005שנתערב]?\u0006","\u0003אמרי דבי\u0004 \u0005[אומרים\u0006 חכמי \u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ינאי: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 \u0003כגון דאיערב\u0004 \u0005[שהתערבה]\u0006 בהמה \u0003נקובת הקוץ\u0004 שנוצר בגופה נקב על ידי קוץ, ואינה נטרפת בכך, \u0003בדרוסת הזאב\u0004 שנעץ בה זאב את ציפורניו ונטרפה בכך, שכיון שיש בשתיהן נקב אין דרך לזהות את הטריפה.","\u0003ריש לקיש אמר\u0004 באופן שונה: \u0003[כגון] דאיערב\u0004 \u0005[שהתערבה]\u0006 בהמה כשרה \u0003בנפולה\u0004 כלומר, בבהמה שנפלה ממקום גבוה, שהיא נאסרת בכך, שמא טריפה היא, אבל אין עליה סימן חיצוני. ומקשים: \u0003נפולה נמי\u0004 \u0005[גם כן]\u0006 \u0003ליבדקה\u0004 \u0005[שיבדוק אותה]\u0006 אם היא הולכת בעצמה, ואז כשירה היא! ומשיבים: לדעתו עדיין ספק טריפה היא, ואסורה בהקרבה, שכן \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 כדעת האומר בענין נפולה: אם \u0003עמדה\u0004 על רגליה בעצמה — \u0003צריכה\u0004 לחיות \u0003מעת לעת\u0004 (יממה) כדי שניתן יהיה להכשירה. ומכל מקום, גם אם \u0003הלכה\u0004 ואין צריך להמתין מעת לעת — \u0003צריכה בדיקה\u0004 פנימית לאחר שנשחטה כדי להכשירה.","ואילו \u0003ר' ירמיה אמר\u0004 הסבר אחר בענין הטריפה שנתערבה שבמשנתנו: מדובר \u0003כגון דאיעריב\u0004 \u0005[שנתערבה]\u0006 בהמה כשירה \u0003בולד\u0004 של \u0003טריפה,\u0004 ובו הרי אין כל סימן טריפה, \u0003ו\u0004שיטת \u0003ר' אליעזר היא,\u0004 ש\u0003אמר: ולד טריפה לא יקרב לגבי מזבח.\u0004","ומסבירים מדוע נחלקו חכמים אלה בהסבר המשנה: \u0003כולהו\u0004 \u0005[כולם,\u0006 ריש לקיש ור' ירמיה\u0005]\u0006 \u0003כ\u0004הסברו של \u0003ר' ינאי\u0004 שהתערבה נקובת הקוץ בדרוסת הזאב, \u0003לא אמרי\u0004 \u0005[אינם אומרים],\u0006 משום שלדעתם \u0003בין נקובת הקוץ לדרוסת הזאב מידע ידיע\u0004 \u0005[ידוע,\u0006 ניכר, ההבדל\u0005],\u0006 שהרי \u0003האי\u0004 \u0005[זה,\u0006 נקב של דריסת הזאב\u0005]\u0006 — \u0003משיך\u0004 \u0005[משוך,\u0006 מוארך\u0005],\u0006 \u0003ו\u0004אילו \u0003האי\u0004 \u0005[זה,\u0006 נקב של קוץ\u0005]\u0006 — \u0003עגיל\u0004 \u0005[עגול].\u0006","ר' ינאי ור' ירמיה, \u0003כ\u0004הסברו של \u0003ריש לקיש\u0004 שנתערבה בנפולה, \u0003לא אמרי\u0004 \u0005[אינם אומרים],\u0006 כי \u0003קסברי\u0004 \u0005[סבורים הם]\u0006 בענין נפולה, כדעת האומר שאם \u0003עמדה\u0004 — \u0003אינה צריכה מעת לעת\u0004 אלא בדיקה, ואם \u0003הלכה\u0004 — \u0003אינה צריכה\u0004 כלל \u0003בדיקה\u0004 נוספת. ואם כן, ניתן לבדוק את הבהמות שנתערבו, שאם הן מהלכות — כולן כשרות.","ר' ינאי וריש לקיש, \u0003כ\u0004הסברו של \u0003ר' ירמיה\u0004 שנתערב בולד טריפה, \u0003לא אמרי\u0004 \u0005[אינם אומרים],\u0006 משום ש\u0003כ\u0004דעת \u0003ר' אליעזר,\u0004 שאין הלכה כמותו, \u0003לא מוקמי\u0004 \u0005[מעמידים\u0006 משנה\u0005].\u0006","ועוד בבירור המשנה. שנינו בה: נתערבו \u0003קדשים בקדשים מין במינו\u0004 — זה יקרב לשם מי שהוא, וזה יקרב לשם מי שהוא. ומקשים על כך: \u0003והא בעי\u0004 \u0005[והרי צריך]\u0006 \u0003סמיכה\u0004 של הבעלים על ראש קרבנו, ובמקרה זה אי אפשר לקיימה, שהרי אין אנו יודעים מיהו הבעלים!","\u0003אמר רב יוסף:\u0004 מדובר כאן \u0003בקרבן נשים\u0004 שאינו טעון סמיכה. ותמהים: \u0003אבל בקרבן אנשים\u0004 — \u0003לא\u0004 נוהג הדין שבמשנתנו, ואין תקנה לקדשים שנתערבו מין במינו?"],["\u0003איתיביה\u0004 \u0005[הקשה לו\u0006 לרב יוסף\u0005]\u0006 \u0003אביי\u0004 ממה ששנינו בברייתא: \u0003קרבן\u0004 של \u0003יחיד שנתערב בקרבן\u0004 של \u0003יחיד, ו\u0004כן \u0003קרבן ציבור שנתערב בקרבן ציבור,\u0004 או \u0003קרבן יחיד וקרבן ציבור שנתערבו זה בזה,\u0004 ואין ניכרים זה מזה — \u0003נותן\u0004 הכהן \u0003ארבע מתנות\u0004 דם, \u0003מכל אחד ואחד\u0004 מהם, שבכך יוצא ידי חובת כולם. \u0003ואם נתן מתנה מכל אחד\u0004 — \u0003יצא\u0004 ידי חובה. \u0003ואם נתן ארבע\u0004 מתנות \u0003מכולן\u0004 יחד — \u0003יצא.\u0004","\u0003במה דברים אמורים\u0004 שנותן לכתחילה מדמו של כל אחד ואחד? \u0003שנתערבו\u0004 הקרבנות הללו בעודם \u0003חיין\u0004 (לפני שהוקרבו), ויכול הכהן לתת ארבע מתנות מדמו של כל אחד ואחד בנפרד. \u0003אבל\u0004 אם \u0003נתערבו שחוטין\u0004 שנבלל דמם בכלי אחד — \u0003נותן\u0004 הכהן \u0003ארבע מתנות מכולן\u0004 יחד.","\u0003ו\u0004מכל מקום \u0003אם נתן מתנה אחת מכולן\u0004 — \u0003יצא,\u0004 שכל הקרבנות הניתנים על המזבח החיצון, אם נתן מדמם נתינה אחת בלבד — יצא ידי חובתו. \u0003רבי אומר: רואין\u0004 (מודדים) \u0003את המתנה\u0004 שנתן מכולם, \u0003אם יש בה כדי\u0004 שיעור נתינה \u0003לזה וכדי לזה\u0004 — \u0003כשרה, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003פסולה.\u0004","על כל פנים למדנו מכאן שקרבנות חיים שנתערבו — כל אחד קרב לשם בעליו, למרות שקרבנות של אנשים הם, וצריכים סמיכה, שהרי \u0003קתני\u0004 \u0005[הוא שונה\u0006 כאן\u0005]\u0006 קרבן \u0003יחיד דומיא\u0004 \u0005[בדומה]\u0006 לקרבן \u0003ציבור, מה\u0004 קרבן \u0003ציבור\u0004 המדובר הוא בקרבנם של \u0003גברי\u0004 \u0005[אנשים],\u0006 שהרי אנשים מקריבים אותו, ולא נשים, \u0003אף\u0004 קרבן של \u0003יחיד\u0004 מדובר בשל \u0003גברי\u0004 \u0005[אנשים]\u0006 ולא נשים. וקשה איפוא לרב יוסף!","\u0003אמר רבא\u0004 לאביי בדחיית קושייתו זו: \u0003ותסברא הא מתרצתא\u0004 \u0005[ו\u0006כי \u0005סבור אתה\u0006 שברייתא \u0005זו מיושבת,\u0006 נטולת קושיות\u0005]\u0006 \u0003היא,\u0004 שאתה יכול להוכיח ממנה? והרי \u0003דקתני\u0004 \u0005[\u0006מה \u0005ש\u0006הוא \u0005שונה]\u0006 בה: \u0003במה דברים אמורים\u0004 שצריך לתת מדמו של כל אחד ואחד? \u0003כשנתערבו חיין, אבל נתערבו שחוטין\u0004 — \u0003לא,\u0004 יש לשאול על כך: \u0003מה לי חיים מה לי שחוטין?\u0004 וכי בזה תלוי ההבדל? הרי אף בשחוטים, אם היה דמו של כל אחד בכלי לעצמו, ואין אנו יודעים מהו דמו של כל קרבן — צריך הכהן לתת מכל אחד ואחד!","\u0003אלא\u0004 \u0003הכי קאמר\u0004 \u0005[כך אומר\u0006 התנא שבברייתא\u0005]:\u0006 \u0003במה דברים אמורים\u0004 שנותן מתנה מכל אחד? \u0003שנתערבו שחוטין כעין חיים\u0004 כלומר \u0003בכוסות\u0004 שדמו של כל קרבן נמצא בכוס לעצמה, \u0003אבל בבולל\u0004 שנתערבו הדמים זה בזה לתוך כוס אחת — \u0003נותן ארבע מתנות לכולן, ואם נתן מתנה אחת לכולן\u0004 — \u0003יצא.\u0004 ואין איפוא ראייה מן הברייתא שסמיכה אינה מעכבת בקרבנות שנתערבו, שהרי מדובר בה כשנתערבו לאחר סמיכה.","שנינו בברייתא זו, \u0003רבי אומר: רואין את המתנה, אם יש בה כדי לזה וכדי לזה\u0004 — \u0003כשרה, ואם לא\u0004 — \u0003פסולה.\u0004 ושואלים על כך: \u0003ומי אית ליה\u0004 \u0005[והאם יש לו]\u0006 \u0003לרבי האי סברא\u0004 \u0005[סברה זו]\u0006 שצריך שיהא בדם שיעור נתינה? \u0003והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 בענין מי חטאת (של פרה אדומה) שנפלו לתוכם מים שפסולים להזאה, \u0003אמר רבי: לדברי ר' אליעזר,\u0004"],["\u0003הזאה כל שהיא\u0004 ממי חטאת על האדם הטמא הריהי \u0003מטהרת אותו\u0004 מטומאתו, שכן \u0003הזאה אינה צריכה שיעור\u0004 כדי לטהר. וכן \u0003הזאה\u0004 ש\u0003מחצה\u0004 שבה \u0003כשר\u0004 להזאה \u0003ומחצה פסול\u0004 להזאה, גם היא מטהרת!","ומשיבים: \u0003לדבריו\u0004 של \u0003ר' אליעזר קאמר\u0004 \u0005[אומר]\u0006 רבי שהזאה אינה צריכה שיעור, אבל הוא עצמו אינו סבור כן. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 תירוץ אחר: יש להבדיל ולומר, \u0003הזאה\u0004 של מי חטאת \u0003לחוד, ונתינה\u0004 של דם \u0003לחוד,\u0004 להזאה אין צריך שיעור ולנתינה יש שיעור מסויים.","שנינו במשנה: \u0003נתערבו\u0004 שאר קרבנות \u0003בבכור ומעשר,\u0004 שאינם נפדים ואינם נמכרים גם אם נפל בהם מום, מה יעשו? ירעו כולם עד שיפול בהם מום, ויאכלו כבכור וכמעשר שנפל בהם מום, שאין מוכרים ואין שוחטים אותם בשוק, ואין שוקלים את בשרם במשקל, שיש בכך זלזול בקדשים. ומביאים דיון בענייני בכור, שהוזכרה בו משנתנו. \u0003אמר רמי בר חמא: בכור\u0004 בעל מום, \u0003ל\u0004שיטת \u0003בית שמאי\u0004 במסכת בכורות, שגם לאחר שנפל בו מום אסור הכהן לאוכלו בטומאה, ולכן \u0003אין מאכילין\u0004 אותו \u0003ל\u0004נשים \u0003נדות, תמורתו\u0004 (שאמר בעל הבכור על בהמת חולין שיש לו: \"הרי זו תחת זו\") \u0003מהו\u0004 דינה? האם היא מותרת באכילה לנשים נדות כשנופל בה מום?","ועוד שאל רמי בר חמא: ה\u0003בכור\u0004 עצמו \u0003אינו נפדה\u0004 גם כשנפל בו מום, ואולם \u0003תמורתו מהו\u0004 שתיפדה? ועוד שאל: ה\u0003בכור\u0004 עצמו, גם כשנופל בו מום \u0003אינו נשקל בליטרא\u0004 (במשקל, כדרך בשר הנמכר בשוק), כדין שאר קדשים שנפל בהם מום ונפדו, \u0003תמורתו מהו\u0004 דינה לענין זה? \u0003אמר רבא\u0004 בפתרון לבעיות אלה, \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003בכור ומעשר\u0004 — גם \u0003משהוממו\u0004 (משעה שנפל בהם מום) \u0003עושין תמורה, ותמורתן כיוצא בהן.\u0004","ועוד \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רמי בר חמא התפיס\u0004 הכהן \u0003בכור\u0004 בעל מום כהקדש \u0003לבדק הבית,\u0004 שההקדש ייהנה מדמיו, \u0003מהו שישקול\u0004 את בשרו \u0003בליטרא?\u0004 וצדדי השאלה: האם במקרה זה, השיקול של \u0003רווחא\u0004 \u0005[רווח]\u0006 של ה\u0003הקדש עדיף,\u0004 וראוי איפוא שישקלו את בשר הבכור בליטרא, שכן בדרך זו ניתן להשיג מחיר גבוה יותר עבורו. \u0003או דלמא\u0004 \u0005[שמא]\u0006 השיקול של \u0003זילותא\u0004 \u0005[הזלזול]\u0006 ב\u0003בכור\u0004 \u0003עדיף,\u0004 ולא ישקלוהו בליטרא, אף שממעט בכך מרווח ההקדש?","\u0003אמר ר' יוסי בר זבידא, תא שמע\u0004 \u0005[בוא ושמע]\u0006 ראייה ממה ששנינו במשנתנו: \u0003נתערבו\u0004 שאר הקרבנות \u0003בבכור ובמעשר\u0004 — \u0003ירעו\u0004 כולם \u0003עד שיסתאבו\u0004 (שיפול בהם מום), \u0003ויאכלו כבכור וכמעשר,\u0004 שאינם נשקלים בליטרא. והרי בדרך זו נגרם הפסד להקדש, שאין שאר הקרבנות נמכרים במחיר הגבוה. \u0003לאו למימרא\u0004 \u0005[האם לא\u0006 נסיק \u0005נאמר\u0006 מכאן\u0005]\u0006 שבכור בעל מום שהוקדש לבדק הבית \u0003אינו נשקל בליטרא,\u0004 אף שנגרם בכך מיעוט רווח להקדש?","\u0003רב הונא ור' חזקיה תלמידי ר' ירמיה אמרי\u0004 \u0005[אומרים]\u0006 שניהם בדחיית ראייה זו: \u0003מי דמי\u0004 \u0005[האם דומה\u0006 הדבר\u0005]?\u0006 \u0003התם\u0004 \u0005[שם,\u0006 במשנתנו\u0005]\u0006 מדובר במצב בו יש \u0003שתי קדושות\u0004 נפרדות (קדושת הבכור וקדושת שאר קרבנות) \u0003ושני גופין\u0004 נפרדים (בהמת הבכור ובהמת קדשים אחרת), ובמקרה שכזה אין מזלזלים בקדושת הבכור בגלל הבהמה האחרת שנתערבה בה. ואילו \u0003הכא\u0004 \u0005[כאן,\u0006 במתפיס בכור לבדק הבית\u0005]\u0006 מדובר במצב בו יש \u0003שתי קדושות\u0004 (קדושת בכור וקדושת בדק הבית) \u0003ו\u0004שתיהן נמצאות ב\u0003גוף אחד\u0004 (בהמת הבכור). ואולי במקרה זה, שקדושת בדק הבית עצמה מצויה בבכור זה, נתיר לשוקלו בליטרא, משום רווח ההקדש!","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003ר' יוסי בר אבין:\u0004 כיצד ניתן להעלות על הדעת שיכול אדם באמצעות התפסה לבדק הבית להתיר איסורים הנוגעים לבכור? \u0003מה\u0004 \u0003אילו אמר \"הפדו לי\"\u0004 כלומר שרצונו לפדות \u0003בכור שהתפיסו\u0004 קודם לכן \u0003לבדק הבית,\u0004 כדי שירויח בכך ההקדש, \u0003כלום שומעין לו?\u0004 ודאי שלא, משום שמן התורה אין פדיון לבכור. ותוהים על עצם השוואה זו: וכי יכול אתה להקשות ממי שאומר \u0003\"הפדו\u0004 לי\"? והרי \u0003רחמנא אמר\u0004 \u0005[התורה אמרה]\u0006 בדין הבכור: \"אך בכור שור או בכור כשב או בכור עז \u0003לא תפדה\u0004 קודש הם\" (במדבר יח, יז). ואילו שקילה בליטרא — אין בה איסור תורה!","\u0003אלא\u0004 יש לפתור את שאלת רמי בר חמא במה ש\u0003אמר ר' אמי:\u0004 \u0003כלום הקנה זה\u0004 \u0003אלא מה שקנו לו?\u0004 וכשם שהכהן שהתפיס את הבכור לבדק הבית אינו יכול לשוקלו בליטרא ולהרויח, אף ההקדש שקיבל מהכהן אינו יכול לעשות כן.","שנינו במשנה: \u0003הכל,\u0004 כל מיני הקדשים, \u0003יכולין להתערב\u0004 זה בזה, שיש בהם בהמות שוות במינן ובגודלן, חוץ מחטאת ואשם. ושואלים: \u0003מאי שנא\u0004 \u0005[במה שונים]\u0006 \u0003חטאת ואשם? דהאי\u0004 \u0005[שזה,\u0006 האשם\u0005]\u0006 הוא תמיד \u0003זכר והאי\u0004 \u0005[וזו,\u0006 החטאת\u0005]\u0006 היא תמיד \u0003נקבה,\u0004 אם כן","\u0003חטאת ועולה נמי\u0004 \u0005[גם כן]\u0006 אינם מתערבים, שהרי העולה היא תמיד זכר, והחטאת היא תמיד נקבה! ומשיבים: \u0003איכא\u0004 \u0005[יש]\u0006 \u0003שעיר נשיא\u0004 שהוא חטאת זכר, וכן מקריבים שעיר לעולה. ומוסיפים: ומכל מקום באשם אין שעיר הנשיא יכול להתערב, למרות ששניהם זכרים, שכן \u0003האי\u0004 \u0005[זה\u0006 השעיר\u0005]\u0006 יש לו \u0003שיער\u0004 ישר, \u0003ו\u0004אילו \u0003האי\u0004 \u0005[זה\u0006 האשם\u0005]\u0006 אינו בא אלא מן הכבשים או האילים, שיש להם \u0003צמר,\u0004 שהוא מקורזל.","ושואלים על המשנה: והרי \u0003פסח ואשם נמי לא מיערב\u0004 \u0005[גם כן אינם יכולים להתערב],\u0006 שכן \u0003האי\u0004 \u0005[זה\u0006 הפסח\u0005]\u0006 הוא \u0003בן שנה\u0004, \u0003ו\u0004אילו \u0003האי\u0004 \u0005[וזה\u0006 האשם\u0005]\u0006 הוא \u0003בן שתי שנים!\u0004 ומשיבים: \u0003איכא\u0004 \u0005[יש]\u0006 \u0003אשם נזיר ואשם מצורע\u0004 שהם בני שנה. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 ההבדל שבין בן שנה ובן שנתיים אינו כה ברור, שכן \u0003איכא\u0004 \u0005[יש]\u0006 \u0003בן שנה דמיחזי\u0004 \u0005[שנראה]\u0006 \u0003כבן שתי שנים, ואיכא\u0004 \u0005[ויש]\u0006 \u0003בן שתים דמיחזי\u0004 \u0005[שנראה]\u0006 \u0003כבן שנה.\u0004","קרבן \u0003אשם שנתערב ב\u0004קרבן \u0003שלמים,\u0004 ואין יודעים מיהו כל קרבן. ומעתה כיון שדיני האשם והשלמים שונים זה מזה, בשחיטה ובאכילה, מה יעשו? \u0003ר' שמעון אומר: שניהם ישחטו בצפון\u0004 העזרה, שכן האשם שחיטתו בצפון בלבד, ואילו השלמים שחיטתם בכל מקום בעזרה. \u0003ויאכלו\u0004 שניהם \u0003כ\u0004דינו של ה\u0003חמור שבהן\u0004 שהוא האשם: בעזרה שבמקדש בלבד (ולא בכל ירושלים, כדין השלמים), לזכרי כהונה בלבד (ולא לכל אדם, כדין השלמים), ובמשך יום ולילה בלבד (ולא בשני ימים ולילה, כדין השלמים).","\u0003אמרו לו\u0004 חכמים לר' שמעון: אין עושים כן, שהרי \u0003אין מביאין קדשים לבית הפסול,\u0004 כלומר, אין גורמים להם להיפסל. ולשיטתך, נמצאים השלמים נאסרים מלהיאכל לאחר יום אחד, ונפסלים כנותר. אלא, ירעו שניהם עד שיפול בהם מום, ויימכרו, ויביא אשם ושלמים, כל אחד בדמי היפה שבשניהם.","ומוסיפה המשנה: גם לדעת חכמים, אם \u0003נתערבו חתיכות\u0004 בשר מקרבן זה \u0003בחתיכות\u0004 בשר מקרבן אחר, \u0003קדשי קדשים בקדשים קלים,\u0004 וכן אם נתערבו חתיכות מקרבנות \u0003הנאכלין ליום אחד\u0004 \u0003ב\u0004חתיכות מקרבנות ה\u0003נאכלין לשני ימים ולילה,\u0004 הואיל ואין להם תקנה כמו בהמות שנתערבו — \u0003יאכלו\u0004 כולם \u0003כחמור שבהן.\u0004","שנינו במשנתנו שחכמים חולקים על ר' שמעון מחמת הכלל שאין מביאים קדשים לבית הפסול. ובענין זה מסופר, \u0003תני\u0004 \u0005[שנה]\u0006 ה\u0003תנא\u0004 (שונה המשניות והברייתות שבבית המדרש) \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003רב\u0004 ברייתא זו: תבואה של \u0003שביעית אין לוקחין בדמיה\u0004 פירות של \u0003תרומה\u0004 של שנה אחרת, \u0003מפני\u0004 שבכך גורמים \u0003שממעטין באכילתה\u0004 של התרומה, שהרי פירות שביעית ודמיהם, מותרים באכילה רק עד זמן הביעור, כאשר לא נותר מאותו המין בשדה, ואילו תרומה מותרת לעולם.","\u0003אמרוה\u0004 לברייתא זו \u0003רבנן קמיה\u0004 \u0005[חכמים לפני]\u0006 \u0003רבא [רבה]\u0004 והסבירו אותה: \u0003הא\u0004 \u0005[\u0006ברייתא \u0005זו]\u0006 היא ש\u0003לא כ\u0004שיטת \u0003ר' שמעון\u0004 שבמשנתנו, \u0003דאי\u0004 \u0005[שאם]\u0006 היא \u0003כר' שמעון, האמר\u0004 \u0005[הרי אמר\u0006 עולה מדבריו במשנתנו\u0005]\u0006 ש\u0003מביאין קדשים לבית הפסול!\u0004","\u0003אמר להו\u0004 \u0005[להם]\u0006 רבה: \u0003אפילו תימרו\u0004 \u0005[תאמרו]\u0006 שהיא כשיטת \u0003ר' שמעון\u0004 במשנתנו, יש לומר כי \u0003הני מילי\u0004 \u0005[דברים אלה,\u0006 שמותר להביא קדשים לבית הפסול\u0005]\u0006 נאמרו רק במקרה \u0003דאיעבד\u0004 \u0005[ש\u0006כבר \u0005נעשה\u0006 דבר\u0005],\u0006 כגון במשנתנו שהתערבו הקדשים זה בזה, ואולם לגרום \u0003לכתחילה\u0004 להבאה לבית הפסול, כגון בקניית פירות תרומה בדמי שביעית, \u0003לא\u0004 מתיר גם ר' שמעון. ושואלים: \u0003ו\u0004האם \u0003לכתחילה לא\u0004 התיר ר' שמעון? \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי\u0004 לרבה"],["ממה ששנינו במשנה לגבי דרך אכילת הקרבנות: \u0003ו\u0004ב\u0003כולן רשאין כהנים לשנות באכילתן\u0004 לאוכלם בכל דרך שירצו: \u0003לאכלן צלויין\u0004 באש, או \u0003שלוקין\u0004 (מבושלים בישול יתר) \u0003ומבושלין\u0004 (בישול רגיל), \u0003ו\u0004רשאים הכהנים \u0003לתת לתוכן תבלי חולין ו\u0004כן \u0003תבלי תרומה,\u0004 אלו \u0003דברי ר' ישמעאל.\u0004 משמע שמותר לכתחילה להוסיף תבלים של תרומה לקרבנות, אף שבכך מתמעט זמן אכילת התרומה כזמן אכילת הקרבנות! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה לאביי: \u0003הנח לתרומת תבלין,\u0004 אין להביא ראיה ממנה לענייננו, שהרי כל עצמה של תרומה זו אינו אלא מ\u0003דרבנן\u0004 \u0005[\u0006מ\u0005דברי סופרים].\u0006","חזר אביי ו\u0003איתיביה\u0004 \u0005[הקשה לו\u0006 לרבה\u0005]\u0006 ממה ששנינו במשנה: \u0003אין\u0004 הכהנים \u0003לוקחין\u0004 (קונים) \u0003תרומה בכסף מעשר\u0004 שני, \u0003מפני ש\u0004בכך הוא \u0003ממעט באכילתה\u0004 של התרומה. שכן התרומה נאכלת בכל מקום ומותרת אף לאונן, בעוד שמעשר שני (ומה שקונים בדמיו) מותר באכילה רק בירושלים ואסור לאונן. \u0003ור' שמעון מתיר\u0004 לקנותה בכסף מעשר שני. הרי שר' שמעון מתיר אף לכתחילה להביא תרומה לבית הפסול! \u0003אישתיק ליה\u0004 \u0005[שתק לו\u0006 רבה\u0005]\u0006 ולא השיב לאביי.","\u0003כי אתא לקמיה\u0004 \u0005[כאשר בא\u0006 אביי \u0005לפני]\u0006 \u0003רב יוסף\u0004 ומסר לו את דברי רבה ואת קושייתו עליו, \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא תותביה מהא\u0004 \u0005[תקשה לו מזו]\u0006 ששנינו: \u0003אין מבשלין ירק של שביעית בשמן של תרומה, שלא יביאו\u0004 על ידי כך \u0003קדשים\u0004 (תרומה) \u0003לבית הפסול,\u0004 שיצטרך לבער את שמן התרומה כשיגיע זמן ביעור פירות שביעית, \u0003ור' שמעון מתיר.\u0004 הרי שלשיטת ר' שמעון מותר אף לכתחילה להביא קדשים לבית הפסול!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: ולאו מי אותביתיה מהא\u0004 \u0005[ו\u0006האם \u0005לא הקשיתי לו\u0006 לרבה \u0005מזו]\u0006 של \u0003תבלין\u0004 תרומה, \u0003ואמר לי: הנח לתרומת תבלין\u0004 שאינה אלא מ\u0003דרבנן\u0004 \u0005[מדברי סופרים]?\u0006 \u0003הכא נמי\u0004 \u0005[כאן גם כן,\u0006 בענין ירק שביעית\u0005]\u0006 יכול הוא להשיב על קושייתי זו ולומר ש\u0003תרומה\u0004 זו שמדובר עליה \u0003תרומת ירק\u0004 היא, שאינה אלא מ\u0003דרבנן\u0004 \u0005[מדברי סופרים].\u0006 אמר לו רב יוסף לאביי: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שמדובר במשנה זו בתרומת ירק, \u0003איפכא מיבעיא ליה למיתני\u0004 \u0005[ההיפך היה צריך לו\u0006 לתנא \u0005לשנות]\u0006 במשנה זו, וכך לומר: \"אין מבשלים \u0003ירק של תרומה בשמן של שביעית\"!\u0004 אלא וודאי בשמן תרומה מדובר, שתרומתו מן התורה. ואם כן, יכול אתה להקשות ממשנה זו על רבה!","חזר ואמר אביי לרב יוסף: \u0003ולאו מי אותביתיה ממתניתין\u0004 \u0005[ו\u0006האם \u0005לא הקשיתי לו\u0006 לרבה \u0005ממשנתנו]\u0006 ששנינו בה ש\u0003מתיר ר' שמעון\u0004 להביא קדשים לבית הפסול, \u0003ואמר לי\u0004 שאין להביא ראיה ממנה, כיון שמדובר במקרה \u0003דאיערב\u0004 \u0005[ש\u0006כבר \u0005נתערבו\u0006 האשם והשלמים\u0005]\u0006 וכבר נעשה הדבר? \u0003הכא נמי דאיערב\u0004 \u0005[כאן גם כן\u0006 מדובר \u0005ש\u0006כבר \u0005התערב\u0006 שמן התרומה בירק השביעית\u0005],\u0006 ולכן הוא מתיר לבשלם יחד, אבל אין ראיה שהוא מתיר לעשות כן לכתחילה.","ושואלים: \u0003אי דאיערב\u0004 \u0005[אם\u0006 מדובר במקרה \u0005ש\u0006כבר \u0005התערב],\u0006 \u0003מאי טעמייהו דרבנן\u0004 \u0005[מה טעמם של חכמים]\u0006 האוסרים לבשלם? ומשיבים: \u0003מידי דהוה\u0004 \u0005[כמו שהוא\u0006 הדין\u0005]\u0006 לשיטתם במשנתנו, במקרה של \u0003אשם ושלמים\u0004 שנתערבו, שאינם מתירים לבשלם, ולהביא את בשר השלמים לידי פסול.","ומקשים: \u0003מי דמי\u0004 \u0005[האם דומים\u0006 הדברים\u0005]?\u0006 \u0003התם\u0004 \u0005[שם],\u0006 בתערובת אשם ושלמים, \u0003אית ליה תקנתא\u0004 \u0005[יש לו תקנה]\u0006 \u0003ברעייה,\u0004 שירעו כולם עד שיפול בהם מום, ויימכרו, ויביאו בדמי היפה שבהם קרבן אשם וכן קרבן שלמים. ואילו \u0003הא\u0004 \u0005[זה],\u0006 בתערובת שמן תרומה בירק שביעית, \u0003לית ליה תקנתא\u0004 \u0005[אין לו תקנה]\u0006 \u0003ב\u0004דרך הדומה ל\u0003רעייה!\u0004","ואם יש להשוות מקרה זה, של שמן תרומה שכבר נתערב בירק שביעית, לתערובת קדשים, \u0003הא לא דמי\u0004 \u0005[זה אינו דומה]\u0006 \u0003אלא ל\u0004הלכה השניה שבמשנתנו, הדנה ב\u0003חתיכה\u0004 של קדשי קדשים \u0003ש\u0004נתערבה \u0003בחתיכות\u0004 קדשים קלים. ובמקרה זה גם חכמים מודים ש\u0003כיון דלית תקנתא\u0004 \u0005[שאין תקנה]\u0006 לחתיכות המעורבות, ש\u0003אוכל\u0004 את כולן \u0003כ\u0004דין ה\u0003חמור שבהן!\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבינא: מי דמי\u0004 \u0005[האם דומים\u0006 הדברים\u0005]?\u0006 והרי \u0003חתיכה ש\u0004נתערבה \u0003בחתיכות לית לה תקנתא\u0004 \u0005[אין לה תקנה]\u0006 \u0003כלל,\u0004 ולכן התירו חכמים לאכלם כחמור שבהם. ואילו \u0003האי אית ליה תקנתא\u0004 \u0005[זה,\u0006 שמן של תרומה, \u0005יש לו תקנה]\u0006 \u0003בסחיטה,\u0004 שיסחוט את השמן מן הירק! ואם כן, מקרה זה אכן דומה למקרה שנתערבו קרבנות אשם ושלמים שיש להם תקנה, ומשום כך אסרו חכמים לבשלם.","\u0003ורב יוסף,\u0004 מה הוא משיב על כך? לדעתו אף בסחיטה אין לו תקנה, שכן \u0003היכי\u0004 \u0005[כיצד]\u0006 \u0003נסחוט?\u0004 אם \u0003נסחוט\u0004 את הירק \u0003טובא\u0004 \u0005[הרבה]\u0006 — \u0003קא\u0004 \u0005[הריהו]\u0006 בכך \u0003מפסיד ב\u0004ירק של \u0003שביעית,\u0004 ואין לעשות כן. ואם \u0003נסחוט\u0004 את הירק \u0003פורתא\u0004 \u0005[מעט]\u0006 — \u0003סוף סוף\u0004 עדיין \u0003איערובי מיערב\u0004 \u0005[מעורב]\u0006 שמן התרומה בירק השביעית, ולא הועילה הסחיטה. וחוזרת איפוא טענתו של רב יוסף, שבמקרה זה לא היו חכמים אוסרים לבשל את ירק השביעית בשמן התרומה. ואם הם אוסרים משמע שמדובר במקרה שעדיין לא נתערבו, ויש להם תקנה. וממשנה זו יש להוכיח, שר' שמעון, המתיר לבשלם, מתיר להביא קדשים לבית הפסול לכתחילה, ולא רק במקרה שנתערבו, כפי שסבור רבה.","ועוד \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 רב יוסף על שיטת רבה, ממה ששנינו בברייתא: מי שהוא ספק מצורע מוחלט, החייב להביא ביום השמיני לטהרתו אשם ולוג שמן, מה יעשה? \u0003ר' שמעון אומר: למחרת\u0004 שבעת ימי טהרתו, ביום השמיני, \u0003מביא אשמו ולוגו עמו, ואומר: אם\u0004 קרבן זה \u0003של מצורע\u0004 הוא — \u0003הרי זה אשמו וזה לוגו,\u0004 כדינו,"],["\u0003ואם לאו\u0004 \u0005[לא]\u0006, שאין הוא מצורע — איל \u0003אשם זה\u0004 יהא \u0003של שלמי נדבה,\u0004 שכן דרך הקרבתם שווה. \u0003ו\u0004כיצד נוהגים ב\u0003אותו אשם\u0004 של ספק? הריהו \u0003טעון\u0004 (צריך) \u0003שחיטה בצפון\u0004 העזרה, כדין האשם, \u0003ומתן\u0004 מדמו על \u0003בהונות\u0004 המיטהר ועל אוזנו (ראה ויקרא יד, יד), \u0003וסמיכה, ונסכים, ותנופת\u0004 (הנפת) \u0003חזה ושוק\u0004 כדין שלמים,","\u0003ונאכל ליום ולילה\u0004 כדין אשם (ולא לשני ימים, כשלמים). הרי שבמקרה של ספק מתיר ר' שמעון לכתחילה להביא קדשים לבית הפסול, ולא רק במקרה שנתערבו בהמות העומדות להקרבה! ומשיבים: \u0003תקוני גברא שאני\u0004 \u0005[תיקון האדם שונה],\u0006 שכיון שאין לו דרך להיטהר לגמרי מצרעתו, אלא אם יביא קרבנו — אין חוששים למיעוט אכילת הקדשים.","ולגופה של שיטת ר' שמעון שואלים: פתרון זה של ר' שמעון על ידי תנאי \u0003התינח\u0004 \u0005[זה נוח]\u0006 לגבי ה\u0003אשם,\u0004 ואולם ביחס ל\u0003לוג\u0004 שמן שצריך המצורע להביא \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 שהרי אין לוג שמן בא עם השלמים! ומשיבים: \u0003דאמר\u0004 \u0005[ש\u0006הוא מתנה ו\u0005אומר]\u0006 שאם אינו מצורע \u0003לוג זה יהא נדבה,\u0004 שכן ניתן להקדיש שמן כנדבה. ושואלים: \u0003ודילמא\u0004 \u0005[ושמא]\u0006 באמת \u0003לאו\u0004 \u0005[לא]\u0006 \u0003מצורע הוא,\u0004 \u0003ו\u0004אם כן, \u0003בעי מקמץ\u0004 \u0005[צריך להיות נקמץ],\u0006 כפי שנוטלים קומץ מסולת המנחה, ולהקטיר אותו על המזבח כדי להתירו לכהנים באכילה! ומשיבים: מדובר \u0003דמקמיץ\u0004 \u0005[ש\u0006לוג זה אכן \u0005נקמץ]\u0006 תחילה.","ושואלים: \u0003ודילמא\u0004 \u0005[ושמא]\u0006 באמת \u0003מצורע הוא, ובעי\u0004 \u0005[וצריך]\u0006 \u0003מתן שבע\u0004 הזיות מלוג השמן לפני ה' (ראה ויקרא יד, טו— טז)! ומשיבים: \u0003דיהיב\u0004 \u0005[ש\u0006הכהן אכן \u0005נותן]\u0006 את המתנות הללו.","ומקשים: וכיצד הוא יכול להזות? \u0003והא חסר ליה\u0004 \u0005[והרי\u0006 כבר \u0005נחסר לו]\u0006 לוג השמן על ידי הקמיצה, ואין מזים אלא מלוג שלם! ומשיבים: \u0003דמייתי פורתא ומלי ליה\u0004 \u0005[ש\u0006לאחר הקמיצה \u0005מביא מעט\u0006 שמן נוסף, \u0005וממלא,\u0006 משלים, \u0005אותו\u0006 לכדי שיעור לוג\u0005].\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו]:\u0006 \u0003חסר הלוג עד שלא\u0004 \u0003יצק\u0004 הכהן מן השמן על כפו השמאלית, על מנת להזות ממנה על המצורע באצבעו הימנית — \u0003ימלאנו.\u0004","וחוזרים ושואלים: \u0003ו\u0004אם אין הוא מצורע, ואותו לוג שמן הריהו נדבה, \u0003הא בעי\u0004 \u0005[הרי\u0006 הקומץ שקמץ ממנו \u0005צריך]\u0006 \u0003הקטרה\u0004 על המזבח, כדי להתיר את השיריים באכילה לכהנים! ומשיבים: \u0003דאקטר ליה\u0004 \u0005[ש\u0006באמת הכהן \u0005מקטיר אותו].\u0006","ושואלים: \u0003אימת\u0004 \u0005[מתי]\u0006 מקטיר הכהן את הקומץ? \u0003אי בתר\u0004 \u0005[אם אחר]\u0006 \u0003מתנות שבע\u0004 שלפני ה', לטהרת המצורע — אינו יכול לעשות זאת, שהרי בהזאות אלו נחסר לוג השמן, ומה שנותר \u0003הוו להו\u0004 \u0005[נהיו\u0006 בכך\u0005]\u0006 כ\u0003שיריים\u0004 של מנחה \u0003שחסרו בין קמיצה להקטרה, ואין מקטירין\u0004 עוד \u0003את הקומץ עליהן\u0004 כדי להתירם באכילה.","\u0003אי\u0004 \u0005[אם]\u0006 הכוונה היא שמקטיר הכהן את הקומץ \u0003קודם מתנות שבע\u0004 שלפני ה', הרי מאחר והקטיר את הקומץ מלוג השמן — שוב אינו יכול להזות ממנו לפני ה', שהרי כלל הוא: \u0003כל שממנו לאישים\u0004 — \u0003הרי הוא ב\"בל תקטירו\",\u0004 כלומר, כל דבר שחלק ממנו קרב על המזבח (\"לאישים\"), החלק האחר שבו אסור בהקרבה. והזיה זו מעין הקטרה היא!","\u0003אמר רב יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' שמעון בן פזי:\u0004 כשהוא מזה שבע הזיות הריהו מתנה שאם אינו מצורע — אינו מתכוון להקרבה אלא לשפיכה סתם, כמו דברים האסורים בהקטרה \u0003דמסיק להו\u0004 \u0005[שמעלה אותם]\u0006 \u0003לשם עצים\u0004 (להסקה) בלבד. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אליעזר אומר:\u0004 אותם דברים שאסורים בהקטרה על המזבח — \u0003לריח ניחוח אי\u0004 (אין) \u0003אתה מעלה\u0004 אותם למזבח, \u0003אבל אתה מעלה\u0004"],["\u0003לשם עצים.\u0004","ומקשים: גם אם ניתן לקמוץ מלוג השמן ולהקטיר, וכן להזות ממנו לפני ה', \u0003והא איכא\u0004 \u0005[והרי\u0006 עדיין \u0005יש]\u0006 \u0003שיריים דבעי מילינהו\u0004 \u0005[שצריך\u0006 היה \u0005למלא,\u0006 להשלים \u0005אותם]\u0006 לאחר הקמיצה, כדי שיוכל להזות שבע הזיות מלוג שלם, \u0003ואיכא הך פורתא\u0004 \u0005[ויש\u0006 איפוא \u0005המעט הזה\u0006 שהוסיף\u0005]\u0006 \u0003דלא קמיץ עילויה\u0004 \u0005[שלא קמץ עליו]\u0006 מתחילה. ואם אין הוא מצורע, ולוג השמן הריהו נדבה, נמצא שיש חלק מלוג השמן שלא הותר על ידי הקמיצה! ומשיבים: \u0003דפריק ליה\u0004 \u0005[ש\u0006הוא \u0005פודה אותו].\u0006 כלומר, לאחר שהיזה מלוג השמן את ההזיות שלפני ה', עושה תנאי שאם אכן אין הוא מצורע, אותו שמן מתחלל על מעות ונעשה חולין.","ושואלים: \u0003דפריק ליה היכא\u0004 \u0005[שפודה אותו היכן]?\u0006 \u0003אי גוואי\u0004 \u0005[אם\u0006 כשהשמן \u0005בפנים,\u0006 בעזרה שבמקדש\u0005]\u0006 — \u0003קא מעייל\u0004 \u0005[\u0006נמצא שבכך \u0005הוא מכניס]\u0006 \u0003חולין לעזרה! אי אבראי\u0004 \u0005[אם בחוץ]\u0006 שמוציא את לוג השמן אל מחוץ לעזרה — \u0003איפסיל ליה\u0004 \u0005[נפסל לו]\u0006 \u0003ב\u0004פסול \u0003יוצא,\u0004 ואסור הדבר! ומשיבים: \u0003לעולם\u0004 מדובר כשפודה אותו כשהוא ב\u0003גוואי\u0004 \u0005[בפנים].\u0006 ואין זה אסור, משום ש\u0003חולין ממילא הויין\u0004 \u0005[\u0006הם \u0005נעשים]\u0006 על ידי הפדיה, ומתחילה הרי לא הכניס חולין לעזרה.","ומקשים עוד על עצם הפתרון שהציעו לדעת ר' שמעון, למי שהוא ספק מצורע, להביא לוג שמן לנדבה ולהתנות עליו: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' שמעון\u0004 עצמו ש\u0003אין מתנדבין שמן!\u0004 ומשיבים: \u0003תקוני גברא שאני\u0004 \u0005[תיקון של האדם שונה],\u0006 כלומר, מודה ר' שמעון במקרה זה, שהרי רק כך יכול המצורע להיטהר לגמרי.","ועוד בענין שיטת ר' שמעון, שספק מצורע יכול להביא כבש שלמים לנדבה, ולהתנות עליו מסופר: \u0003יתיב\u0004 \u0005[יושב\u0006 היה\u0005]\u0006 \u0003רב רחומי קמיה\u0004 \u0005[לפני]\u0006 \u0003רבינא, ויתיב וקאמר משמיה\u0004 \u0005[ויושב\u0006 היה \u0005ואומר משמו]\u0006 של \u0003רב הונא בר תחליפא:\u0004 מדוע לא יביא המצורע כבש לאשמו, \u0003ונימא\u0004 \u0005[ויאמר]\u0006 שאם אינו מצורע \u0003אשם זה יהא אשם תלוי\u0004 (הבא על ספק עבירה), שהוא נאכל ליום ולילה, כמו אשם מצורע. וכך אין הוא ממעט בזמן אכילת קדשים, כדרך שממעט בזמן אכילת השלמים!","ומתוך שלא נקט כן ר' שמעון, \u0003שמע מינה\u0004 \u0005[למד מכאן]:\u0006 \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא דפליג עליה\u0004 \u0005[שחולק עליו]\u0006 על \u0003ר' אליעזר\u0004 הסבור (במסכת כריתות כה,א) שיכול אדם להתנדב אשם תלוי — \u0003ר' שמעון הוא, דאמר\u0004 \u0005[שהוא אומר],\u0006 כפי שעולה מדבריו כאן: \u0003אין מתנדבין אשם תלוי. אמר ליה\u0004 \u0005[לו]\u0006 רבינא לרב רחומי: \u0003תורה, תורה,\u0004 כלומר, היכן היא תורתו של אדם גדול כמוך! \u0003אימרי בדיכרי מיחלפי\u0004 \u0005[כבשים באילים מתחלפים]\u0006 \u0003לך\u0004 שהרי אשם מצורע הוא כבש (ויקרא יד, י) בן שנה, ואיך הוא יכול להתנות שיקרב כאשם תלוי, שאינו בא אלא מן האילים (ויקרא ה, טו), שהם בני שנתיים?","\u0003איברי חטאת,\u0004 שבשרה נאכל על ידי הכהנים, ואסור בהקרבה, \u0003שנתערבו באיברי עולה,\u0004 שקרבים על המזבח, מה יעשה בהם? \u0003ר' אליעזר אומר: יתן\u0004 את כולם \u0003למעלה\u0004 (על המזבח), \u0003ורואה אני את בשר\u0004 (איברי) \u0003החטאת מלמעלה כאילו הן עצים\u0004 שנשרפים על המזבח ולא כקרבן. \u0003וחכמים אומרים:\u0004 לא כך יעשה, אלא ימתינו כל האיברים שבתערובת עד ש\u0003תעובר צורתן\u0004 (ישתנו מראיהם) בלינה, וייפסלו להקרבה כדינו של נותר, \u0003ויצאו\u0004 כולם \u0003לבית השריפה\u0004 שבעזרה, כדין קדשי קדשים שנפסלו.","ומבררים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 לשיטת \u0003ר' אליעזר,\u0004 שהתיר להעלות את בשר החטאת על המזבח לשם עצים? ומשיבים: \u0003אמר קרא\u0004 \u0005[המקרא]\u0006 באיסור הקרבת שאור ודבש: \u0003\"ואל המזבח לא יעלו לריח ניחח\"\u0004 (ויקרא ב, יב), \u0003לריח ניחוח אי\u0004 (אין) \u0003אתה מעלה\u0004 אותם, \u0003אבל אתה מעלה\u0004 אותם \u0003לשם עצים.\u0004 ומכאן אתה למד לשאר דברים האסורים בהקרבה, כגון בשר החטאת, שניתן להעלותם כעצים.","\u0003ורבנן\u0004 \u0005[חכמים]\u0006 החולקים על ר' אליעזר, מה הם משיבים? לדעתם \u0003מיעט רחמנא\u0004 \u0005[הכתוב]\u0006 בתחילת אותו פסוק: \"קרבן ראשית תקריבו \u0003אותם\",\u0004 ללמדנו: \u0003אותם\u0004 (שאור ודבש) \u0003הוא\u0004 שנאמר בהם: \u0003אי\u0004 (אין) \u0003אתה מעלה\u0004 לקרבן \u0003אבל אתה מעלה\u0004 אותם \u0003לשם עצים, אבל\u0004 כל \u0003מידי אחרינא\u0004 \u0005[דבר אחר]\u0006 שנאסר \u0005בהקרבה —\u0006 \u0003לא\u0004 מעלים על המזבח כלל.","ושואלים: \u0003ור' אליעזר\u0004 כיצד הוא דורש את המיעוט הזה? ומשיבים: הוא דורש אותו לאיסור אחר שדייקו מפסוק זה: דווקא \u0003אותם\u0004 (שאור ודבש) \u0003הוא דרבאי\u0004 \u0005[שריבה]\u0006 \u0003לך\u0004 בהם איסור העלאה על \u0003כבש\u0004 המזבח \u0003כ\u0004העלאה על ה\u0003מזבח\u0004 עצמו, \u0003אבל\u0004 כל \u0003מידי אחריני\u0004 \u0005[דבר אחר]\u0006 — \u0003לא\u0004 נחשבת להם העלאתם לכבש המזבח כהעלאה למזבח עצמו.","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מנין להם הלכה זו? ומשיבים: \u0003תרתי שמע מינה\u0004 \u0005[\u0006את \u0005שני\u0006 הדינים \u0005אתה יכול ללמוד מכאן],\u0006 ש\"אותם\" מדגיש כי כל מה שנאמר בפסוק זה אינו נוגע אלא לשאור ודבש — הן שמותר להעלותם על המזבח כעצים, והן שדין הכבש הריהו כדין המזבח.","ומעירים: \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 היא ש\u0003לא כי האי תנא\u0004 \u0005[כמו\u0006 שיטת \u0005תנא זה]\u0006 בהבנת מחלוקתם, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' יהודה: לא נחלקו ר' אליעזר וחכמים על איברי חטאת שנתערבו באיברי עולה\u0004 — \u0003ש\u0004לדעת הכל, וגם לדעת חכמים, \u0003יקרבו\u0004 כולם. וכמו כן לא נחלקו שאם נתערבו איברים הראויים להקרבה \u0003ב\u0004איברי \u0003רובע ונרבע\u0004 האסורים להקרבה — \u0003שלא יקרבו,\u0004 גם לדעת ר' אליעזר, שגנאי הוא למזבח.","\u0003על מה נחלקו? על איברי עולה תמימה שנתערבו באיברי בעלת מום\u0004 הפסולה להקרבה, \u0003ש\u0004במקרה זה \u0003ר' אליעזר אומר: יקרבו\u0004 כל האיברים, \u0003ורואה אני\u0004 את איברי בעלת המום \u0003למעלה\u0004 על המזבח \u0003כאילו הן עצים. וחכמים אומרים: לא יקרבו.\u0004","ושואלים לשיטה זו: \u0003ור' אליעזר, מאי שנא\u0004 \u0005[במה שונים,\u0006 מיוחדים\u0005]\u0006 איברי \u0003רובע ונרבע\u0004 שאינם עולים למזבח — משום שרובע ונרבע \u0003לא חזו\u0004 \u0005[אינם ראויים]\u0006 להקרבה, איברי \u0003בעלת מום נמי\u0004 \u0005[גם כן]\u0006 \u0003לא חזי\u0004 \u0005[אינם ראויים]\u0006 להקרבה!"],["\u0003אמר רב הונא:\u0004 מדובר כאן באיברי בהמה שיש בה מום שאינו ניכר כל כך, כגון שנפסל אותו הקרבן \u0003בדוקין\u0004 (כעין קרום) \u0003שבעין,\u0004 \u0003ואליבא\u0004 \u0005[ועל פי שיטת]\u0006 \u0003ר' עקיבא,\u0004 ש\u0003אמר\u0004 כי בעלי מומים כאלה \u0003אם עלו\u0004 למזבח — \u0003לא ירדו.\u0004 ומקשים: \u0003אימר\u0004 \u0005[אמור]\u0006 ש\u0003אמר ר' עקיבא\u0004 את שיטתו זו במקרה \u0003דאי עבד\u0004 \u0005[שאם\u0006 כבר \u0005עשה]\u0006 הכהן מעשה והעלה את איברי בעלי מומים כאלו, שלא ירדו למזבח. ואולם לעשות כן \u0003לכתחלה\u0004 ולהעלות תערובת שיש בה איברים כאלו \u0003מי\u0004 \u0005[האם]\u0006 \u0003אמר?\u0004","\u0003אמר רב פפא: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 \u0003כגון ש\u0004קרה ו\u0003עלו\u0004 כל אותם האיברים שבתערובת \u0003על גבי כבש\u0004 המזבח, וכיון שכבר עלו לשם ונתקדשו כקרבן, ניתן להעלותם למזבח עצמו. ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שכבר עלו על הכבש, \u0003אפילו בעינייהו\u0004 \u0005[בעינם,\u0006 כמות שהם\u0005]\u0006 בלא תערובת, יעלה את איברי בעלי המום למזבח, וכשיטת ר' עקיבא!","\u0003אלא\u0004 זהו \u0003טעמיה\u0004 \u0005[טעמו]\u0006 של \u0003ר' אליעזר:\u0004 באיסור הקרבת בעל מום למזבח \u0003מיעט רחמנא\u0004 \u0005[הכתוב],\u0006 ואמר: \u0003\"מום בם\u0004 לא ירצו לכם\" (ויקרא כב, כה), והרי זה בא לומר: דווקא כשהמום מצוי בם \u0003הוא\u0004 ש\u0003לא ירצו, הא\u0004 \u0005[אבל]\u0006 אם היה זה \u0003על ידי תערובת\u0004 — \u0003ירצו.\u0004 אבל לא נאמר מיעוט כזה אלא בבעלי מום, ולא ברובע ונרבע, ולכן אף אם נתערבו בכשרים אין מעלים אותם.","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 כיצד הם דורשים את לשון הפסוק? ומשיבים: מיעוט אחר יש בפסוק זה, \u0003\"מום בם\" הוא\u0004 ש\u0003לא ירצו,\u0004 כלומר, כל עוד יש בם מום, \u0003הא\u0004 \u0005[אבל]\u0006 \u0003עבר\u0004 ה\u0003מום\u0004 שבהם — \u0003ירצו.\u0004 \u0003ו\u0004אילו \u0003ר' אליעזר\u0004 לומד הלכה זו \u0003מ\u0004מה שנאמר באותו פסוק: \"כי משחתם בהם מום בם\", שיכול היה לאמר \"כי משחתם \u0003בם\"\u0004 ואמר: \u0003\"בהם\",\u0004 ובייתור זה משמיענו הכתוב שאם עבר מומו — כשר. ומן הצד האחר, \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 אינם לומדים הלכה זו מכאן, משום שאת שינוי הלשון \u0003\"בם\"\u0004 במקום \u0003\"בהם\" לא דרשי\u0004 \u0005[אינם דורשים].\u0006","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שלדעת ר' אליעזר בעלי מום כשרים להקרבה בתערובת, מדוע צריך ר' אליעזר לומר \u0003\"רואה\u0004 אני את איברי בעל המום כאילו הן עצים\", ומשום כך מותר להעלותם? \u0003הא רחמנא אכשריה\u0004 \u0005[הרי התורה הכשירה אותם]\u0006 לקרבן! ומשיבים: \u0003לדבריהם\u0004 של חכמים \u0003קאמר להו\u0004 \u0005[\u0006הוא \u0005אומר להם]\u0006 כן: \u0003לדידי\u0004 \u0005[לי עצמי,\u0006 לשיטתי\u0005]\u0006 \u0003רחמנא אכשריה\u0004 \u0005[התורה הכשירה אותו],\u0006 ואולם אף \u0003לדידכו\u0004 \u0005[לשיטתכם]\u0006 שאינם כשרים כקרבן, \u0003אודו לי מיהא\u0004 \u0005[הודו לי על כל פנים]\u0006 ש\u0003בשר בעלת מום\u0004 שנתערב עם בשר הכשירה \u0003כעצים דמי\u0004 \u0005[נחשב],\u0006 \u0003מידי דהוה\u0004 \u0005[כמו שהוא]\u0006 בדין \u0003בשר חטאת\u0004 שנתערב בבשר עולה. שהרי לשיטת ברייתא זו, אף חכמים מודים שיקרבו יחד.","\u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מה הם משיבים לו? לדבריהם יש לחלק: \u0003הכא\u0004 \u0005[כאן]\u0006 בתערובת איברי בעלי מום — \u0003מאיסי\u0004 \u0005[מאוסים]\u0006 הם בעלי מום, ולכן אין מעלים אותם על המזבח, אפילו כעצים. \u0003התם\u0004 \u0005[שם],\u0006 בתערובת איברי חטאת באיברי עולה, איברי החטאת \u0003לא מאיסי\u0004 \u0005[אינם מאוסים],\u0006 אין בהם שום צד של פסול וגנות בעצמם, ולכן מותר להעלותם לשם עצים.","\u0003אברין\u0004 של עולות כשרות שנתערבו \u0003באברין\u0004 של עולות \u0003בעלי מומין,\u0004 \u0003ר' אליעזר אומר:\u0004 אף שנפסלו כל האיברים שבתערובת להקרבה, \u0003אם\u0004 בדיעבד \u0003קרב ראש אחד מהן\u0004 — \u0003יקרבו כל הראשין\u0004 האחרים שבתערובת, שאנו אומרים שהראש שקרב בתחילה הוא הראש הפסול שבתערובת. וכן אם קרבו כבר \u0003כרעים של אחד מהן\u0004 — \u0003יקרבו כל\u0004 שאר \u0003הכרעים\u0004 שבתערובת. \u0003וחכמים אומרים: אפילו קרבו\u0004 כל האיברים \u0003כלם חוץ מאחד מהן\u0004 — יש לחשוש שהוא האיבר הפסול, ולא יוקרב על המזבח, אלא \u0003יצא לבית השריפה.\u0004","\u0003אמר ר' אלעזר: לא הכשיר ר' אליעזר\u0004 כשקרב איבר אחד מן התערובת, \u0003אלא\u0004 רק כשמקריב את שאר האיברים \u0003שנים שנים,\u0004 שבאופן זה אחד מן השנים הוא בוודאי כשר. \u0003אבל אחד אחד\u0004 — \u0003לא.\u0004 \u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003ר' ירמיה\u0004 ממה ששנינו במשנתנו: \u0003וחכמים\u0004 החולקים על ר' אליעזר \u0003אומרים: אפילו קרבו כולן חוץ מאחד מהן\u0004 — \u0003יצא לבית השריפה,\u0004 ומשמע שגם באופן זה, שנותר רק אחד מהם, קיימת המחלוקת ביניהם, ומשמע שר' אליעזר סבור שמותר להקריבו!","\u0003אמר לו\u0004 ר' אלעזר ל\u0003ר' ירמיה בר תחליפא\u0004 בתשובה: \u0003אסברה\u0004 \u0005[אסביר]\u0006 \u0003לך\u0004 את האמור במשנה, \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אחד\"? זוג אחד,\u0004 שהם שני איברים.","\u0003דם\u0004 של קרבן כשר \u0003שנתערב במים,\u0004 מה עושים? \u0003אם יש בו\u0004 בתערובת עדיין \u0003מראית דם\u0004 — \u0003כשר\u0004 הדם לזריקה על המזבח, למרות שהמים מרובים מן הדם. \u0003נתערב\u0004 הדם \u0003ביין\u0004 שהוא אדום, ואי אפשר להבחין לפי המראה — \u0003רואין אותו\u0004 את היין שנתערב \u0003כאילו הוא מים,\u0004 ואם בכמות שכזו של מים היה בתערובת מראה דם — הריהו כשר לזריקה. וכן אם \u0003נתערב\u0004 דם הקרבן \u0003בדם בהמה\u0004 של חולין, \u0003או בדם החיה,\u0004 והרי אי אפשר להבחין בין הדמים — גם כן \u0003רואין אותו\u0004 דם הבהמה או החיה \u0003כאילו הוא מים,\u0004 ומשערים לפי החשבון."],["\u0003ר' יהודה אומר: אין דם מבטל דם,\u0004 שלדעתו דבר שנתערב במינו, אפילו טיפה בכלי גדול — אינו בטל. ודם הקרבן כשר הוא, ויזרוק הכהן את דם התערובת על המזבח.","\u0003נתערב\u0004 דם כשר \u0003בדם\u0004 של קרבנות \u0003פסולין\u0004 — אין לו תקנה, ו\u0003ישפך\u0004 הכל \u0003לאמה\u0004 (תעלת המים העוברת בעזרה). נתערב דם הקרבן \u0003בדם התמצית\u0004 (שנתמצה מצוואר הבהמה לאחר שיצא דם הנפש) והריהו פסול לזריקה — \u0003ישפך\u0004 הכל \u0003לאמה. ר' אליעזר מכשיר\u0004 תערובת זו לזריקה. ומכל מקום גם לדעת תנא קמא, בכל המקרים, \u0003אם לא נמלך\u0004 (שאל) הכהן והלך מדעת עצמו \u0003ונתן\u0004 מדם התערובת על המזבח — \u0003כשר\u0004 הקרבן.","שנינו במשנה כי דם שנתערב במים, אם יש בו מראית דם — כשר, למרות שהמים מרובים מן הדם. ועל כך \u0003אמר ר' חייא בר אבא אמר ר' יוחנן: לא שנו\u0004 הלכה זו \u0003אלא\u0004 דווקא במקרה \u0003שנפלו מים לתוך דם, אבל\u0004 במקרה ש\u0003נפל דם לתוך מים\u0004 — כל חלק וחלק מן הדם שנפל אל המים \u0003ראשון ראשון בטל\u0004 במים, ואין התערובת כשרה לזריקה, גם אם תהא בה בסוף מראית דם.","\u0003אמר רב פפא: ולענין\u0004 מצות \u0003כיסוי\u0004 הדם של חיה ועוף שנשחטו, \u0003אינו כן,\u0004 שלא רק אם נפלו המים לדם, אלא גם אם נפל הדם למים, אם יש בתערובת מראית דם — הריהי חייבת בכיסוי הדם. ואין אנו אומרים שכבר נתבטל הדם מתחילה, ושוב אינו חייב בכיסוי, \u0003לפי שאין דחוי במצו‍ת,\u0004 שכיון שכבר התחייב הדם במצות כיסוי, הריהו חוזר ומתחייב כך משעה שיש בו מראית דם.","ועוד בדיני תערובת. \u0003אמר ריש לקיש:\u0004 בשר \u0003הפיגול\u0004 (קרבן שנפסל מחמת מחשבת חוץ לזמנו), \u0003ו\u0004בשר \u0003הנותר\u0004 (שעבר זמן אכילתו), \u0003ו\u0004בשר \u0003הטמא, ש\u0004בכל אחד מהם שיעור כזית המחייב מלקות על אכילתו, ש\u0003בללן\u0004 (עירב אותם) \u0003זה בזה, ואכלן\u0004 בתערובתם — הרי הוא \u0003פטור\u0004 מעונש מלקות על כך, משום ש\u0003אי אפשר ש\u0004תוך כדי תהליך הלעיסה בפה \u0003לא ירבה מין\u0004 אחד \u0003על חבירו ויבטלנו,\u0004 וכיון שאין יודעים מהו האיסור שרבה ומהו האיסור שבטל, אין אפשרות להתרות בוודאות באדם האוכל על אכילת איזה מן האיסורים הוא עומד ללקות, ובלא התראה ודאית אין לוקים.","ומעירים: \u0003שמע מינה תלת\u0004 \u0005[למד מכאן\u0006 מדברי ריש לקיש \u0005שלושה\u0006 כללים הלכתיים\u0005]:\u0006 \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שאף \u0003איסורין מבטלין זה את זה\u0004 ברוב, בדומה להיתר המבטל איסור. \u0003ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 עוד שההלכה שדבר איסור ה\u0003נותן טעם\u0004 בדבר היתר הריהו אוסרו, אף \u0003ב\u0004זמן שההיתר הוא \u0003רוב\u0004 — \u0003לאו דאורייתא\u0004 \u0005[לא מן התורה\u0006 היא\u0005],\u0006 אלא מדברי חכמים. שאילו היתה מן התורה, צריך היה במקרה זה ללקות על אכילה זו, שהרי אחד מן האיסורים נתן טעם בחבירו, ואסרו. \u0003ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 עוד ש\u0003התראת ספק,\u0004 שאין העדים המתרים באדם יודעים בוודאות איזו עבירה הוא עומד לעבור — \u0003לא שמה התראה,\u0004 ולכן אין הוא לוקה במקרה זה, אף אם התרו בו עדים.","על מה שמשמע מכאן שנותן טעם ברוב אינו אוסר מן התורה, \u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רבא\u0004 ממה ששנינו במשנה: מי ש\u0003עשה עיסה\u0004 ממיני קמח שונים, \u0003מן\u0004 ה\u0003חיטין ומן\u0004 ה\u0003אורז,\u0004 \u0003אם יש בה\u0004 בתערובת זו \u0003טעם דגן\u0004 (חיטה) — \u0003חייבת ב\u0004הפרשת \u0003חלה\u0004 כדין עיסה העשויה מקמח של אחד מחמשת מיני דגן. \u0003ו\u0004דין זה אמור \u0003אף על גב דרובא\u0004 \u0005[אף על פי שהרוב]\u0006 שבה הוא קמח \u0003אורז!\u0004","ומשיבים: אף חיוב זה בחלה אינו אלא \u0003מדרבנן\u0004 \u0005[מדברי חכמים],\u0006 ולא מן התורה. ומקשה רבא: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של אותה משנה: \u0003אדם יוצא בה\u0004 בעיסה זו \u0003ידי חובתו\u0004 באכילת מצה \u0003בפסח,\u0004 שהיא מצוה מן התורה דווקא במיני דגן. הרי שדין נתינת טעם ברוב מן התורה הוא!"],["\u0003אלא,\u0004 כך צריך לומר לשיטת ריש לקיש: תערובת של \u0003מין בשאינו מינו,\u0004 כגון קמח חטים וקמח אורז, שטעמיהם שונים — \u0003בטעמא\u0004 \u0005[בטעם],\u0006 כלומר, הנותן טעם בחבירו אוסרו. ואולם אם נתערב \u0003מין במינו\u0004 שטעמיהם שווים, וכגון תערובת בשר פיגול ונותר וטמא, שעוסק בה ריש לקיש — \u0003ברובא\u0004 \u0005[ברוב],\u0006 הולכים אחר הרוב.","ושואלים על כך: \u0003ו\u0004מדוע לא \u0003נשער\u0004 במקרה של \u0003מין\u0004 שהתערב \u0003במינו כ\u0004אילו היה זה מקרה של תערובת \u0003מין בשאינו מינו,\u0004 ואין המועט בטל אם יש בו שיעור כדי נתינת טעם במרובה! \u0003דתנן\u0004 \u0005[ש\u0006הרי כן \u0005שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003נתערב\u0004 דם קרבן \u0003ביין\u0004 (והרי זו תערובת מין במינו, שאין צבע הדם ניכר) — \u0003רואין אותו כאילו הוא מים. מאי לאו\u0004 \u0005[האם אין]\u0006 כוונת הדברים ש\u0003רואין אותו ליין\u0004 (מינו) \u0003כאילו הוא מים\u0004 (אינו מינו), ואם באופן זה היה במים מראה דם — הרי זה כשר לזריקה, למרות שאין בו רוב?","ומשיבים: \u0003לא\u0004 זו כוונת המשנה, אלא: אם נתערב הדם ברוב יין \u0003רואין אותו\u0004 את ה\u0003דם כאילו הוא מים,\u0004 כלומר, הריהו פסול, כאילו זרק מים על המזבח. ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה מפרש, \u0003\"בטל\u0004 הדם\" \u0003מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לתנא\u0005]\u0006 לומר!","\u0003ועוד\u0004 שואלים: והרי \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 דלי טמא שהטבילוהו במקוה כדי לטהרו, ויש בו יין לבן או חלב, \u0003ר' יהודה אומר:\u0004 אף על פי שאין מראה היין או החלב ניכר במים, \u0003רואין אותו\u0004 את היין הלבן או את החלב \u0003כאילו הוא יין אדום, אם\u0004 מחמת תערובת המים היה \u0003דיהה\u0004 (נחלש) \u0003מראהו\u0004 האדום — בטלו המשקים במי המקוה, והדלי \u0003כשר\u0004 (טהור),","\u0003ואם לאו\u0004 \u0005[לא]\u0006 — \u0003פסול\u0004 (טמא). הרי שמשערים מין במינו (יין לבן במי המקוה) כאילו היתה זו תערובת מין בשאינו מינו, ואינו בטל ברוב!","ומשיבים: אין להביא ראיה מדברי ר' יהודה, שכן \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא,\u0004 ואנו פוסקים כשיטת החכמים החולקים עליו. \u0003דתניא\u0004 \u0005[ש\u0006כך \u0005שנויה\u0006 אותה ברייתא\u0005]:\u0006 \u0003דלי\u0004 טמא \u0003שיש בו יין לבן או חלב, והטבילו\u0004 את הדלי — \u0003הולכין אחר הרוב,\u0004 שאם יש רוב ממי המקוה בדלי — נטהר הדלי. \u0003ר' יהודה אומר: רואין אותו\u0004 את היין הלבן או את החלב שבדלי \u0003כאילו הוא יין אדום, אם\u0004 מחמת המים \u0003דיהה מראהו\u0004 — \u0003כשר, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003פסול.\u0004","\u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 בשיטת ר' יהודה ממה ששנינו במשנה: \u0003דלי\u0004 טמא \u0003שהוא מלא רוקין והטבילו\u0004 במקוה — הרוקים חוצצים בין מי המקוה לבין הדלי, והריהו \u0003כאילו לא טבל.\u0004","היה הדלי הטמא מלא \u0003מי רגלים\u0004 (שתן) והטבילו, הרי אף שמי הרגלים שונים מעט במראם מן המים — \u0003רואין אותו\u0004 (את מי הרגלים) \u0003כאילו הן מים,\u0004 ומשעה שהושקו למי המקוה הרי הם נחשבים כמחוברים להם, ואין הם חוצצים מלטהר את הדלי.","היה הדלי הטמא \u0003מלא מי חטאת\u0004 (מי פרה אדומה) — אין השקה מועילה להם, ואין הדלי נטהר \u0003עד שירבו המים\u0004 כלומר, מי המקוה שנכנסו לדלי, \u0003על מי חטאת\u0004 שבו, ויבטלם ברוב.","ויש לברר: \u0003מאן שמעת ליה דאית ליה\u0004 \u0005[מיהו\u0006 התנא \u0005ששמעת אותו שיש לו]\u0006 \u0003\"רואין\"\u0004 כפי ששנינו במשנה זו, בענין מי רגלים? \u0003ר' יהודה\u0004 הוא (כפי ששנינו בברייתא לעיל), \u0003ו\u0004אילו בסוף משנה זו \u0003קתני\u0004 \u0005[\u0006הוא \u0005שונה]\u0006 לגבי מי חטאת שנתערבו במים \u0003דסגי ליה ברובא\u0004 \u0005[שדי לו ברוב]\u0006 כדי לבטלם, ואין רואים \u0005אותם כאילו היו יין אדום!\u0006","\u0003אמר אביי: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006"],["\u0003הא\u0004 \u0005[זה]\u0006 ששנינו במשנה בענין מי חטאת, שהם בטלים ברוב רגיל של מים — הוא כשיטה \u0003דידיה\u0004 \u0005[שלו],\u0006 של ר' יהודה עצמו. \u0003הא\u0004 \u0005[זה]\u0006 ששנינו בברייתא, בדין יין לבן שרואים אותו כאילו הוא יין אדום, ואינו בטל ברוב רגיל של מים — הוא כשיטה \u0003דרביה\u0004 \u0005[של רבו]\u0006 שהוא רבן גמליאל, המחמיר בדין תערובת של מין במינו, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 \u0003ר' יהודה אומר משום\u0004 (בשם) \u0003רבן גמליאל: אין דם מבטל דם\u0004 כגון דם קדשים שאינו בטל בדם אחר. \u0003אין רוק\u0004 \u0003מבטל רוק\u0004 כגון רוקו של הזב שנתערב ברוק של אדם טהור, \u0003ואין מי רגלים\u0004 \u0003מבטלין מי רגלים\u0004 כגון מי רגליו של זב במי רגלים אחרים.","\u0003רבא אמר\u0004 תירוץ אחר: המשנה לפיה מי חטאת בטלים ברוב רגיל של מי המקוה, אין ממנה סתירה לדברי ר' יהודה שבברייתא לענין יין לבן שנתערב במים, שכן \u0003בדלי שתוכו\u0004 (חללו) \u0003טהור ו\u0004רק \u0003גבו טמא עסקינן\u0004 \u0005[עוסקים אנו]\u0006 במשנה זו, \u0003דמדינא סגי להו בכל דהו\u0004 \u0005[שמן הדין די להם\u0006 למי המקוה \u0005ב\u0006כניסה \u0005כל שהוא]\u0006 לדלי, כדי לטהר את שפתו. ומי החטאת שבתוכו אינם מעכבים כלל את טהרתו.","\u0003ורבנן הוא דגזרו בהו\u0004 \u0005[וחכמים הם שגזרו בהם]\u0006 במי החטאת, להוסיף עליהם ממי המקוה, \u0003דילמא חייס עלייהו ולא מבטיל ליה\u0004 \u0005[שמא יחוס עליהם\u0006 הבעלים, על מי החטאת, מתוך \u0005שאינו\u0006 רוצה לבטל אותם מקדושתם\u0005]\u0006 ולא יטבול את הכלי כראוי, \u0003ו\u0004משום כך, \u0003כיון דאיכא ריבויא\u0004 \u0005[שיש ריבוי]\u0006 של מי המקוה עליהם — \u0003לא צריך\u0004 יותר, שהרי כבר נטהר הכלי.","\u0003אמר רבא\u0004 בסיכום דיני תערובת: \u0003אמור רבנן\u0004 \u0005[אמרו חכמים]\u0006 \u0003בטעמא\u0004 \u0005[בטעם],\u0006 שאם ניכר טעמו של דבר בדבר אחר — אינו בטל, \u0003ואמור\u0004 \u0003רבנן ברובא\u0004 \u0005[ואמרו חכמים\u0006 שאיסור בטל \u0005ברוב],\u0006 \u0003ואמור רבנן בחזותא\u0004 \u0005[ואמרו חכמים במראה],\u0006 שדבר שמראהו ניכר אינו בטל. וכך פירוש הדברים: בתערובת \u0003מין בשאינו מינו\u0004 — הביטול הוא \u0003ב\u0004התאם ל\u0003טעמא\u0004 \u0005[טעם],\u0006 בתערובת \u0003מין במינו\u0004 — הביטול הוא \u0003ברובא\u0004 \u0005[ברוב],\u0006 ו\u0003היכא דאיכא חזותא\u0004 \u0005[ובמקום שיש מראה]\u0006 שהמראה הוא הקובע האם דבר כשר או פסול — הביטול תלוי \u0003במראה.\u0004","ושבים לשיטת ריש לקיש שאמר שאיסורים (כגון נותר ופיגול וטמא) מבטלים זה את זה. ואומרים: \u0003ופליגא\u0004 \u0005[וחלוקה]\u0006 שיטה זו על \u0003ר' אלעזר,\u0004 שכן \u0003אמר ר' אלעזר: כשם שאין מצו‍ת מבטלות זו את זו\u0004 כשאוכל אותן כאחת, אלא כל אחת עומדת בפני עצמה, למרות שהאחרת מרובה ממנה, או נותנת בה טעם, \u0003כך אין איסורין מבטלין זו את זו.\u0004","ומוסיפים: \u0003מאן\u0004 \u0005[מיהו]\u0006 זה ש\u0003שמעת ליה\u0004 \u0005[אותו]\u0006 ש\u0003אמר: אין מצו‍ת מבטלות זו את זו?\u0004 שיטת \u0003הלל היא, דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003אמרו עליו על הלל הזקן ש\u0004כך \u0003היה\u0004 נוהג בליל הסדר, \u0003כורכן\u0004 את קרבן הפסח עם המצה והמרור \u0003בבת אחת ואוכלן, משום שנאמר\u0004 בקרבן הפסח: \u0003\"על מצות ומרורים יאכלוהו\"\u0004 (במדבר ט, יא), ולא חשש הלל שבכך יבטל טעם המרור את טעם המצה."],["ועוד בענין תערובת של מין במינו, שלדעת ר' יהודה במשנתנו אינו בטל. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003חרסן\u0004 (שבר כלי חרס) \u0003של זב וזבה\u0004 שבלועים בו מי רגליהם, שהם אב הטומאה והוא מטמא את נושאו, ונתן לתוכו מים כדי לנקותו, \u0003פעם ראשון ושני\u0004 שהדיחו — הרי הוא עדיין \u0003טמא,\u0004 פעם \u0003שלישי\u0004 — \u0003טהור,\u0004 שרבו מי ההדחה על מי הרגלים הבלועים בו, ונפלטו ממנו מי הרגלים הטמאים.","\u0003במה דברים אמורים? שנתן לתוכו מים, אבל לא נתן לתוכו מים,\u0004 אלא מי רגלים של אדם טהור — \u0003אפילו\u0004 פעם \u0003עשירי טמא,\u0004 שאין מי הרגלים הטמאים בטלים בהם, לפי שמין במינו לא בטל. \u0003ר' אליעזר בן יעקב אומר:\u0004 פעם \u0003שלישי אף על פי שלא נתן לתוכו מים,\u0004 אלא מי רגלים — \u0003טהור.\u0004 ושואלים: \u0003מאן\u0004 \u0005[מי]\u0006 החכם \u0003דשמעת ליה דאמר\u0004 \u0005[ששומע אתה אותו שאומר]:\u0006 \u0003מין במינו לא בטיל\u0004 \u0005[בטל]?\u0006 \u0003ר' יהודה,\u0004 והוא איפוא התנא קמא של ברייתא זו.","\u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו בברייתא אחרת: \u0003פשתן שטוואתו נדה\u0004 למרות שנספג בו רוק הנדה, שהוא מטמא במשא — ה\u0003מסיטו\u0004 (מזיז אותו) \u0003טהור,\u0004 מאחר שנתייבש הרוק וכך אינו מטמא. \u0003ואם היה\u0004 עדיין הפשתן \u0003לח\u0004 — \u0003מסיטו טמא, משום משקה פיה\u0004 (רוקה). \u0003ר' יהודה אומר: אף הרוטבו\u0004 (המרטיב אותו) את הפשתן \u0003במים\u0004 — הרי הוא שוב \u0003טמא משום משקה פיה. ו\u0004דין זה נאמר \u0003אפילו\u0004 אם היה מרטיב \u0003טובא\u0004 \u0005[הרבה]\u0006 את הפשתן, לפי שאין המים מבטלים את הרוק ומפליטים אותו, ובניגוד למה שאמר ר' יהודה בענין כלי חרס שנבלעו בו מי רגלים!","\u0003אמר רב פפא: שאני\u0004 \u0005[שונה]\u0006 \u0003רוק דקריר\u0004 \u0005[ש\u0006הוא \u0005נספג ונדבק]\u0006 בפשתן, ואין ההדחה במים יכולה לבטלו.","שנינו במשנה: אם \u0003נתערב\u0004 דם קרבן כשר \u0003בדם הפסולין\u0004 להקרבה, וכן אם נתערב דם קרבנות בדם התמצית שהוא פסול לזריקה — \u0003ישפך\u0004 הכל \u0003לאמה,\u0004 אפילו היה שם רוב של דם כשר. ואילו ר' אליעזר מכשיר לזריקה. ומבררים: \u0003במאי קמיפלגי\u0004 \u0005[במה הם חלוקים]?\u0006","\u0003אמר רב זביד: ב\u0004שאלה אם \u0003גוזרין גזירה\u0004 כעין \u0003זו\u0004 \u0003במקדש קא מיפלגי\u0004 \u0005[חלוקים הם],\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 חכמים, \u0005סבור]:\u0006 \u0003גוזרין,\u0004 ולכן אין זורקים את תערובת הדמים הללו, שמא יבואו מתוך כך גם לזריקת תערובת שיש בה רוב מדם הפסולים או מדם התמצית. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' אליעזר, \u0005סבור]:\u0006 \u0003לא גוזרין\u0004 גזירה כעין זו במקדש, ולכן תערובת דמים זו כשרה לזריקה.","\u0003רב פפא אמר\u0004 הסבר אחר במחלוקתם: \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003גוזרין\u0004 גזירה במקדש, ולכן במקרה שנתערב הדם הכשר בדם פסולים גם ר' אליעזר סבור שיישפך לאמה, ואינו מכשיר אלא כשנתערב בדם התמצית.","\u0003והכא\u0004 \u0005[וכאן]\u0006 \u0003ב\u0004שאלה האם \u0003דם התמצית מצוי לרבות\u0004 (להיות יותר) \u0003על דם הנפש קא מיפלגי\u0004 \u0005[חלוקים הם],\u0006 \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 חכמים, \u0005סבור]:\u0006 \u0003שכיח\u0004 \u0005[מצוי]\u0006 הדבר, ולכן יש לגזור על כל תערובת דם התמצית בדם הנפש, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' אליעזר, \u0005סבור]:\u0006 \u0003לא שכיח\u0004 \u0005[מצוי]\u0006 הדבר, ואין מקום לגזור גזירה זו.","ואומרים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004הסברו של \u0003רב פפא,\u0004 שר' אליעזר אינו מכשיר אלא בדם התמצית, אבל בדם הפסולים סבור הוא כדעת חכמים, שיישפך לאמה — \u0003היינו דקתני\u0004 \u0005[זהו ששנינו]\u0006 במשנתנו: \u0003נתערב בדם הפסולין\u0004 — \u0003ישפך לאמה, בדם התמצית\u0004 — \u0003ישפך לאמה,\u0004 מפני שיש פה שתי שאלות נפרדות, ורק בשניה ר' אליעזר מכשיר.","\u0003אלא ל\u0004הסברו של \u0003רב זביד,\u0004 שנחלקו בשני המקרים — \u0003ליערבינהו\u0004 \u0005[שיערב אותם]\u0006 התנא של משנתנו את שני המקרים הללו, \u0003וליתנינהו\u0004 \u0005[וישנה אותם]\u0006 ביחד: נתערב בדם הפסולים או בדם התמצית יישפך לאמה, ור' אליעזר מכשיר! ומסכמים: אכן, להסברו של רב זביד \u0003קשיא\u0004 \u0005[קשה]\u0006 הדבר.","נתערב \u0003דם\u0004 של קרבנות \u0003תמימים בדם\u0004 של \u0003בעלי מומין\u0004 שאינם ראויים להקרבה, \u0003ישפך\u0004 הכל \u0003לאמה\u0004 (תעלת הניקוז שבמקדש). ודין זה אמור כשנבלל דם כשר בדם פסול בכלי אחד. אבל אם נתערב \u0003כוס\u0004 של דם בעל מום \u0003בכוסות\u0004 של דמים כשרים, ואין יודעים איזה דם מצוי בכל כוס, \u0003ר' אליעזר אומר:\u0004 אף שאסור להקריב את כולם מחמת הספק, \u0003אם\u0004 קרה ו\u0003קרב\u0004 כבר \u0003כוס אחד\u0004 מהם — \u0003יקרבו כל\u0004 שאר \u0003הכוסות,\u0004 משום שאנו אומרים שזה שקרב היה הכוס הפסול, וכל השאר כשרים הם. \u0003וחכמים אומרים: אפילו קרבו\u0004 כל הכוסות \u0003כולן חוץ מאחד מהן\u0004 — \u0003ישפך\u0004 הכל \u0003לאמה,\u0004 מפני הספק אולי הוא הכוס הפסול.","דמי קרבנות \u0003הניתנין למטה\u0004 מחוט הסיקרא שבאמצע המזבח (כגון עולה ואשם ושלמים) \u0003שנתערבו ב\u0004דמים של חטאת ה\u0003ניתנין למעלה\u0004 מחוט הסיקרא, מה יעשה? \u0003ר' אליעזר אומר: יתן\u0004 תחילה מדמי התערובת \u0003למעלה\u0004 לשם חטאת, \u0003ורואה אני את\u0004 הדמים \u0003התחתונים\u0004 הניתנים \u0003מלמעלן, כאילו הם\u0004 אינם אלא \u0003מים\u0004 בלבד, \u0003ויחזור ויתן\u0004 מדמי התערובת \u0003למטה. וחכמים אומרים:\u0004 אין לתת דמים שלא במקומם, ו\u0003ישפך\u0004 הכל \u0003לאמה. ו\u0004מכל מקום, גם לדעת חכמים, \u0003אם\u0004 הכהן \u0003לא נמלך\u0004 (שאל מה לעשות), \u0003ונתן\u0004 את דם התערובת על המזבח למעלה — הרי זה \u0003כשר,\u0004 ויחזור ויתן למטה."],["דמים \u0003הניתנין במתנה\u0004 (נתינה) \u0003אחת\u0004 על גבי המזבח, \u0003שנתערבו ב\u0004דמים שאף הם \u0003ניתנין במתנה אחת\u0004 (כגון דם בכור בדם בכור אחר, או בדם מעשר בהמה) — \u0003ינתנו\u0004 כולם \u0003במתנה אחת.\u0004 וכן אם נתערבו הניתנים ב\u0003מתן ארבע\u0004 בניתנים \u0003במתן ארבע\u0004 כגון חטאת בחטאת, וכן עולה בשלמים, שדם שניהם ניתן שתי מתנות שהן ארבע — \u0003ינתנו\u0004 כולם \u0003במתן ארבע.\u0004","נתערבו הניתנים ב\u0003מתן ארבע\u0004 בניתנים \u0003במתנה אחת,\u0004 כגון דם עולה בדם בכור, מה יעשה? \u0003ר' אליעזר אומר: ינתנו\u0004 כולם \u0003במתן ארבע. ר' יהושע אומר: ינתנו\u0004 כולם \u0003במתנה אחת,\u0004 שהרי גם הניתנים במתן ארבע, אם נתנם במתנה אחת — כיפר (לעיל זבחים לו,ב).","\u0003אמר לו ר' אליעזר\u0004 לר' יהושע: לשיטתך, שיינתנו כולם במתנה אחת, נמצא שלגבי דם העולה \u0003הרי הוא עובר\u0004 בכך \u0003על\u0004 איסור \u0003\"בל תגרע\"\u0004 (\"את כל הדבר אשר אנכי מצוה אתכם אותו תשמרו לעשות לא תוסף עליו ולא תגרע ממנו\", דברים יג, א)! \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יהושע:\u0004 אף לשיטתך, \u0003הרי הוא עובר על\u0004 דם הבכור משום איסור \u0003\"בל תוסיף\"!\u0004","\u0003אמר לו ר' אליעזר: לא נאמר \"בל תוסיף\"\u0004 לגבי דם הבכור \u0003אלא כשהוא בעצמו,\u0004 אבל כאן הריהו מעורב בדבר אחר שנעשה כדינו! \u0003אמר לו ר' יהושע:\u0004 אף לשיטתי, \u0003לא נאמר \"בל תגרע\"\u0004 לגבי דם העולה \u0003אלא כשהוא בעצמו,\u0004 ולא כשהוא מעורב בדבר אחר! \u0003ועוד אמר ר' יהושע\u0004 לחזק את דבריו: \u0003כשנתת\u0004 מתן ארבע, כשיטת ר' אליעזר — \u0003עברת\u0004 בכך \u0003על \"בל תוסיף\"\u0004 לגבי דם הבכור \u0003ו\u0004באופן שבו \u0003עשית מעשה בידך.\u0004 ואילו \u0003כשלא נתת\u0004 אלא מתנה אחת בלבד, אמנם \u0003עברת\u0004 בכך \u0003על \"בל תגרע\"\u0004 לגבי דם העולה, אבל \u0003לא עשית מעשה בידך.\u0004","שנינו במשנה את שיטת ר' אליעזר, אם נתערבה כוס דם של בעלי מומים בכוסות דם של קרבנות כשרים, וקרב כוס אחד, שאר הכוסות כשרים להקרבה. \u0003אמר ר' אלעזר: לא הכשיר ר' אליעזר\u0004 את שאר הכוסות \u0003אלא\u0004 רק כאשר הוא מקריב אותם \u0003שנים שנים,\u0004 מאחר שאחד מהם הוא בוודאי כשר. \u0003אבל\u0004 להקריב את הכוסות \u0003אחד אחד\u0004 — \u0003לא\u0004 התיר ר' אליעזר.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב דימי\u0004 ממה ששנינו במשנתנו: \u0003וחכמים\u0004 (החולקים על ר' אליעזר) \u0003אומרים: אפילו קרבו כולן, חוץ מאחד מהן\u0004 — \u0003ישפך לאמה,\u0004 משמע שגם במקרה זה, שלא נותר אלא אחד, ר' אליעזר מכשיר! \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יעקב לר' ירמיה בר תחליפא: אסברא\u0004 \u0005[אסביר]\u0006 \u0003לך מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אחד\"\u0004 האמור במשנתנו? \u0003זוג אחד,\u0004 כלומר, שני כוסות. מחלוקת ר' אליעזר וחכמים נשנתה לעיל (זבחים עז,ב) גם בתערובת איברים של קרבן בעל מום וקרבנות כשרים.","ומעירים: \u0003וצריכא\u0004 \u0005[וצריך]\u0006 לשנות את שתי המחלוקת במשנה, \u0003דאי איתמר בהא\u0004 \u0005[שאם\u0006 היתה \u0005נאמרת\u0006 מחלוקתם רק \u0005בזו,\u0006 באיברים שנתערבו\u0005],\u0006 היינו אומרים: דווקא \u0003בהא קאמר\u0004 \u0005[בזו אומר]\u0006 \u0003ר' אליעזר\u0004 להכשיר את השאר, \u0003משום דאיתעביד ביה\u0004 \u0005[ש\u0006כבר \u0005נעשתה בו,\u0006 בקרבן\u0005]\u0006 \u0003כפרתו\u0004 (זריקת דמו, שהיא המכפרת), שהרי הקרבת איברי הקרבן באה לאחר זריקת הדם, \u0003אבל בהא אימא מודי להו לרבנן\u0004 \u0005[ב\u0006מקרה \u0005זה,\u0006 בכוסות שנתערבו, טרם שנעשתה כפרתם, \u0005אמור\u0006 ש\u0005מודה להם לחכמים]\u0006 שאין השאר כשרים.","ולהיפך, \u0003ואי איתמר בהא\u0004 \u0005[ואם היתה נאמרת\u0006 מחלוקתם רק \u0005בזה,\u0006 בכוסות שנתערבו\u0005],\u0006 הייתי אומר: דווקא \u0003בהא קאמרי רבנן\u0004 \u0005[בזה אמרו חכמים]\u0006 שהשאר פסולים, \u0003אבל בהא אימא מודו\u0004 \u0005[בזה,\u0006 באיברים שנתערבו, \u0005אמור\u0006 ש\u0005מודים]\u0006 \u0003לר' אליעזר\u0004 שהשאר כשרים להקרבה, שהרי נזרק דמם, על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמרו שתי המחלוקות.","ועוד במחלוקת ר' אליעזר וחכמים בתערובת, \u0003תנן התם\u0004 \u0005[שנינו שם\u0006 במשנה במסכת פרה\u0005]:\u0006 \u0003צלוחית\u0004 של מי חטאת (מי פרה אדומה) \u0003שנפלו לתוכה מים\u0004 סתם בשיעור \u0003כל שהו\u0004 — \u0003ר' אליעזר אומר: יזה\u0004 הכהן על הטמא \u0003שתי הזאות,\u0004 שבאופן זה בוודאי נטהר הטמא ממי החטאת. \u0003וחכמים פוסלין\u0004 הכל.","ושואלים: \u0003בשלמא רבנן\u0004 \u0005[נניח,\u0006 מובן הדבר שיטת \u0005חכמים]\u0006 הפוסלים, שהם \u0003סברי\u0004 \u0005[סבורים]\u0006 ש\u0003יש בילה\u0004 (בלילה), כלומר, אנו מניחים כי נוזלים המתערבים זה בזה נבללים לגמרי, ובכל הזאה יש ממי החטאת. \u0003ו\u0004מכל מקום אינו נטהר באף אחת מן ההזאות, מאחר ש\u0003הזאה צריכה\u0004 מי חטאת ב\u0003שיעור\u0004 הזאה, והרי בכל הזאה יש גם מן המים אחרים. \u0003ו\u0004לא יועיל הדבר להזות פעמיים, משום שלדעתם \u0003אין מצטרפין להזאות,\u0004 כלומר, אין מי חטאת שבשתי הזאות מצטרפים לטהר.","\u0003אלא ר' אליעזר מאי קסבר\u0004 \u0005[מה הוא סבור]?\u0006 \u0003אי קסבר\u0004 \u0005[אם סבור הוא]\u0006 ש\u0003אין\u0004 לסמוך על כך שיש \u0003בילה,\u0004 אם כן גם \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003מזה\u0004 הכהן \u0003שתי הזאות מאי הוי\u0004 \u0005[מה בכך]?\u0006 והלוא יש לחשוש \u0003דילמא תרוייהו מיא קא מזי\u0004 \u0005[שמא\u0006 ב\u0005שתיהם מים\u0006 סתם \u0005הוא מזה]\u0006 ולא ממי החטאת! \u0003אלא\u0004 בהכרח, \u0003קא סבר\u0004 \u0005[סבור הוא]\u0006 ש\u0003יש בילה,\u0004 ובכל הזאה יש ממי החטאת. ומעתה, \u0003אי קסבר\u0004 \u0005[אם סבור]\u0006 הוא ש\u0003אין הזאה צריכה שיעור, למה לי שתי הזאות?\u0004 הרי גם בהזאה אחת יצא! \u0003אלא\u0004 צריך לומר ש\u0003קסבר\u0004 \u0005[סבור הוא]\u0006 \u0003הזאה צריכה שיעור. ו\u0004מעתה יש לשאול: \u0003אי קסבר\u0004 \u0005[אם סבור הוא]\u0006 \u0003אין מצטרפין להזאות, כי\u0004 \u0005[כאשר]\u0006 \u0003מזה שתי הזאות מאי הוי\u0004 \u0005[מה יהיה\u0006 בכך\u0005]?\u0006 \u0003ואי נמי\u0004 \u0005[ואם גם כן]\u0006 תאמר ש\u0003מצטרפין להזאות, מי יימר דמלא ליה שיעורא\u0004 \u0005[מי יאמר שהתמלא לו השיעור]\u0006 על ידי שתי ההזאות? שמא רוב מה שהיזה היה מן המים הפסולים!","\u0003אמר ריש לקיש: לעולם\u0004 לדעת ר' אליעזר \u0003יש בילה, ו\u0004כן סבור הוא ש\u0003הזאה צריכה שיעור,\u0004 ולדעתו, הזאות מצטרפות. \u0003ו\u0004אין לחשוש שבשתי ההזאות גם יחד אין שיעור הזאה, משום ש\u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון שנתערבו אחת באחת\u0004 מי חטאת בשיעור הזאה שנתערבו במים פסולים בשיעור דומה. ומעתה, כשמזה שתי הזאות נמצא שהיזה מי החטאת שיש בהם שיעור הזאה.","\u0003רבא אמר\u0004 הסבר אחר: \u0003לעולם\u0004 ר' אליעזר סבור ש\u0003יש בילה,\u0004 ובכל הזאה יש ממי החטאת. \u0003ו\u0004כן סבור הוא ש\u0003הזאה אין צריכה שיעור,\u0004 ולפי זה די מעיקר הדין בהזאה אחת. \u0003ו\u0004אולם \u0003קנסא\u0004 \u0005[קנס]\u0006 ש\u0003קנסו\u0004 אותו \u0003רבנן\u0004 \u0005[חכמים]\u0006 את מי שנתערבו לו מים פסולים במי החטאת, \u0003כי היכי דלא משתרש ליה\u0004 \u0005[כדי שלא יהא לו רווח בזה],\u0006 ולא יבואו לערב מים במי החטאת.","\u0003רב אשי אמר\u0004 הסבר אחר: ר' אליעזר סבור ש\u0003אין בילה,\u0004 ולפיכך, אם יזה הזאה אחת יש לחשוש שמא אין בה כלל ממי החטאת, ולכן \u0003יזה שתי הזאות.\u0004","על הסברו של ריש לקיש, שלדעת ר' אליעזר הזאה צריכה שיעור, \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו, \u0003רבי אומר: לדברי\u0004 \u0003ר' אליעזר\u0004 המכשיר בשתי הזאות, \u0003הזאה כל שהוא מטהרת,\u0004 ו\u0003הזאה אין צריכה שיעור,\u0004 ואפילו \u0003הזאה\u0004 שיש בה \u0003מחצה כשר ומחצה פסול\u0004 גם היא מטהרת!"],["\u0003ועוד\u0004 יש להקשות לשיטת רב אשי, הסבור כי לדעת ר' אליעזר אין בילה: הרי \u0003תניא בהדיא\u0004 \u0005[שנויה\u0006 ברייתא \u0005במפורש]:\u0006 דמי חטאת \u0003הניתנין למעלה שנתערבו ב\u0004דמי עולה ה\u0003ניתנין למטה\u0004 — \u0003ר' אליעזר אומר: יתן למעלה\u0004 לשם חטאת, ואחר כך יתן למטה לשם עולה, והעליונים \u0003ו\u0004גם \u0003התחתונים עלו לו.\u0004","\u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 \u0003אין בילה, אמאי\u0004 \u0005[מדוע]\u0006 \u0003עלו לו? דילמא קיהיב\u0004 \u0005[שמא נמצא נותן]\u0006 \u0003עליונים למטה והתחתונים למעלה!\u0004","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 \u0003כגון דאיכא רובא\u0004 \u0005[שיש רוב]\u0006 \u0003עליונים, וקא יהיב\u0004 \u0005[והוא נותן]\u0006 \u0003למעלה\u0004 דם כ\u0003שיעור\u0004 הדמים ה\u0003תחתונים\u0004 שהיו בתערובת \u0003ועוד\u0004 דם, כך שבוודאי נתן למעלה מדם העליונים.","ומקשים: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003\"תחתונים עלו לו\" קתני\u0004 \u0005[שנה],\u0006 ואילו לפי הסבר זה, יתכן שנתן את כל דמי העולה למעלה, ומדוע עלו לו? ומשיבים: אין הכוונה שעלו לו לשם דמי עולה, שדמה ניתן למטה, אלא שעלו לו \u0003לשם שירים\u0004 של חטאת, שצריך לשפוך אותם אל יסוד המזבח.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה נוספת ממה ששנינו: \u0003נתן למטה ולא נמלך\u0004 מה יעשה עתה? \u0003ר' אליעזר אומר: יחזור ויתן\u0004 מן התערובת \u0003למעלה,\u0004 והעליונים \u0003והתחתונים עלו לו.\u0004 ואם לדעת ר' אליעזר אין בילה, מדוע עלו לו? שמא נתן את העליונים למטה ואת התחתונים למעלה!","ומשיבים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר \u0003ברובא\u0004 \u0005[ברוב]\u0006 שהיו מה\u0003עליונים, וקא יהיב\u0004 \u0005[והוא נותן]\u0006 \u0003למעלה שיעור תחתונים ועוד,\u0004 כך שבוודאי נתן מקצת מן העליונים במקומם. ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"תחתונים עלו לו\" קתני\u0004 \u0005[שנה]!\u0006 ולפי הסבר זה יתכן שנתן את כולם למעלה, ומדוע עלו לו? ומשיבים: עלו לו \u0003לשם שירים\u0004 של החטאת.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו: \u0003נתנן למעלה ולא נמלך\u0004 — \u0003אלו ואלו מודים שיחזור ויתן למטה, ואלו ואלו עלו לו.\u0004 ואם לדעת ר' אליעזר אין בילה — שמא נתן את התחתונים למעלה ואת העליונים למטה!","ומשיבים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר \u0003ברובא\u0004 \u0005[ברוב]\u0006 \u0003עליונים, וקא יהיב\u0004 \u0005[והוא נותן]\u0006 \u0003למעלה שיעור תחתונים ועוד,\u0004 ויוצא ידי חובת העליונים בלבד.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אלו ואלו עלו לו קתני\u0004 \u0005[שנה]!\u0006 ומשיבים: \u0003מי קתני\u0004 \u0005[האם שנה]\u0006 לגבי הלכה זו: \u0003אלו ואלו מודים\u0004 שאלו ואלו עלו לו? \u0003\"אלו ואלו עלו לו\" קתני\u0004 \u0005[שנה]\u0006 בלבד. שאף שבתחילה שנינו שאלו ואלו מודים שיחזור ויתן למטה, כלומר, שאף ר' אליעזר סבור כן, ואולם \u0003סיפא\u0004 \u0005[בסוף],\u0006 ששנינו: אלו ואלו עלו לו, \u0003אתאן לרבנן\u0004 \u0005[הגענו ל\u0006שיטת \u0005חכמים\u0006 בלבד\u0005],\u0006 \u0003דאמרי\u0004 \u0005[ש\u0006הם \u0005אומרים]:\u0006 \u0003יש בילה,\u0004 ולכן אלו ואלו עלו לו.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו במשנתנו: \u0003הניתנין במתנה אחת שנתערבו בניתנין במתנה אחת\u0004 — \u0003ינתנו במתנה אחת. ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 כי לדעת ר' אליעזר \u0003אין בילה, אמאי\u0004 \u0005[מדוע]\u0006 \u0003ינתנו במתנה אחת? דילמא מהאי קיהיב ומהאי לא קיהיב\u0004 \u0005[שמא מזה הוא נותן ומזה אינו נותן]!\u0006 ומשיבים: מדובר \u0003כגון שנתערבו\u0004 שיעור מתנה \u0003אחת ב\u0004שיעור מתנה \u0003אחת\u0004 ולא יותר, ובוודאי נתן משניהם.","ועוד מקשים: הרי שנינו כי דם שטעון \u0003מתן ארבע\u0004 שנתערב \u0003ב\u0004דם שטעון \u0003מתן ארבע\u0004 יינתן במתן ארבע, ואם אין בילה — שמא אינו נותן אלא מדמו של אחד! ומשיבים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר \u0003שנתערבו\u0004 שיעור \u0003ארבע\u0004 מתנות \u0003ב\u0004שיעור \u0003ארבע\u0004 מתנות, ובוודאי נתן משניהם.","ועוד מקשים: והרי שנינו שאם נתערבו הניתנים \u0003מתן ארבע ב\u0004ניתנים \u0003מתנה אחת\u0004 שיתן במתן ארבע. וגם כאן, אם לדעת ר' אליעזר אין בילה — שמא לא נתן אלא מדמו של אחד הקרבנות!"],["\u0003וכי תימא\u0004 \u0005[וכי תאמר]:\u0006 \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר \u0003בנתערב\u0004 שיעור ארבע מתנות \u0003ב\u0004מתנה \u0003אחת\u0004 בדיוק, ובוודאי נותן משניהם, \u0003אי הכי\u0004 \u0005[אם כך],\u0006 מה ש\u0003אמר לו ר' יהושע\u0004 לר' אליעזר: \u0003הרי הוא עובר על \"בל תוסיף\"\u0004 לגבי הראוי לינתן במתנה אחת, \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003\"בל תוסיף\" מהיכא\u0004 \u0005[מהיכן]?\u0006 הרי אין ממנו אלא שיעור של מתנה אחת!","\u0003אלא אמר רבא: בבלול לא פליגי\u0004 \u0005[לא נחלקו]\u0006 ר' אליעזר וחכמים במשנתנו, \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה \u0003בכוסות\u0004 שנתערבו, ואין יודעים איזה דם יש בכל אחד מהם, ובכך נחלקו: \u0003לר' אליעזר אית ליה\u0004 \u0005[יש לו\u0006 הוא סבור\u0005]\u0006 כי \u0003רואין\u0004 את הדם שניתן שלא כדינו כאילו הוא מים, ומותר לעשות כן, \u0003לרבנן לית להו\u0004 \u0005[לחכמים אין להם]\u0006 \u0003רואין\u0004 ולכן יישפך הכל לאמה.","ושואלים: \u0003ובבלול לא פליגי\u0004 \u0005[חלוקים]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' יהודה: לא נחלקו ר' אליעזר וחכמים על דם חטאת\u0004 שניתן למעלה \u0003שנתערב בדם עולה\u0004 שניתן למטה, \u0003שיקרב\u0004 לדעת הכל. וכן לא נחלקו אם נתערב דם כשר \u0003ב\u0004דם \u0003רובע ונרבע שלא יקרב. על מה נחלקו? על דם תמימה שנתערב בדם בעלת מום, שר' אליעזר אומר: יקרב, בין בבלול בין בכוסות, וחכמים אומרים: לא יקרב!\u0004","ומשיבים: \u0003ר' יהודה אליבא\u0004 \u0005[לפי שיטת]\u0006 \u0003ר' אליעזר מתני\u0004 \u0005[היה שונה]\u0006 את מחלוקתם \u0003בין בבלול בין בכוסות, ו\u0004אילו \u0003רבנן\u0004 \u0005[חכמים]\u0006 ששנו את משנתנו, לשיטתם דווקא \u0003בכוסות פליגי\u0004 \u0005[נחלקו]\u0006 ר' אליעזר וחכמים.","שנינו במשנתנו כי דם חטאת הניתן למעלה שנתערב בדם עולה הניתן למטה, לדעת ר' אליעזר יתן למעלה, ורואה אני את התחתונים למעלה כאילו הם מים, ויחזור ויתן למטה, ולדעת חכמים יישפך הכל לאמה. ועל כך \u0003אמר אביי: לא שנו\u0004 שלדעת חכמים יישפך הכל לאמה \u0003אלא\u0004 שנתערבו \u0003תחלת\u0004 דם \u0003חטאת,\u0004 שצריך להינתן למעלה, \u0003ו\u0004דם \u0003עולה,\u0004","\u0003אבל סוף\u0004 דם \u0003חטאת,\u0004 כלומר, השיריים שנותרו וצריך לשופכם על יסוד המזבח (ויקרא ד, כה), \u0003[ו\u0004דם \u0003עולה]\u0004 שנתערבו — \u0003דברי הכל\u0004 \u0003מקום\u0004 דם ה\u0003עולה,\u0004 למטה מחוט הסיקרא, הוא \u0003מקום שיריים\u0004 של חטאת, לפי שמשם הם שותתים ליסוד. ויתן את כל הדם על קיר המזבח למטה מחוט הסיקרא. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יוסף, הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב יהודה: שירים צריכין איצטבא\u0004 כלומר, להינתן על גג היסוד עצמו, ולא על קיר המזבח כדם העולה. ואם כן, גם במקרה זה נחלקו ר' אליעזר וחכמים.","\u0003וכן\u0004 נחלקו בכך אמוראי ארץ ישראל, \u0003אמר ר' שמעון\u0004 בן לקיש: \u0003לא שנו אלא תחלת חטאת ועולה, אבל סוף חטאת ועולה\u0004 — \u0003דברי הכל מקום עולה מקום שירים. אמר ר' יוחנן, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' אלעזר: עדיין היא מחלוקת.\u0004","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב הונא בר יהודה\u0004 ממה ששנינו בברייתא: נאמר לגבי הבכורות \u0003\"קדש הם\"\u0004 (במדבר יח, יז), והדגשה זו באה ללמד \u0003ש\u0004גם \u0003אם נתערב\u0004 דמם \u0003בדם קדשים אחרים\u0004 — \u0003יקרבו,\u0004 שאינם בטלים. \u0003מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה גם ל\u0003סוף\u0004 (שיירי דם) \u0003עולה ו\u0004לדם \u0003בכור\u0004 שנתערבו, שזורקם יחד על המזבח למטה מחוט הסיקרא? \u0003ושמע מינה\u0004 \u0005[ולמד מכאן]:\u0006 \u0003מקום עולה,\u0004 שהוא גם מקום דם הבכור, הריהו \u0003מקום שירים!\u0004 ודוחים: \u0003לא,\u0004 הכוונה היא ל\u0003תחילת\u0004 דם \u0003עולה ו\u0004לדם \u0003בכור.\u0004","ומקשים: \u0003ומאי קא משמע לן\u0004 \u0005[ומה משמיע לנו]\u0006 הכתוב לפי הסבר זה, ש\u0003אין עולין מבטלים זה את זה?\u0004 אולם \u0003האי\u0004 \u0005[\u0006דבר \u0005זה]\u0006 \u0003מ\u0004מה שנאמר \u0003\"ולקח מדם הפר ומדם השעיר\"\u0004 (ויקרא טז, יח) \u0003נפקא\u0004 \u0005[יוצא]!\u0006 ומשיבים: \u0003תנאי\u0004 \u0005[מחלוקת תנאים]\u0006 \u0003היא\u0004 בענין זה, \u0003איכא דנפקא ליה מהכא, ואיכא דנפקא ליה מהכא\u0004 \u0005[יש שיוצא לו\u0006 דין זה \u0005מכאן, ויש שיוצא לו\u0006 דין זה \u0005מכאן].\u0006","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רבא\u0004 ממה ששנינו בברייתא: נאמר לגבי קרבן עולה: \u0003\"והקריבו בני אהרן את הדם וזרקו את הדם\"\u0004 (ויקרא א, ה), והביטוי \"הדם\" שהוא מיותר, מלמד כי שמו של הדם נשאר עליו גם אם נתערב בדם אחר, וייזרק כדינו. ויש לשאול: \u0003מה\u0004"],["\u0003תלמוד לומר \"דם\" \"דם\"\u0004 פעמיים? ומשיבים: \u0003ש\u0004אם מ\"דם\" אחד \u0003יכול\u0004 אתה לומר: \u0003אין לי אלא אלו\u0004 (כלומר, דמי עולה) \u0003שנתערבו ב\u0004דם \u0003תמורתה, ש\u0004הרי \u0003אף\u0004 אם נתערבה בה \u0003מחיים,\u0004 כלומר, בהמה בבהמה — \u0003תקרב\u0004 העולה והתמורה, \u0003מנין לרבות\u0004 גם \u0003תודה ושלמים\u0004 שאם נתערבו בעולה מחיים לא היו קרבים?","וגם אם תאמר: \u0003מרבה אני\u0004 בכלל ה\"דם\" הראשון דם עולה שנתערב בדם \u0003תודה ושלמים,\u0004 \u0003ש\u0004כן \u0003באין בנדר ונדבה כמותה, מנין לרבות את האשם\u0004 שאינו בא בנדר ונדבה?","וגם אם \u0003מרבה אני\u0004 בכלל ה\"דם\" הראשון \u0003את\u0004 דם \u0003האשם,\u0004 שדם עולה אינו בטל בו, משום \u0003שטעון מתן ארבע כמותו\u0004 (כלומר, שתים שהן ארבע), \u0003דם\u0004 \u0003בכור ומעשר ופסח\u0004 שניתנים רק במתנה אחת, שנתערב בהם דם עולה, \u0003מנין? תלמוד לומר \"דם\" \"דם\"\u0004 (ויקרא א, ה), ללמד שבכל אופן שנתערב דם העולה בדם קרבן אחר (שדמו ניתן למטה) — יקרב.","\u0003מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה ל\u0003סוף\u0004 (שיירי דם) \u0003עולה ו\u0004לתחילת דם \u0003בכור\u0004 שנתערבו? \u0003ושמע מינה\u0004 \u0005[ולמד מכאן]:\u0006 \u0003מקום עולה מקום שירים\u0004 הוא, שהרי מקריבים אותם יחד!","ודוחים: \u0003לא,\u0004 הכוונה היא ל\u0003תחילת\u0004 דם \u0003עולה ובכור.\u0004 ומקשים: \u0003ומאי קא משמע לן\u0004 \u0005[ומה משמיע לנו],\u0006 ש\u0003אין עולין מבטלין זה את זה?\u0004 והרי דבר זה \u0003מ\"ולקח מדם הפר ומדם השעיר\"\u0004 (ויקרא טז, יח) \u0003נפקא\u0004 \u0005[יוצא],\u0006 שהכהן הגדול מערבם יחד כדי לתת מהם על קרנות מזבח הזהב, ואין דם השעיר בטל בדם הפר! ומשיבים: \u0003תנאי\u0004 \u0005[מחלוקת תנאים]\u0006 \u0003היא, איכא דנפקא ליה מהכא, ואיכא דנפקא ליה מהכא\u0004 \u0005[יש שיוצא לו\u0006 המקור לכך \u0005מכאן, ויש שיוצא לו מכאן].\u0006 נמצא איפוא ששלושה מקורות שונים ניתנו לדין זה, שאין עולים מבטלים זה את זה: \"קודש הם\" (במדבר יח, יז), \"ולקח מדם הפר ומדם השעיר\" (ויקרא טז, יח), \"דם\" \"דם\" (ויקרא א, ה).","ומעירים: \u0003והני תנאי\u0004 \u0005[ותנאים אלה]\u0006 ש\u0003מ\"ולקח מדם הפר ומדם השעיר\" לא ילפי\u0004 \u0005[אינם למדים],\u0006 \u0003קסברי\u0004 \u0005[סבורים הם]\u0006 ש\u0003אין מערבין\u0004 את דם הפר ודם השעיר כדי \u0003ל\u0004תת על ה\u0003קרנות,\u0004 אלא נותן כל אחד מהם לחוד. ואלו ש\u0003מ\"דם\" \"דם\" לא יליף\u0004 \u0005[אינם למדים]\u0006 — הלימוד מ\u0003\"דם\" \"דם\" לא משמע להו\u0004 \u0005[להם].\u0006","\u0003אלא\u0004 אלה שאינם למדים \u0003מ\"קדש הם\"\u0004 האמור לגבי בכורות (במדבר יח, יז), שאינם בטלים בתערובת, \u0003מאי טעמא לא ילפי\u0004 \u0005[מה טעם אינם למדים]\u0006 משם? ומשיבים: \u0003קסברי\u0004 \u0005[סבורים הם]\u0006 שכך יש לדרוש כתוב זה: \u0003\"קדש הם\"\u0004 — \u0003הם קריבין, ואין תמורתן\u0004 של בכורות \u0003קריבה.\u0004","ומן הצד האחר, \u0003ואידך\u0004 \u0005[והאחר]\u0006 מהיכן הוא למד דין זה? \u0003נפקא ליה\u0004 \u0005[יוצא לו]\u0006 הדבר \u0003מ\u0004מה שנאמר לגבי בכור: \u0003\"אם שור אם שה לה' הוא\"\u0004 (ויקרא כז, כו), וההדגשה במילה \"הוא\" כוונתה: \u0003הוא קרב, ואין תמורתו קריבה.\u0004 ושבים לשאלה האם מקום דם העולה הוא מקום שיירי הקרבנות.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו בברייתא: דמים הניתנים למעלה שנתערבו בניתנים למטה, שלדעת חכמים יישפכו לאמה, אם \u0003נתן למעלה ולא נמלך\u0004 — \u0003אלו ואלו מודים שיחזור ויתן למטה, אלו ואלו עולין לו.\u0004","\u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר \u0003דאיערוב\u0004 \u0005[שהתערבו]\u0006 \u0003חטאת ועולה? וכיון דיהיב ליה\u0004 \u0005[שנתן לו]\u0006 כבר מדם החטאת \u0003למעלה,\u0004 מה שנותר מדם החטאת \u0003הוו להו\u0004 \u0005[הרי הם]\u0006 \u0003שירים, וקתני\u0004 \u0005[ושנינו]:\u0006 \u0003אלו ואלו מודים שיחזור ויתן למטה\u0004 את דם העולה עם שיירי החטאת, \u0003ושמע מינה\u0004 \u0005[ולמד מכאן]:\u0006 \u0003מקום עולה מקום שירים!\u0004","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב יצחק בר יוסף\u0004 מארץ ישראל \u0003אמר, אמרי במערבא\u0004 \u0005[אומרים בארץ ישראל]\u0006: \u0003הכא במאי עסקינן\u0004 \u0005[כאן,\u0006 שנתערבו עליונים ותחתונים, \u0005במה אנו עוסקים]\u0006? לא בתערובת דם חטאת ודם עולה, אלא \u0003כגון דאיערב\u0004 \u0005[שהתערב]\u0006 דם \u0003חטאת החיצונה,\u0004 שניתן למעלה, \u0003בשירים\u0004 של חטאת פנימית (שדמה ניתן תחילה בהיכל), שצריך ליתנם למטה על היסוד. ולאחר שנתן מן התערובת למעלה, יש בידיו תערובת שיריים בלבד, שמקומם שווה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי,\u0004 ומדוע צריך להזכיר בענין זה שיירי חטאת פנימית? \u0003ונימא מר\u0004 \u0005[ושיאמר אדוני]\u0006: \u0003כגון דאיערב\u0004 \u0005[שהתערב]\u0006 דם חטאת חיצונה \u0003בשירים\u0004 של חטאת חיצונה! \u0003דלמא הא קא משמע לן\u0004 \u0005[שמא זה משמיע לנו],\u0006 ש\u0003אפילו למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 ש\u0003שירים\u0004 של חטאות פנימיות \u0003מעכבין\u0004 את הכפרה, אם לא נתנו מהם על היסוד, מכל מקום אם \u0003חסרו\u0004 השיריים, כמו כאן, שנתן תחילה מן התערובת למעלה — \u0003אין מעכבין\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא תוספאה לרבינא:\u0004 כיצד מביאים ראיה מברייתא זו לענייננו? \u0003הא אוקימנא ההיא\u0004 \u0005[הרי\u0006 כבר \u0005העמדנו אותה]\u0006 (לעיל זבחים פ,ב) \u0003ב\u0004תערובת דמים עליונים ותחתונים שיש בה \u0003רובא\u0004 \u0005[רוב]\u0006 מן הדמים ה\u0003עליונים, וקא יהיב\u0004 \u0005[ונותן]\u0006 \u0003למעלה שיעור תחתונים ועוד! אמר ליה\u0004 \u0005[לו]\u0006 רבינא: \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 נאמרו\u0005]\u0006 \u0003למאן דאמרו מעיקרא\u0004 \u0005[למי שאמרו מתחילה]\u0006 כי ר' אליעזר וחכמים נחלקו בדמים שנבללו, וכדי לבאר את טעמו של ר' אליעזר הסבור ש\u0003אין בילה.\u0004 ואילו לפי ה\u0003מסקנא בכוסות פליגי\u0004 \u0005[חלוקים הם],\u0006 ולא בדמים שנבללו.","דמי הקרבנות \u0003הניתנין בפנים\u0004 (בהיכל, בין הבדים, על הפרוכת ועל מזבח הזהב), \u0003שנתערבו ב\u0004דמי קרבנות ה\u0003ניתנין בחוץ\u0004 (על המזבח החיצון שבעזרה) — אין להם תקנה, שאין משנים מקומו של דם זה כדי לקיים מצוותו של דם אחר, ו\u0003ישפכו\u0004 כולם \u0003לאמה\u0004 (תעלה שבעזרה). אם הלך הכהן על דעת עצמו \u0003ונתן\u0004 מתערובת דמים אלו תחילה \u0003בחוץ,\u0004 \u0003ו\u0004אחר כך \u0003חזר ונתן\u0004 מן התערובת \u0003בפנים\u0004 ההיכל — הרי זה \u0003כשר.\u0004","ואם נתן מתערובת זו בתחילה \u0003בפנים ו\u0004רק אחרי כן \u0003חזר ונתן בחוץ\u0004 — \u0003ר' עקיבא פוסל\u0004 את הניתן בחוץ, \u0003וחכמים מכשירים.\u0004 והסבר מחלוקתם, \u0003שר' עקיבא אומר: כל דמים\u0004 שדינם לינתן בחוץ \u0003שנכנסו לכפר בהיכל\u0004 — \u0003פסולין\u0004 הם. \u0003וחכמים אומרים:\u0004 דם \u0003חטאת\u0004 חיצונה \u0003בלבד\u0004 הוא הנפסל אם הוכנס להיכל כדי להזות שם, שנאמר: \"וכל חטאת אשר יובא מדמה אל אוהל מועד לכפר בקדש לא תאכל\" (ויקרא ו, כג), אבל לא דמי שאר קרבנות. \u0003ר' אליעזר אומר: אף\u0004 דם \u0003האשם\u0004 דינו כחטאת, \u0003ש\u0004הרי \u0003נאמר: \"כחטאת כאשם\u0004 תורה אחת להם\" (ויקרא ז, ז), אבל לא דמי שאר קרבנות.","על מה ששנינו במשנה ללא מחלוקת, שדמים הניתנים בחוץ שנתערבו בדמים הניתנים בפנים יישפכו לאמה, שואלים: \u0003וניפלוג נמי\u0004 \u0005[ושיחלוק גם כן]\u0006 \u0003ר' אליעזר בהא\u0004 \u0005[ב\u0006הלכה \u0005זו],\u0006 כשם שחלק במשנה הקודמת בתערובת דמים הניתנים למטה בדמים הניתנים למעלה, ויאמר שיש להתייחס אל הדמים הניתנים שלא במקומם כאל מים!","ומשיבים: \u0003היכי ליעביד\u0004 \u0005[כיצד ייעשה]?\u0006 \u0003ניתיב\u0004 \u0005[ניתן]\u0006 תחילה מדמי התערובת \u0003בחוץ, והדר ניתיב\u0004 \u0005[ונחזור\u0006 ו\u0005ניתן\u0006 אחר כך\u0005]\u0006 מדמי התערובת \u0003לפנים\u0004 — דבר זה אינו אפשרי, משום ש\u0003כשם שמצוה להקדים\u0004 את מתן דמים ה\u0003עליונים לתחתונים,\u0004 כלומר, להקדים דם חטאת לדם עולה, מאחר וחטאת באה לכפר, \u0003כך מצוה להקדים\u0004 נתינת דמים ב\u0003פנים ל\u0004נתינת דמים ב\u0003חוץ.\u0004"],["\u0003ו\u0004אם \u0003ניתיב\u0004 \u0005[ניתן]\u0006 בתחילה מתערובת הדמים \u0003לפנים, ו\u0004אחר כך \u0003הדר ניתיב\u0004 \u0005[נחזור וניתן]\u0006 ממנה \u0003לחוץ\u0004 — אף שפתרון זה קיים ברוב הקרבנות שדמם ניתן בחוץ, מכל מקום \u0003כיון דאיכא\u0004 \u0005[שיש]\u0006 \u0003חטאת ואשם, דכי\u0004 \u0005[ש\u0006לדעת ר' אליעזר \u0005כאשר]\u0006 \u0003נכנס דמן\u0004 להיכל הם \u0003פסולין\u0004 מלהינתן על המזבח בחוץ, ובהם לא קיים פתרון זה — \u0003לא פסיקא ליה\u0004 \u0005[פסוק,\u0006 חתוך, \u0005לו\u0006 הדבר\u0005],\u0006 אין זה פתרון שלם לגמרי, ולכן לא חלק ר' אליעזר במשנה זו.","ושנינו במשנה: \u0003שהיה ר' עקיבא אמר:\u0004 כל הדמים שנכנסו לכפר בהיכל, נפסלו בכך. ודנים כיצד למד ר' עקיבא דבר זה מן הכתוב האמור בענין זה, שאינו עוסק לכאורה אלא בחטאת ולא בשאר קרבנות, שנאמר: \"וכל חטאת אשר יובא מדמה אל אהל מועד לכפר בקודש לא תאכל, באש תשרף\" (ויקרא ו, כג). \u0003אמר רב יהודה אמר שמואל: משל למה הדבר דומה? לתלמיד ש\u0004בתוך כדי הסעודה \u0003מזג\u0004 (עירב, מהל) יין \u0003לרבו ב\u0004מים \u0003חמין, ו\u0004שוב \u0003אמר לו\u0004 הרב לתלמיד: \u0003מזוג לי! אמר לו\u0004 התלמיד לרב: \u0003במה?\u0004 כלומר, האם בחמין או בצונן? \u0003אמר לו\u0004 הרב לתלמיד: וכי \u0003לא בחמין אנו עסוקין\u0004 עד כה?! \u0003עכשיו,\u0004 משחזרתי וביקשתי ממך למזוג, כוונתי שתמזוג לי \u0003בין בחמין בין בצונן.\u0004","\u0003הכא נמי\u0004 \u0005[כאן גם כן],\u0006 \u0003מכדי\u0004 \u0005[הרי]\u0006 \u0003בחטאת עסקינן ואתי\u0004 \u0005[עסוקים אנו ובאים]\u0006 באותה פרשה (ויקרא ו, פסוק יז ואילך), אם כן \u0003\"חטאת\" דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 בפסוק זה \u0003למה לי,\u0004 והרי ברור שבחטאת מדובר! \u0003אלא\u0004 בדומה למשל, נאמרה חטאת כדי ללמדנו ש\u0003לאו\u0004 \u0005[לא]\u0006 ב\u0003חטאת\u0004 בלבד \u0003קאמינא לה\u0004 \u0005[אומר אני\u0006 הלכה \u0005זו]\u0006 שנפסל הדם בכניסתו לפנים, \u0003אלא\u0004 ב\u0003כל\u0004 ה\u0003קדשים.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע:\u0004 לפי הסבר זה יש להסיק דווקא את המסקנה ההפוכה, שכן \u0003מכדי\u0004 \u0005[הואיל]\u0006 ובפרשה זו כבר \u0003איתרבו\u0004 \u0005[התרבו]\u0006 \u0003כל\u0004 ה\u0003קדשים\u0004 הקרבים \u0003לגבי מזבח לענין מריקה ושטיפה\u0004 האמורה בחטאת (ויקרא ו פסוק כא, שאם נתבשלו בכלי נחושת, נאסר הכלי בשל הבליעה, ויש להגעילו ברותחים), כפי שלמדו ממדרש הכתובים, נמצא שבכל הקדשים מדובר בפרשה זו, ואם כן, \u0003חטאת דכתב רחמנא\u0004 \u0005[ש\u0006חזרה ו\u0005כתבה התורה]\u0006 בענין זה של דם שנכנס לפני ולפנים \u0003למה לי? שמע מינה\u0004 \u0005[למד מכאן]:\u0006 \u0003חטאת\u0004 שנכנס דמה לפנים — \u0003אין\u0004 \u0005[כן]\u0006 נפסלת, ואילו \u0003מידי אחרינא\u0004 \u0005[דבר אחר,\u0006 שאר קרבנות\u0005]\u0006 — \u0003לא. ו\u0004אם יש מקום להמשיל משל כעין זה,","\u0003הא לא דמיא\u0004 \u0005[זו אינה דומה]\u0006 \u0003אלא לתלמיד שמזג לרבו\u0004 מתחילה \u0003בין בחמין בין בצונן,\u0004 ו\u0003אמר לו\u0004 רבו: \u0003אל תמזוג לי אלא חמין!\u0004","\u0003אלא טעמא\u0004 \u0005[הטעם,\u0006 המקור לשיטתו\u0005]\u0006 של \u0003ר' עקיבא\u0004 הוא \u0003מ\u0004מה שלא נאמר בדין זה \u0003\"חטאת\",\u0004 אלא: \u0003\"וכל חטאת\",\u0004 והרי זה בא לרבות אף שאר קרבנות. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 בענין זה: \"וכל \u0003חטאת\u0004 אשר יובא מדמה... באש תישרף\" — \u0003אין לי\u0004 שנוהגת הלכה זו \u0003אלא\u0004 בקרבן \u0003חטאת\u0004 בלבד, בשאר \u0003קדשי קדשים מנין? תלמוד לומר: \"כל חטאת\"\u0004 שהוא לשון ריבוי. ושנוהגת כן אף ב\u0003קדשים קלים מנין\u0004 לנו? \u0003תלמוד לומר: \"וכל חטאת\",\u0004 שו' שב\"וכל\" יש בה ריבוי נוסף, \u0003דברי ר' עקיבא.\u0004","\u0003אמר לו ר' יוסי הגלילי: אפילו אתה\u0004 מוצא במקרא זה עוד לשונות ריבוי ו\u0003מרבה\u0004 מהם \u0003כל היום כולו, איני שומע לך\u0004 לדרוש בפסוק זה \u0003אלא\u0004 לגבי \u0003חטאת\u0004 בלבד. וכך יש לדרוש: \"וכל חטאת אשר יובא מדמה אל אוהל מועד... באש תישרף\" — \u0003אין לי\u0004 שנוהג דין זה \u0003אלא\u0004 ב\u0003חטאת יחיד,\u0004 ב\u0003חטאת צבור מנין? תלמוד לומר \"כל חטאת\". ו\u0004עדיין יש לשאול: \u0003אין לי\u0004 שנוהג דין זה \u0003אלא\u0004 ב\u0003חטאת זכר,\u0004 ואולם שנוהג כן אף ב\u0003חטאת נקבה מנין? תלמוד לומר \"וכל\",\u0004 בו'.","ותוהים: \u0003כלפי לייא\u0004 \u0005[לאן הוא נוטה]?\u0006 והרי ההיפך הוא המסתבר, שהרי סתם חטאת עליה מדובר היא חטאת יחיד, הבאה נקבה! ומתקנים, \u0003אלא הכי קאמר\u0004 \u0005[כך אומר]\u0006 ר' יוסי הגלילי: \u0003אין לי אלא חטאת נקבה, חטאת זכר מנין? תלמוד לומר \"וכל חטאת\".\u0004","ושואלים על כך: \u0003וסבר\u0004 \u0005[ו\u0006כי \u0005סבור]\u0006 \u0003ר' יוסי הגלילי\u0004 כי \u0003האי קרא להכי הוא דאתא\u0004 \u0005[פסוק זה לכך הוא שבא]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יוסי הגלילי אומר: (לפי שמצינו) כל הענין כולו\u0004 \"וכל חטאת אשר יובא מדמה אל אוהל מועד לכפר בקודש לא תאכל, באש תישרף\" \u0003אינו מדבר\u0004 בחטאת חיצונה שנכנס דמה אל אוהל מועד שלא כראוי, \u0003אלא בפרים הנשרפים ושעירים הנשרפים,\u0004 כלומר, החטאות הפנימיות, שדינן להישרף מחוץ לירושלים, ובא כתוב זה ללמד שאם אירע בהם פסול יש","\u0003לשרוף\u0004 את \u0003פסוליהן\u0004 ב\u0003בית הבירה,\u0004 כלומר, בתוך המקדש, \u0003ולעמוד ב\u0004איסור \u0003לא תעשה על אכילתו.\u0004","\u0003אמרו לו\u0004 חכמים: לדבריך, \u0003חטאת\u0004 חיצונה \u0003שנכנס דמה לפני ולפנים\u0004 (לקודש הקדשים) \u0003מנין\u0004 לנו שהיא טעונה שריפה? \u0003אמר להם:\u0004 דבר זה נלמד מדברי משה לבני אהרן, לאחר שנשרף שעיר החטאת ביום מות נדב ואביהוא: \"מדוע לא אכלתם את החטאת... \u0003הן לא הובא\u0004 את דמה אל הקדש פנימה\" (ויקרא י, יח), ללמדנו שאם היה נכנס דמה פנימה, ראויה היתה להישרף. וכיצד, בויכוחו עם ר' עקיבא, דורש ר' יוסי הגלילי את הפסוק שלא כשיטתו, אלא לענין חטאת חיצונה!","ומשיבים: ר' יוסי הגלילי \u0003לדבריו\u0004 של \u0003ר' עקיבא קאמר\u0004 \u0005[אמר],\u0006 שגם לשיטתו אין לדרוש את הפסוק אלא לגבי חטאת ולא לגבי שאר קדשים. ואילו הוא עצמו אינו סבור שעל כך מדובר בפסוק זה.","\u0003חטאת\u0004 חיצונה \u0003שקבל\u0004 הכהן את \u0003דמה בשני כוסות,\u0004 אם \u0003יצא אחד מהן לחוץ\u0004 העזרה, ונפסל בכך, \u0003הפנימי\u0004 שנשאר בעזרה לא נפסל ו\u0003כשר\u0004 לזריקה. \u0003נכנס אחד מהם לפנים\u0004 (להיכל), ונפסל בכך (כמבואר במשנה הקודמת) — \u0003ר' יוסי הגלילי מכשיר\u0004 לזריקה את הדם ש\u0003ב\u0004כוס ה\u0003חיצון\u0004 (שבעזרה), \u0003וחכמים פוסלין\u0004 אותו.","\u0003אמר ר' יוסי הגלילי\u0004 להוכיח את שיטתו: \u0003מה אם במקום שהמחשבה\u0004 לזרוק בו את הדם \u0003פוסלת\u0004 את הקרבן, דהיינו \u0003בחוץ\u0004 לעזרה, אם יצא לשם מקצת הדם ונפסל \u0003לא עשה\u0004 על ידי כך \u0003את\u0004 הדם \u0003המשויר\u0004 (הנשאר) שבפנים \u0003כ\u0004דם ה\u0003יוצא,\u0004 והריהו כשר, וכפי שמוסכם על דעת הכל. אם הגיע מקצת הדם אל \u0003מקום שאין המחשבה\u0004 לזרוק שם את הדם \u0003פוסלת\u0004 בו, כלומר \u0003בפנים\u0004 (בהיכל) — \u0003אינו דין\u0004 (לא קל וחומר הוא) \u0003שלא נעשה\u0004 בו \u0003את\u0004 דינו של הדם \u0003המשויר\u0004 בעזרה \u0003כ\u0004דינו של ה\u0003נכנס\u0004 לפנים?","ועוד בענין דם חטאת חיצונה שנכנס להיכל לכפר: אם \u0003נכנס\u0004 הדם פנימה \u0003לכפר\u0004 (להזות), \u0003אף על פי שלא כפר\u0004 בפועל — \u0003פסול\u0004 הדם, אלו \u0003דברי ר' אליעזר. ר' שמעון אומר:\u0004 אין הדם נפסל לזריקה \u0003עד שיכפר,\u0004 שיזה ממנו בפנים. \u0003ר' יהודה אומר: אם הכניס\u0004 את הדם להיכל ב\u0003שוגג\u0004 — \u0003כשר\u0004 הדם לזריקה.","ובענין דמים שנפסלו, מוסיפים: \u0003כל הדמים\u0004 ה\u0003פסולין\u0004 לזריקה \u0003שנתנו על גבי המזבח\u0004 — אין הקרבן כשר. ואף שנאמר על הציץ שבראש הכהן הגדול: \"והיה על מצח אהרן ונשא אהרן את עון הקדשים\" (שמות כח, לח), מכל מקום \u0003לא הרצה\u0004 (הכשיר) \u0003הציץ אלא על ה\u0004קרב כשהוא \u0003טמא, שהציץ מרצה על הטמא ואינו מרצה על היוצא\u0004 מן העזרה, ולא על פסולים אחרים.","בענין מחלוקתם של ר' יוסי הגלילי וחכמים, כשנתן מדמה של חטאת בהיכל, האם הדם שבכוס השני נפסל, \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' יוסי הגלילי: קל וחומר\u0004 הוא שהוא כשר, \u0003ומה במקום שמחשבה\u0004 לזרוק בו את הדם \u0003פוסלת,\u0004 כלומר \u0003בחוץ\u0004 לעזרה — \u0003לא פסל דם ש\u0004יצא \u0003בחוץ את\u0004 הדם \u0003ש\u0004נותר \u0003בפנים. מקום שאין מחשבה\u0004 לזרוק בו את הדם \u0003פוסלת\u0004 כלומר, \u0003בפנים\u0004 (בהיכל) — \u0003אינו דין שלא יפסול\u0004 ה\u0003דם ש\u0004נכנס \u0003בפנים את\u0004 הדם \u0003ש\u0004נותר \u0003בחוץ?\u0004","\u0003אמרו לו\u0004 חכמים בתשובה, \u0003הרי הוא אומר:\u0004 \"וכל חטאת \u0003אשר יובא מדמה\u0004 אל אהל מועד לכפר בקודש לא תאכל, באש תישרף\" (ויקרא ו, כג), והלשון \"מדמה\" משמעה: \u0003אפילו\u0004 הובא \u0003מקצת\u0004 מ\u0003דמה\u0004 הריהי נפסלת כולה בכך.","\u0003אמר להם\u0004 ר' יוסי הגלילי לחכמים: אם כך אתם מדייקים מלשון הכתוב, יש לדון ב\u0003קל וחומר ל\u0004דם ה\u0003יוצא\u0004 אל מחוץ לעזרה \u0003מעתה,\u0004 שאף הוא יפסול את הדם שנותר בעזרה, ובאופן זה: \u0003ומה במקום שאין מחשבה פוסלת\u0004 בו, כלומר \u0003בפנים\u0004 — \u0003פוסל\u0004 ה\u0003דם שבפנים את\u0004 הדם \u0003שבחוץ\u0004 (שבעזרה). \u0003מקום שמחשבה פוסלת\u0004 בו, כלומר \u0003בחוץ\u0004 לעזרה — \u0003אינו דין שיפסול\u0004 ה\u0003דם שבחוץ את\u0004 הדם \u0003שבפנים\u0004 העזרה? ומדוע מכשירים אתם במקרה זה?","\u0003אמרו לו\u0004 חכמים בתשובה לכך: \u0003הרי הוא אומר\u0004 במקרא זה: \u0003\"אשר יובא\u0004 מדמה אל אהל מועד\", ולשון ביאה באה ללמד שדווקא הדם \u0003הנכנס\u0004 הוא ה\u0003פוסל\u0004 במקצתו את הדם שבעזרה, \u0003ואין ה\u0004דם ה\u0003יוצא\u0004 מהעזרה \u0003פוסל\u0004 את הדם שבעזרה.","בעקבות דיון זה שואלים: \u0003ו\u0004מדוע לא נלמד ש\u0003תהא מחשבה\u0004 לזרוק \u0003בפנים פוסלת מ\u0004כוח \u0003קל וחומר,\u0004 ובאופן זה: \u0003ומה במקום שלא פסל\u0004 מקצת ה\u0003דם ש\u0004יצא \u0003בחוץ את\u0004 שאר הדם \u0003שבפנים\u0004 (שבעזרה) — \u0003מחשבה\u0004 בו \u0003פוסלת\u0004 את הקרבן, כלומר, \u0003בחוץ. מקום שפסל\u0004 בו מקצת ה\u0003דם שבפנים את\u0004 שאר ה\u0003דם שבחוץ\u0004 (שבעזרה) — \u0003אינו דין שתהא מחשבה\u0004 של הכהן בו \u0003פוסלת,\u0004 כלומר, \u0003בפנים?\u0004","ומשיבים: אין למדים כן מקל וחומר, ש\u0003הרי הוא אומר\u0004 בדין פיגול: \"ואם האכל יאכל \u0003ביום השלישי\u0004 פיגול הוא לא ירצה\" (ויקרא יט, ז), ודרשוהו חכמים לענין מחשבת חוץ למקומו, ללמד"],["ש\u0003מקום\u0004 זה שמחשבה בו פוסלת צריך \u0003שיהא משולש, ב\u0004זריקת ה\u0003דם ב\u0004אכילת ה\u0003בשר\u0004 ו\u0003ב\u0004הקטרת ה\u0003אימורים,\u0004 שלגבי שלושתם הוא מוגדר כחוץ למקומו, ולכן אין מחשבה על ההיכל פוסלת.","\u0003ו\u0004עדיין יש לשאול לכיוון ההפוך: ונלמד ש\u0003לא תהא מחשבה פוסלת בחוץ מקל וחומר\u0004 ממחשבה בפנים שאינה פוסלת: \u0003ומה מקום שפסל דם ש\u0004נכנס \u0003בפנים\u0004 (בהיכל) \u0003את\u0004 שאר הדם \u0003ש\u0004נשאר \u0003בחוץ\u0004 (בעזרה) — \u0003אין מחשבה פוסלת\u0004 אם חישב לזרוק את הדם \u0003בפנים\u0004 (בהיכל), \u0003מקום שלא פסל\u0004 ה\u0003דם ש\u0004יצא \u0003בחוץ את\u0004 הדם \u0003ש\u0004נשאר \u0003בפנים\u0004 כלומר, בעזרה — \u0003אינו דין שלא יהא פוסל מחשבה\u0004 אם חשב לזרוק \u0003בחוץ?\u0004","\u0003תלמוד לומר:\u0004 \"ואם האכל יאכל מבשר זבח שלמיו ביום השלישי לא ירצה... פגול יהיה\" (ויקרא ז, יח), ודרשו חכמים שכוונת הכתוב \u0003\"ביום השלישי\"\u0004 — הרי זו מחשבת \u0003חוץ לזמנו, \"פגול\u0004 יהיה\" — מחשבת \u0003חוץ למקומו.\u0004","ועוד בהלכות אלו: \u0003בשר\u0004 הקרבנות \u0003היוצא ל\u0004מקום שהוא \u0003חוץ\u0004 ממקום אכילתו (קדשים קלים — מחוץ לחומת ירושלים, קדשי קדשים — מחוץ לחומת העזרה) — \u0003פסול\u0004 מלהיאכל. אבל בשר \u0003הנכנס לפנים\u0004 (להיכל) — לא נפסל בכך, והריהו \u0003כשר\u0004 לאכילה.","וחידוש יש בדין זה, \u0003ש\u0004כן \u0003יהא\u0004 מקום ללמוד \u0003בדין\u0004 (בקל וחומר) \u0003ש\u0004יהא \u0003פסול:\u0004 \u0003ומה במקום שלא פסל\u0004 ה\u0003דם ש\u0004יצא \u0003בחוץ\u0004 לעזרה \u0003את\u0004 הדם \u0003ש\u0004נשאר \u0003בפנים\u0004 — \u0003בשר היוצא לחוץ\u0004 הריהו \u0003פסול. מקום שיפסול דם ש\u0004נכנס \u0003בפנים\u0004 (בהיכל) \u0003את\u0004 הדם \u0003שבחוץ\u0004 — \u0003בשר הנכנס בפנים אינו דין שפסל?\u0004","\u0003הרי הוא אומר:\u0004 \"וכל חטאת אשר יובא \u0003מדמה\u0004 אל אהל מועד... לא תאכל, באש תישרף\" (ויקרא ו, כג) — \u0003דמה\u0004 שהוכנס להיכל פסול, \u0003ולא בשר\u0004 שהוכנס להיכל.","ויש מקום לדון במידת \u0003קל וחומר, מעתה\u0004 שלמדנו שאין בשר הקרבנות הנכנס פנימה פסול, ולומר כך: \u0003ומה במקום שפסל דם שבפנים\u0004 (ההיכל) \u0003את\u0004 הדם \u0003שבחוץ\u0004 (שבעזרה) — \u0003בשר הנכנס לפנים\u0004 (להיכל) \u0003כשר, מקום שלא פסל\u0004 בו ה\u0003דם ש\u0004יצא \u0003בחוץ את שבפנים\u0004 (בעזרה) — \u0003בשר היוצא לחוץ\u0004 לעזרה \u0003אינו דין ש\u0004יהיה \u0003כשר?\u0004","לכך \u0003הרי הוא אומר: \"ובשר בשדה טרפה לא תאכלו\"\u0004 (שמות כב, ל), והמלה \"בשדה\" באה ללמדנו הלכה כללית: \u0003כיון שיצא בשר חוץ למחיצתו\u0004 (למקומו המוגדר) — \u0003נאסר.\u0004","ושבים לדון בדין דם חטאת שנכנס להיכל. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר בדברי משה לבניו של אהרן: \"מדוע לא אכלתם את החטאת... הן לא הובא את דמה אל הקודש \u0003פנימה\"\u0004 (ויקרא י, יח), ומכאן יש לדייק שאילו היה מובא מדמה אל הקודש פנימה, אכן היתה נפסלת ואסורה באכילה. ויש לדון בדבר: \u0003אין לי אלא\u0004 אם הוכנס דמה \u0003פנימה\u0004 (לקודש הקדשים), ואולם אם הוכנס ל\u0003היכל מנין\u0004 לנו שכך הוא גם כן דינו? \u0003תלמוד לומר \"אל הקדש פנימה\",\u0004 ו\"הקודש\" הוא ההיכל.","ושואלים על ברייתא זו: \u0003ויאמר\u0004 הכתוב \u0003\"קדש\"\u0004 בלבד, \u0003ואל יאמר\u0004 גם \u0003\"פנימה\",\u0004 שהרי אם הכנסה לקודש פוסלת — ממילא גם הכנסה לקודש הקודשים! \u0003אמר רבא: בא\u0004 כתוב \u0003זה ולימד על\u0004 כתוב \u0003זה,\u0004 שאילו לא היה כתוב אלא \"קודש\" בלבד הייתי אומר שהכוונה לקודש הקדשים, וייתור הלשון \"פנימה\" מלמד ש\"קודש\" הינו ההיכל, ו\"פנימה\" הינו קודש הקדשים. ומביאים דוגמה לאופן זה של לימוד: \u0003מידי דהוה\u0004 \u0005[כמו שהוא]\u0006 לענין איסור אכילת תרומה על ידי עבדיו העבריים של הכהן, שלמדו מן הכתוב \u0003\"תושב\u0004 כהן \u0003ושכיר\u0004 לא יאכל קדש\" (ויקרא כב, י).","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003\"תושב\"\u0004 — \u0003זה\u0004 עבד עברי ה\u0003קנוי\u0004 לכהן \u0003קנין עולם\u0004 (עבד נרצע, הקנוי עד היובל), \u0003\"שכיר\"\u0004 — \u0003זה\u0004 עבד עברי ה\u0003קנוי קנין שנים,\u0004 שיוצא בשנה השביעית.","ושואלים: \u0003יאמר\u0004 הכתוב \u0003\"תושב\"\u0004 בלבד, ללמדנו שהקנוי קנין עולם אינו אוכל בתרומה, \u0003ואל יאמר\u0004 גם \u0003\"שכיר\", ואני אומר\u0004 מעצמי: אם מי ש\u0003קנוי קנין עולם\u0004 לכהן \u0003אינו אוכל\u0004 בתרומה כמו עבדיו הכנענים, משום שהוא אינו נחשב כרכוש הכהן — זה שהוא רק \u0003קנוי קנין שנים לא כל שכן\u0004 שאינו אוכל?","ומשיבים: \u0003אילו כן\u0004 היה כתוב, \"תושב\" בלבד, \u0003הייתי אומר: \"תושב\"\u0004 — \u0003זה\u0004 עבד ה\u0003קנוי קנין שנים, אבל\u0004 ה\u0003קנוי קנין עולם\u0004 — \u0003יהא אוכל\u0004 בתרומה. לכן \u0003בא \"שכיר\" ולימד על \"תושב\", ש\u0004\"תושב\" \u0003זה\u0004 עבד עברי ה\u0003קנוי קנין עולם, ו\u0004\"שכיר\" \u0003זה\u0004 עבד ה\u0003קנוי קנין שנים, ו\u0004זה וזה \u0003אינו אוכל\u0004 בתרומה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרבא: וכי דומים הדברים? \u0003בשלמא התם\u0004 \u0005[נניח שם,\u0006 באכילת תרומה\u0005]\u0006 יש מקום לפתרון זה, שכל אחד צריך כתוב לעצמו, שכן \u0003תרי גופי נינהו\u0004 \u0005[שני גופים\u0006 נפרדים \u0005הם],\u0006 קנוי קנין עולם וקנוי קנין שנים. \u0003ואף על גב דהוה ליה לקרא למכתב\u0004 \u0005[ואף על פי שהיה לו למקרא לכתוב]\u0006 \u0003\"נרצע לא יאכל\", ו\u0004דינו של \u0003אידך\u0004 \u0005[האחר,\u0006 קנוי קנין שנים\u0005]\u0006 \u0003אתי\u0004 \u0005[היה בא,\u0006 נלמד\u0005]\u0006 \u0003בקל וחומר\u0004 שאינו אוכל — מכל מקום אין בדבר קושי, \u0003כי\u0004 \u0003מילתא דאתי\u0004 \u0005[דבר שבא,\u0006 נלמד\u0005]\u0006 \u0003בקל וחומר\u0004 בכל זאת \u0003טרח וכתב לה קרא\u0004 \u0005[טורח וכותב אותו המקרא].\u0006 \u0003אלא הכא\u0004 \u0005[כאן,\u0006 בדם שנכנס לקודש הקדשים\u0005],\u0006 הלוא מן ההיכל נכנסים לקודש הקדשים, ו\u0003כיון דאיפסל\u0004 \u0005[שנפסל]\u0006 \u0003בהיכל, לפני ולפנים\u0004 (בקודש הקדשים) \u0003מאי בעי\u0004 \u0005[מה צריך]\u0006 לחזור ולפוסלו? \u0003אלא\u0004","\u0003אמר אביי: לא נצרכא\u0004 \u0005[נצרכה]\u0006 \"פנימה\" \u0003אלא ל\u0004מקרה שהוכנס הדם לקודש הקדשים לא דרך ההיכל (שאז היה נפסל מתחילה), אלא ב\u0003דרך משופש\u0004 (בעקיפין) דרך הגג או העליה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא\u0004 לאביי: \u0003והא\u0004 \u0005[והרי]\u0006 לשון \u0003הבאה כתיב ביה\u0004 \u0005[נאמר בו]\u0006 (\"הן לא הובא את דמה אל הקודש פנימה\"), ואילו הבאה בדרך משופש אינה נחשבת הבאה! \u0003אלא אמר רבא:\u0004 יש צורך בכתוב מיוחד הפוסל את הדם בקודש הקדשים, משום ש\u0003כל מידי דחשיב עליה\u0004 \u0005[כל דבר שחשב עליו]\u0006 הכהן להכניסו \u0003לפני ולפנים\u0004 — עדיין \u0003לא מיפסל\u0004 \u0005[אינו נפסל]\u0006 \u0003בהיכל.\u0004","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא: פר העלם דבר של\u0004 \u0003צבור ושעיר עבודה זרה, ש\u0004צריך להזות את דמם בהיכל, ו\u0003הכניס דמן\u0004 אל \u0003לפני ולפנים\u0004 (לקודש הקדשים) \u0003מהו?\u0004 האם נפסל הדם?","וצדדי השאלה: \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]\u0006 כי כיון שנאמר בפסול זה: \u0003\"אל הקדש פנימה\"\u0004 (ויקרא י, יח) ברצף אחד, יש ללמוד כי \u0003כל היכא דקרינן\u0004 \u0005[כל מקום שקוראים אנו]\u0006 בו \u0003\"אל הקדש\",\u0004 שהדם נפסל בכניסתו להיכל, \u0003קרינן ליה\u0004 \u0005[קוראים אנו בו]\u0006 \u0003\"פנימה\"\u0004 הריהו נפסל גם בכניסתו לקודש הקדשים, אבל \u0003כל היכא דלא קרינן\u0004 \u0005[כל מקום שאין קוראים אנו]\u0006 \u0003\"אל הקדש\",\u0004 וכגון קרבנות אלו, שאין דמם נפסל בהיכל — \u0003לא קרינן\u0004 \u0005[אין אנו קוראים]\u0006 בו פסול של \u0003\"פנימה\"\u0004 בקודש הקדשים. \u0003או דלמא\u0004 \u0005[שמא]\u0006 על כל פנים, קודש הקדשים \u0003שלא במקומן הוא,\u0004 ונפסל בכך?","\u0003ואם תימצי\u0004 \u0005[תמצא]\u0006 \u0003לומר\u0004 כי הואיל ו\u0003שלא במקומן הוא\u0004 נפסל הדם, יש לשאול עוד: \u0003פר ושעיר של יום הכיפורים ש\u0004הכהן הגדול \u0003הזה מדמן על הבדים\u0004 של הארון שבקודש הקדשים, כדינם (\"על הכפורת ולפני הכפורת\", ויקרא טז, טו), \u0003ו\u0004כשגמר עבודתם \u0003הוציאן\u0004 אחר כך \u0003להיכל, ו\u0004חזר ו\u0003הכניסן, מהו\u0004 דינם?","וצדדי השאלה, \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]:\u0006 \u0003מקומן הוא\u0004 בקודש הקדשים, ואינם נפסלים, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003הואיל ו\u0004כבר \u0003נפק\u0004 \u0005[יצא]\u0006 הדם מקודש הקדשים לאחר שנעשתה מצוותו — \u0003נפק\u0004 \u0005[יצא],\u0006 ושוב אין זה מקומו, ואם הכניסו שוב — נפסל?","\u0003ואם תימצי\u0004 \u0005[תמצא]\u0006 \u0003לומר\u0004 במקרה זה: \u0003הואיל ונפק נפק\u0004 \u0005[ויצא יצא]\u0006, יש לשאול: לאחר שיצא מקודש הקדשים, ו\u0003הזה מדמן על הפרכת,\u0004"],["\u0003והוציאו\u0004 את הדם \u0003ל\u0004עבר \u0003מזבח\u0004 הזהב שבהיכל, והיזה עליו, כסדר האמור בעבודת יום הכיפורים (ויקרא טז, יח), ואחר כך חזר \u0003והכניסן\u0004 שוב לעבר הפרוכת, \u0003מהו\u0004 דינו של דם זה?","וצדדי השאלה: האם נאמר כי \u0003הכא\u0004 \u0005[כאן]\u0006 מקום הפרוכת ומזבח הזהב \u0003ודאי חד מקום\u0004 \u0005[מקום אחד]\u0006 \u0003הוא,\u0004 ההיכל, ולכן לא ייפסל הדם בהחזרתו למקום הפרוכת. \u0003או דילמא\u0004 \u0005[שמא]\u0006 כיון שלהולכת הדם למזבח הזהב \u0003יציאה קרינא ביה\u0004 \u0005[קוראים אנו בו]\u0006 בכתוב (\"ויצא אל המזבח\", ויקרא טז, יח), הרי החזרתו למקום הפרוכת כהכנסה היא נחשבת, ונפסל בכך? שאלות אלה לא נפתרו ונשארו ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","שנינו במשנה שנחלקו חכמים במקרה ש\u0003נכנס\u0004 דם החטאת החיצונה אל ההיכל על מנת \u0003לכפר\u0004 (להזותו) שם ובפועל לא כיפר בו, שלדעת ר' אליעזר הריהו נפסל, ולדעת ר' שמעון אינו נפסל עד שיזה ממנו. ובענין זה, \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אליעזר אומר: נאמר כאן:\u0004 \"וכל חטאת אשר יובא מדמה אל אהל מועד \u0003לכפר בקדש\u0004 לא תאכל, באש תישרף\" (ויקרא ו, כג), \u0003ונאמר להלן\u0004 בסדר עבודת הכהן הגדול ביום הכיפורים: \u0003\"וכל אדם לא יהיה באהל מועד בבאו לכפר בקדש\"\u0004 (ויקרא טז, יז).","\u0003מה להלן,\u0004 ביום הכיפורים, משמעו של \"בבואו לכפר\" הוא \u0003ב\u0004שלב \u0003ש\u0004עדיין \u0003לא כיפר, אף כאן,\u0004 בפסולו של דם שנכנס לפנים, הלשון \"לכפר בקדש\" משמעה שנפסל הדם כבר בכניסתו להיכל, \u0003ב\u0004זמן \u0003ש\u0004עדיין \u0003לא כיפר.\u0004 ואילו \u0003ר' שמעון אומר: נאמר כאן \"לכפר\", ונאמר להלן\u0004 בסוף סדר העבודה ביום הכיפורים: \u0003\"ואת פר החטאת ואת שעיר החטאת אשר הובא את דמם לכפר\u0004 בקודש יוציא אל מחוץ למחנה ושרפו באש\" (ויקרא טז, כז), \u0003מה להלן\u0004 כוונת הלשון \"לכפר\" — \u0003בש\u0004כבר \u0003כיפר,\u0004 שהרי פר ושעיר של יום הכיפורים נשרפים לאחר שהוזה דמם, \u0003אף כאן\u0004 כוונת הלשון \"לכפר\" — \u0003בש\u0004כבר \u0003כיפר,\u0004 ואין עצם הכנסת הדם להיכל פוסלתו.","","ומסבירים: \u0003במאי קמיפלגי\u0004 \u0005[במה הם חלוקים]\u0006 מה הבסיס למחלוקתם של ר' אליעזר ור' שמעון? \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' אליעזר, \u0005סבור]:\u0006 \u0003דנין חוץ מחוץ\u0004 דם חטאת חיצונה שאסור להכניסו להיכל, מן האיסור לכל אדם להיכנס להיכל, \u0003ואין דנין חוץ\u0004 (חטאת חיצונה) \u0003מבפנים\u0004 (מפר ושעיר יום הכיפורים שדמם נכנס לקודש הקדשים).","","","","","","","","","","\u0003ו\u0004אילו \u0003מר סבר\u0004 \u0005[וחכם זה,\u0006 ר' שמעון, \u0005סבור]:\u0006 \u0003דנין בהמה מבהמה\u0004 (חטאת חיצונה מפר ושעיר של יום הכיפורים), \u0003ואין דנין\u0004 דין \u0003בהמה\u0004 (חטאת החיצונה) \u0003מאדם\u0004 (שנאסר להיכנס). עוד שנינו במשנה, \u0003ר' יהודה אומר:\u0004 אם הכניס להיכל מדם חטאת חיצונה בשוגג — כשר. ומדייקים, \u0003הא\u0004 \u0005[אבל]\u0006 אם הכניס ב\u0003מזיד\u0004 — \u0003פסול.\u0004 ויש לדון בדבר: האם הוא פסול רק \u0003ב\u0004מקרה \u0003ש\u0004הכניס הדם ו\u0003כיפר\u0004 (זרק הדם בפנים), וכדעת ר' שמעון במשנתנו, \u0003או\u0004 גם \u0003ב\u0004מקרה \u0003ש\u0004הכניס את הדם ועדיין \u0003לא כיפר,\u0004 וכדעת ר' אליעזר? \u0003אמר ר' ירמיה:\u0004 יש להביא ראיה ממה ששנינו בברייתא: \u0003ממשמע שנאמר\u0004 בסדר העבודה ביום הכיפורים: \u0003\"ואת פר החטאת ואת שעיר החטאת אשר הובא את דמם לכפר בקודש\u0004 יוציא אל מחוץ למחנה ושרפו באש... והשורף אותם יכבס בגדיו....\" (ויקרא טז, כז). \u0003מה תלמוד לומר\u0004 מה בא ללמד הכתוב הנוסף \u0003\"והשרף\"?\u0004 מיד תוהים על עצם השאלה: \u0003מה תלמוד לומר \"והשרף\"?!\u0004 והרי \u0003לגופיה איצטריך\u0004 \u0005[לגופו הוצרך],\u0006 ללמדנו שהשורף את פר ושעיר יום הכיפורים נטמא בכך! \u0003אלא\u0004 כך שואלת הברייתא: \u0003מה תלמוד לומר\u0004 פעמיים, \"פר ה\u0003חטאת\"\u0004 \"שעיר ה\u0003חטאת\"?\u0004 והרי יכול היה לאמר \"ואת פר ושעיר החטאת\"! \u0003לפי ש\u0004אילו היה כתוב בו רק פעם אחת \"חטאת\" \u0003לא למדנו אלא ל\u0004דינם של \u0003פר ושעיר של יום הכפורים שנשרפין\u0004 על \u0003בית הדשן\u0004 שהם \u0003מטמאין בגדים\u0004 של הנושא אותם, ואולם \u0003שאר\u0004 הקרבנות ה\u0003נשרפין מנין\u0004 לנו — \u0003תלמוד לומר \"חטאת\" \"חטאת\",\u0004 לרבות כל החטאות הנשרפות, אלו \u0003דברי ר' יהודה.\u0004 \u0003ר' מאיר אומר: אינו צריך\u0004 ללימוד מ\"חטאת\" \"חטאת\". אלא כך למדים: \u0003הרי הוא אומר\u0004 בפסוק זה: \u0003\"ואת פר החטאת ואת שעיר החטאת...\u0004 יוציא אל מחוץ למחנה\" וכו', \u0003שאין תלמוד\u0004 (צורך) \u0003לומר\u0004 להזכיר לגביהם \"אשר הובא את דמם \u0003לכפר\u0004 בקודש\", ואם כן \u0003מה תלמוד לומר \"לכפר\"? לימד על כל\u0004 הקרבנות \u0003המתכפרים\u0004 בפנים \u0003שהשורפן מטמא בגדים.\u0004 ויש לשאול: \u0003ור' יהודה,\u0004 ש\u0003\"לכפר\" לא משמע ליה\u0004 \u0005[לו]\u0006 כמקור להלכה זו, \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דמיבעיא ליה\u0004 \u0005[שצריך אותה\u0006 את המלה הזו\u0005]\u0006 \u0003לגזירה שוה,\u0004 כדי ללמד שדם חטאת חיצונה שנכנס להיכל אינו נפסל אלא אם כיפר, וכשיטת ר' שמעון? ומכאן איפוא תשובה לשאלת הגמרא. \u0003המזבח מקדש\u0004 אף דבר פסול שעלה עליו, ואינו מקדש הכל אלא \u0003את\u0004 הדבר \u0003הראוי לו.\u0004 הלכה זו היתה הלכה מוסכמת, אלא שנחלקו חכמים ביחס להגדרה המדוייקת מה הוא \"הראוי לו\". \u0003ר' יהושע אומר: כל הראוי לאישים,\u0004 כל דבר שדרכו להישרף באש המזבח (עולות ואימורים וכיוצא בהם) — \u0003אם עלה\u0004 על המזבח, הרי גם אם היה פסול \u0003לא ירד,\u0004 כיון שהתקדש בעלייתו למזבח, והרי הוא קרב עליו, \u0003שנאמר\u0004 בפרשת קרבן עולה: \u0003\"היא העלה על מוקדה\"\u0004 (ויקרא ו, ב), ללמד: \u0003מה עולה שהיא ראויה לאישים\u0004 (\"על מוקדה\") \u0003אם עלתה לא תרד אף כל\u0004 דבר רגיל \u0003שהוא ראוי לאישים\u0004 למזבח \u0003אם עלה לא ירד.\u0004","\u0003רבן גמליאל אומר: כל הראוי\u0004 לעלות למזבח (גם אם אינו נשרף באש המזבח) — \u0003אם עלה לא ירד,\u0004 אף שהוא פסול, \u0003שנאמר: \"היא העלה על מוקדה על המזבח\",\u0004 (ויקרא ו, ב), ללמד: \u0003מה עולה שהיא ראויה למזבח, אם עלתה לא תרד\u0004 — \u0003אף כל דבר שהוא ראוי למזבח אם עלתה לא תרד.\u0004","ומעירים: \u0003אין\u0004 הבדל למעשה \u0003בין דברי רבן גמליאל לדברי ר' יהושע אלא הדם והנסכים\u0004 הפסולים, שאינם עולים לאישים אבל ניתנים על המזבח, \u0003שרבן גמליאל אומר: לא ירדו,\u0004 שהרי ראויים למזבח, \u0003ור' יהושע אומר: ירדו.\u0004 \u0003ר' שמעון אומר:\u0004 נסכים הבאים יחד עם הקרבן, ונפסלו, בין אם היה \u0003הזבח כשר ונסכים\u0004 הבאים עמו \u0003פסולין\u0004 (כגון שנטמאו או שיצאו חוץ למקומם), ובין אם היו \u0003הנסכים\u0004 כשלעצמם \u0003כשירים ו\u0004אולם \u0003הזבח פסול\u0004 (ולכן גם הנסכים נפסלו, שהרי הם באים מחמת הזבח), \u0003אפילו זה וזה פסולין\u0004 — בכל אלה, \u0003הזבח לא ירד,\u0004 שכן המזבח קידשו, \u0003והנסכים ירדו.\u0004",""],["שנינו במשנה: המזבח מקדש את הראוי לו. ומדייקים, כלל זה בא למעט: דוקא את ה\u0003ראוי לו\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 מקדש המזבח, ואילו את \u0003שאין ראוי לו\u0004 — \u0003לא\u0004 מקדש המזבח, ואף שעלה — ירד. ומעתה יש לברר: \u0003למעוטי מאי\u0004 \u0005[למעט\u0006 את \u0005מה]?\u0006 \u0003אמר רב פפא: למעוטי\u0004 \u0005[למעט]\u0006 \u0003קמצין\u0004 שקומצים הכהנים מן המנחות כדי להקטירם על המזבח, \u0003שלא קידשו\u0004 אותם \u0003בכלי\u0004 שרת קודם ההקטרה, ואינם ראויים עדיין למזבח.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבינא: מאי שנא\u0004 \u0005[במה שונה]\u0006 דבר זה \u0003מ\u0004דברי \u0003עולא?\u0004 ש\u0003אמר עולא: אימורי קדשים קלין\u0004 (החלקים המוקטרים על גבי המזבח) \u0003שהעלן\u0004 על המזבח \u0003לפני זריקת דמן,\u0004 ועדיין אינם ראויים למזבח, בכל זאת \u0003לא ירדו,\u0004 משום ש\u0003נעשו לחמו של מזבח!\u0004","ומשיבים: יש לחלק, \u0003הנך\u0004 \u0005[אלה]\u0006 אימורים קודם שנזרק דם הקרבן, \u0003לא מיחסרו\u0004 \u0005[חסרים]\u0006 \u0003מעשה בגופייהו\u0004 \u0005[בגופם]\u0006 כדי לעשותם ראויים למזבח, ואינם צריכים אלא לזריקת הדם. ואילו \u0003הני\u0004 \u0005[אלה]\u0006 הקמצים \u0003מיחסרו\u0004 \u0005[חסרים]\u0006 \u0003מעשה בגופייהו\u0004 \u0005[בגופם\u0006 עצמם\u0005]\u0006 קידוש בכלי, ולכן אינם בכלל הראוי למזבח.","שנינו במשנה כי \u0003ר' יהושע אומר: כל הראוי לאישים,\u0004 למרות שנפסל להקרבה, אם עלה לא ירד, שנאמר: \"היא העולה על מוקדה\" (ויקרא ו, ב) לומר שדבר הראוי להישרף על המוקד הוא שלא ירד. ושואלים: \u0003ורבן גמליאל נמי\u0004 \u0005[גם כן],\u0006 שלדעתו כל הראוי למזבח לא ירד, \u0003הכתיב\u0004 \u0005[הרי נאמר]:\u0006 \u0003\"עלה על מוקדה\"!\u0004 ומשיבים: \u0003ההוא\u0004 \u0005[אותו\u0006 פסוק\u0005]\u0006 \u0003לאהדורי\u0004 \u0005[להחזיר]\u0006 \u0003פוקעין\u0004 חלקי קרבן שמחמת האש ניתקו ועפו מן המזבח \u0003הוא דאתא\u0004 \u0005[שבא],\u0006 שצריך להחזיר אותם למוקד.","ושואלים: \u0003ואידך\u0004 \u0005[ו\u0006התנא \u0005האחר,\u0006 ר' יהושע\u0005]\u0006 הלכה זו שיש \u0003לאהדורי\u0004 \u0005[להחזיר]\u0006 \u0003פוקעין מנא ליה\u0004 \u0005[מנין לו]?\u0006 ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצאת,\u0006 נלמדת \u0005לו]\u0006 הלכה זו \u0003מ\u0004מה שנאמר \u0003\"אשר תאכל האש\u0004 את העולה על המזבח\" (ויקרא ו, ג) שכוונתו: מה שכבר אכלה ממנו האש, אף שפקע — מחזירים אותו על המזבח.","ומבררים: \u0003ואידך\u0004 \u0005[והאחר,\u0006 רבן גמליאל\u0005]\u0006 מה לומד הוא מכתוב זה? \u0003ההוא מיבעי ליה\u0004 \u0005[אותו\u0006 כתוב \u0005נצרך לו]\u0006 \u0003ל\u0004למד: דווקא \u0003עכולי עולה\u0004 (חלקי קרבן שאחזה בהם האש ופקעו) \u0003אתה מחזיר\u0004 למזבח, \u0003ואי\u0004 (אין) \u0003אתה מחזיר עכולי קטורת\u0004 שנפלו ממזבח הזהב שבהיכל. \u0003דתני\u0004 \u0005[\u0006וכפי \u0005ששנה]\u0006 \u0003ר' חנינא בר מניומי בר' אליעזר בן יעקב: \"אשר תאכל האש את העלה על המזבח\"\u0004 — מכאן למדים ש\u0003עכולי עולה\u0004 שנפלו \u0003אתה מחזיר\u0004 למזבח, \u0003ואי אתה מחזיר עכולי קטורת.\u0004","ושואלים: \u0003ואידך\u0004 \u0005[והאחר,\u0006 ר' יהושע\u0005],\u0006 הרי לצורך עיכולי קטורת הוצרך כתוב זה, שאין מחזירים אותם. ומנין הוא לומד הלכה זו? ומשיבים: \u0003לאו ממילא שמע מינה\u0004 \u0005[האם לא מאליו אתה למד]\u0006 ש\u0003עכולי עולה מהדרינן\u0004 \u0005[מחזירים]\u0006 למזבח? ומכאן הוא למד את שתי ההלכות.","שנינו במשנה ש\u0003רבן גמליאל אומר: כל הראוי\u0004 למזבח, אם עלה לא ירד, שהרי נאמר \"העולה על מוקדה על המזבח\" (ויקרא ו, ב). ושואלים: \u0003ור' יהושע נמי, הכתיב\u0004 \u0005[גם כן, הרי נאמר]:\u0006 על ה\u0003מזבח\"\u0004 ולא רק \"על מוקדה\"! ומשיבים: \u0003ההוא מיבעיא ליה\u0004 \u0005[אותו\u0006 פסוק \u0005נצרך לו]\u0006 ללמד כדי להסיק ממנו את עיקרה של ההלכה שהמזבח מקדש כל שעלה עליו, וכך נדרש הפסוק: \u0003מאי (טעמא) קאמר רחמנא\u0004 \u0005[מה טעם אומרת התורה]\u0006 \u0003כל הראוי למוקדה\u0004 לא ירד — משום ש\u0003מקדש\u0004 אותו \u0003מזבח.\u0004","ושואלים: \u0003ואידך\u0004 \u0005[והאחר,\u0006 רבן גמליאל\u0005]\u0006 מנין למד הוא דבר זה? ומשיבים: \u0003\"מזבח\" אחרינא כתיב\u0004 \u0005[אחר כתוב]\u0006 (\"כל הנוגע במזבח יקדש\", שמות כט, לז), וממנו אנו למדים זאת. ושואלים: \u0003ואידך\u0004 \u0005[והאחר,\u0006 ר' יהושע\u0005]\u0006 מה הוא למד משני כתובים שנאמר בהם \"מזבח\"? ומשיבים: \u0003חד להיכא\u0004 \u0005[אחד\u0006 נצרך \u0005להיכן,\u0006 למקרה\u0005]\u0006 ש\u0003היתה לה שעת הכושר\u0004 (זמן שהיתה כשירה) לעלות למזבח ואחר כך נפסלה, כגון בשר שנטמא, \u0003וחד להיכא\u0004 \u0005[ואחר להיכן,\u0006 למקרה\u0005]\u0006 ש\u0003לא היתה לה\u0004 מעולם \u0003שעת הכושר,\u0004 כגון קרבן שנפסל בשחיטתו, ללמד שגם הוא לא ירד.","ושואלים: \u0003ואידך\u0004 \u0005[והאחר,\u0006 רבן גמליאל\u0005]\u0006 מנין לו שגם זה שלא היתה לו שעת הכושר, אם עלה למזבח לא ירד? ומשיבים: \u0003כיון\u0004 ש\u0003פסולין נינהו\u0004 \u0005[הם]\u0006 \u0003ו\u0004בכל זאת \u0003רבינהו רחמנא\u0004 \u0005[ריבתה אותם התורה]\u0006 שלא ירדו, \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 אם \u0003היתה לו שעת הכושר, לא שנא\u0004 \u0005[אינו שונה]\u0006 אם \u0003לא היתה לו שעת הכושר.\u0004","שנינו במשנה: \u0003ר' שמעון אומר\u0004 לגבי נסכים הבאים עם הזבח: בין אם היה \u0003הזבח כשר\u0004 והנסכים פסולים, ובין אם היו הנסכים כשרים כשלעצמם אך הזבח פסול, הזבח לא ירד והנסכים ירדו. ובטעם הדבר \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון אומר:\u0004 בכתוב ממנו למדנו כי קרבן פסול שעלה על המזבח לא ירד נאמר: \"היא ה\u0003עולה\u0004 על המזבח\" (ויקרא ו, ב), ויש ללמוד מכאן: \u0003מה עולה הבאה בגלל עצמה, אף כל הבאין בגלל עצמן. יצאו\u0004 מכלל זה \u0003נסכים הבאין בגלל זבח\u0004 ולא כקרבן לעצמם, שאינם בכלל אלה שלא ירדו.","ועוד שנויה ברייתא בענין משנתנו, \u0003ר' יוסי הגלילי אומר: מתוך שנאמר \"כל הנגע במזבח יקדש\"\u0004 (שמות כט, לז), \u0003שומע אני\u0004 לכאורה שהמזבח מקדש כל שעלה עליו, \u0003בין\u0004 שהוא \u0003ראוי ובין שאינו ראוי\u0004 — \u0003תלמוד לומר\u0004 בפסוק שלאחריו: \"וזה אשר תעשה על המזבח \u0003כבשים\"\u0004 (שמות כט, לח) ללמדנו: \u0003מה כבשים ראויין\u0004 למזבח, \u0003אף כל\u0004 שהוא \u0003ראוי\u0004 למזבח. \u0003ר' עקיבא אומר:\u0004 נאמר בכתוב שבספר ויקרא: \"היא ה\u0003עולה\u0004 על המזבח\" (ויקרא ו, ב), ללמד: \u0003מה עולה ראויה\u0004 למזבח — \u0003אף כל ראויה.\u0004","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם\u0006 למעשה\u0005]?\u0006 \u0003אמר רב אדא בר אהבה: עולת העוף פסולה איכא בינייהו\u0004 \u0005[יש ביניהם],\u0006 \u0003מר מייתי לה\u0004 \u0005[חכם זה,\u0006 ר' עקיבא, \u0005מביא\u0006 לומד \u0005אותה]\u0006 \u0003מ\u0004מה שנאמר \u0003\"עולה\",\u0004 ואם כן אף עולת העוף פסולה בכלל זה, ואם עלתה על המזבח לא תרד. \u0003ומר מייתי לה\u0004 \u0005[וחכם זה,\u0006 ר' יוסי הגלילי, \u0005מביא אותה]\u0006 \u0003מ\u0004מה שנאמר \u0003\"כבשים\",\u0004 ומכאן שרק בבהמה פסולה הדין כן.","ושואלים: \u0003ולמאן דמייתי לה\u0004 \u0005[ולמי שמביא\u0006 \u0005אותה]\u0006 \u0003מ\"כבשים\", הכתיב\u0004 \u0005[הרי נאמר]\u0006 גם: \u0003\"עלה\"!\u0004 ומשיבים: לשיטתו, \u0003אי כתיב\u0004 \u0005[אם\u0006 היה \u0005נאמר]\u0006 רק \u0003\"כבשים\" ולא כתיב\u0004 \u0005[\u0006היה \u0005נאמר]\u0006 \u0003\"עולה\", הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 \u0003אפילו\u0004 נפסלו \u0003מחיים\u0004 אם עלו לא ירדו, לכן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"עולה\",\u0004 לומר שמדובר במה שעולה על המזבח, ולא בכבשים חיים.","ושואלים: \u0003ולמאן דמייתי לה\u0004 \u0005[ול\u0006שיטת \u0005מי שמביא לו\u0006 לדין זה\u0005]\u0006 מקור \u0003מ\"עולה\", הא כתיב\u0004 \u0005[הרי נאמר]:\u0006 גם \u0003\"כבשים\"!\u0004 ומשיבים: \u0003אי כתיב\u0004 \u0005[אם\u0006 היה \u0005נאמר]\u0006 רק \u0003\"עלה\" ולא כתיב\u0004 \u0005[\u0006היה \u0005נאמר]\u0006 \u0003\"כבשים\", הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 שכל דבר שראוי לעלות על המזבח בכלל זה, \u0003אפילו מנחה,\u0004 לכן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"כבשים\",\u0004 לומר שרק בקרבנות מן החי מדובר, ולא במנחות.","ושואלים: \u0003מאי איכא\u0004 \u0005[מה,\u0006 איזה הבדל \u0005יש]\u0006 \u0003בין\u0004 שיטת \u0003הני תנאי\u0004 \u0005[תנאים אלה\u0006 שבברייתא\u0005],\u0006 ר' יוסי הגלילי ור' עקיבא, \u0003להני תנאי דמתניתין\u0004 \u0005[לאותם התנאים של משנתנו]?\u0006 \u0003אמר רב פפא:\u0004 לגבי \u0003קמצים\u0004 של מנחות \u0003שקדשו בכלי\u0004 ונפסלו \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005],\u0006 \u0003לתנאי דידן\u0004 \u0005[ל\u0006שיטת \u0005התנאים שלנו\u0006 של משנתנו\u0005]\u0006 — \u0003לא ירדו,\u0004 שהרי ראויים הם למזבח ולאישים. \u0003לתנאי דמתניתא\u0004 \u0005[ל\u0006שיטת \u0005התנאים של הברייתא]\u0006 — \u0003ירדו,\u0004 שלשיטת שניהם, רק בעלי חיים אמורים בענין זה.","ובסיכום דעות התנאים בענין זה, \u0003ריש לקיש אמר: מנחה הבאה בפני עצמה,\u0004 כקרבן בפני עצמו, ולא כנספחת לזבח, ונפסלה, \u0003לדברי כולן\u0004 — \u0003לא תרד,\u0004 לדעת ר' יהושע ורבן גמליאל — משום שהיא ראויה לאישים, ולדעת ר' שמעון — משום שהיא באה בפני עצמה. אבל \u0003לדברי ר' יוסי הגלילי ור' עקיבא\u0004 —"],["\u0003תרד\u0004 שכן לשיטת שניהם, במנחות לא נאמרה ההלכה שאם עלו אין יורדים, שאינן דומות לכבשים. \u0003מנחה הבאה עם הזבח\u0004 כלומר, מנחת נסכים שמביאים עם קרבן עולה או שלמים, והיא קריבה כליל על גבי המזבח, אם נפסלה, \u0003לדברי רבן גמליאל ור' יהושע\u0004 — \u0003לא תרד\u0004 שהרי היא ראויה לאישים, ואילו \u0003לדברי כולן\u0004 — \u0003תרד,\u0004 אם משום שאינה דומה לכבשים (לשיטת ר' יוסי הגלילי ור' עקיבא), ואם משום שאינה באה לעצמה (לשיטת ר' שמעון).","\u0003נסכים הבאין בפני עצמן\u0004 יין שנדר אדם כדי לנסכו על המזבח, ולא יחד עם קרבן, \u0003לדברי כולן\u0004 — \u0003ירדו,\u0004 אם משום שאינם דומים לכבשים (לשיטת ר' יוסי הגלילי ור' עקיבא), ואם משום שאינם ראויים לאישים (לשיטת ר' יהושע). ואילו \u0003לדברי רבן גמליאל ור' שמעון\u0004 — \u0003לא ירדו,\u0004 שהרי הם ראויים למזבח (לשיטת רבן גמליאל), והם באים לעצמם (לשיטת ר' שמעון). \u0003נסכין הבאין עם הזבח, לדברי כולן\u0004 — \u0003ירדו,\u0004 אם משום שאינם דומים לכבשים (לשיטת ר' יוסי ור' עקיבא), ואם משום שאינם ראויים לאישים (לשיטת ר' יהושע), או משום שאינם באים לעצמם (לשיטת ר' שמעון), \u0003לדברי רבן גמליאל לחודיה\u0004 \u0005[לחוד]\u0006 — \u0003לא ירדו,\u0004 שהרי ראויים הם למזבח.","ושואלים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכן הוא, שהרי כל זה בכלל הדברים שכבר נאמרו, ומה חידש ריש לקיש בדבריו? ומשיבים: ההלכה בדין \u0003מנחה הבאה בפני עצמה איצטריכא ליה\u0004 \u0005[הוצרכה לו\u0006 לריש לקיש\u0005],\u0006 להשמיענו שמנחה הבאה עם הזבח יכולה גם לבוא בפני עצמה, אם אדם מתנדב כן בפירוש. \u0003וכ\u0004דברי \u0003רבא,\u0004 ש\u0003אמר רבא: מתנדב אדם מנחת נסכים,\u0004 כלומר, מנחה עם נסכים שציותה התורה להביא עם הזבח, \u0003בכל יום,\u0004 ולא רק עם הזבח.","\u0003ו\u0004שואלים: אם כן, \u0003נשמעינן\u0004 \u0005[שיאמר לנו\u0006 ריש לקיש כלומר: אמר במפורש\u0005]\u0006 \u0003כ\u0004דברי \u0003רבא,\u0004 ולא בדרך עקיפה! אלא, דינם של \u0003נסכים הבאים עם הזבח,\u0004 שהוזכרו בדבריו במפורש, \u0003איצטריכא ליה\u0004 \u0005[הוצרך לו]\u0006 לריש לקיש להשמיענו, במקרה \u0003דקא מקרב להו למחר וליומא חרא\u0004 \u0005[שהוא מקריב אותם למחר וליום שאחריו],\u0006 ולא ביום שהקריב את הקרבן.","שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר],\u0006 \u0003הואיל ואמר מר\u0004 \u0005[החכם]\u0006 בדרשת הכתוב: \u0003\"מנחתם ונסכיהם\"\u0004 (במדבר כט, יח) — אפילו \u0003בלילה\u0004 הם קרבים, אף שהזבח שבאו עמו קרב ביום, \u0003\"מנחתם ונסכיהם\"\u0004 — גם \u0003למחר\u0004 (לאחר שכבר קרב הזבח שבאו עמו) הם קרבים, אם כן, \u0003כנסכים הבאין בפני עצמן דמו\u0004 \u0005[\u0006הם \u0005נחשבים],\u0006 \u0003ומודי\u0004 \u0005[ומודה]\u0006 \u0003ר' שמעון\u0004 ש\u0003לא ירדו, קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שהריהם כנספחים לקרבן, וירדו.","\u0003אלו\u0004 הם הדברים שאף שנפסלו, \u0003אם עלו\u0004 על המזבח \u0003לא ירדו: הלן\u0004 דם, או אימורים, או איברי עולה, שעבר עליהם הלילה מחוץ למזבח, \u0003והיוצא\u0004 מתחום העזרה, \u0003והטמא, ושנשחט\u0004 במחשבה להקריבו \u0003חוץ לזמנו ו\u0004כן במחשבה להקריבו \u0003חוץ למקומו, ו\u0004הזבח \u0003שקבלו\u0004 את דמו אנשים שהם \u0003פסולין\u0004 לעבודה, \u0003ו\u0004כן ש\u0003זרקו\u0004 פסולים \u0003את דמו.\u0004","\u0003ר' יהודה אומר:\u0004 הזבח \u0003שנשחט בלילה, ו\u0004כן בהמת קדשים ש\u0003נשפך דמה, ו\u0004כן זו ש\u0003יצא דמה חוץ לקלעים\u0004 ונפסלה בכך, גם \u0003אם עלתה תרד. ר' שמעון אומר:\u0004 כל אחת מאלה, אם עלתה \u0003לא תרד,\u0004 משום \u0003שהיה פסולו\u0004 של קרבן זה \u0003בקדש. ש\u0004כך היה \u0003ר' שמעון אומר\u0004 ככלל: \u0003כל\u0004 קרבן פסול \u0003שפסולו\u0004 חל \u0003בקדש\u0004 תוך כדי עבודה במקדש — \u0003הקדש מקבלו,\u0004 וכיון שעלה על המזבח לא ירד. וכל ש\u0003לא היה פסולו בקדש\u0004 ומתחילה לא היה ראוי להקרבה — \u0003אין הקדש מקבלו.\u0004","\u0003ואלו\u0004 הם \u0003שלא היו פסולן בקדש,\u0004 ואם עלו ירדו: בעל חיים \u0003הרובע\u0004 את האדם, \u0003ו\u0004כן בעל חיים \u0003הנרבע\u0004 על ידי אדם, \u0003והמוקצה\u0004 (המופרש) לעבודה זרה, \u0003והנעבד\u0004 כעבודה זרה, \u0003והאתנן\u0004 (שכרה של הזונה), \u0003והמחיר\u0004 שקנו בו כלב, \u0003והכלאים, והטרפה\u0004 (שנפגע או שחלה וסופו למות), \u0003והיוצא דופן\u0004 (שנולד בחיתוך דופן הרחם ולא באופן טבעי) \u0003ובעלי מומין. ר' עקיבא מכשיר בבעלי מומין,\u0004 וסבור שאם עלו, לא ירדו. \u0003ר' חנינא סגן הכהנים אומר: דוחה היה אבא את בעלי מומין מעל גבי המזבח.\u0004","ושבים לתחילת המשנה, לאלו שאם עלו לא ירדו, ומוסיפים: \u0003כשם שאם עלו לא ירדו, כך\u0004 מצד שני \u0003אם ירדו\u0004 שוב \u0003לא יעלו. וכולן,\u0004 גם אלו שאם עלו לא ירדו, במקרה \u0003שעלו חיים לראש המזבח\u0004 — \u0003ירדו,\u0004 שבהמה חיה אינה ראויה למזבח, אלא לאחר שחיטה. \u0003עולה שעלתה חיה לראש המזבח\u0004 — \u0003תרד,\u0004 שלכתחילה אין שוחטים בראש המזבח, אבל אם \u0003שחטה בראש המזבח\u0004 — \u0003יפשיט וינתחה במקומה,\u0004 ואין מורידים אותה עוד.","ובטעמי שיטות התנאים שנשנו במשנה \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יהודה אומר:\u0004 בכתוב ממנו למדנו שהעולים למזבח לא ירדו, נאמר: \u0003\"זאת\u0004 תורת העולה \u0003היא העולה\u0004 על מוקדה על המזבח\" (ויקרא ו, ב) — \u0003הרי אלו שלשה מיעוטין:\u0004 \"זאת\", \"היא\", וה\"א של \"העולה\", \u0003פרט לשנשחטה בלילה, ושנשפך דמה, ושיצא דמה חוץ לקלעים, שאם\u0004 אחת מהן \u0003עלתה\u0004 למזבח — \u0003תרד.\u0004","\u0003ר' שמעון אומר:\u0004 נאמר בכתוב זה \u0003\"עלה\"\u0004 — \u0003אין לי אלא עולה כשרה, מנין לרבות\u0004 גם זו \u0003שנשחטה בלילה, ושנשפך דמה, ושיצא דמה חוץ לקלעים, והלן, והיוצא, והטמא, ושנשחט חוץ לזמנו וחוץ למקומו, ושקבלו פסולין וזרקו את דמו,\u0004 או דם הזבחים","\u0003הניתנין למטה\u0004 מחוט הסיקרא, כגון דם העולה והאשם והשלמים, \u0003שנתנן למעלה,\u0004 או דמי חטאת שצריכים להינתן \u0003למעלה שנתנן למטה, ו\u0004כן \u0003ה\u0004קרבנות שדמיהם \u0003ניתנין בחוץ\u0004 על המזבח החיצון \u0003שנתנן בפנים\u0004 בהיכל, וכן אלו שדמם ניתן \u0003בפנים\u0004 (החטאות הפנימיות) \u0003שנתנן בחוץ, ו\u0004קרבן ה","\u0003פסח וחטאת ששחטן שלא לשמן,\u0004 אף על פי שכולם פסולים, \u0003מנין\u0004 שאם עלו למזבח לא ירדו? \u0003תלמוד לומר: \"תורת העלה\"\u0004 — \u0003ריבה\u0004 הכתוב שתהא \u0003תורה\u0004 (הלכה) \u0003אחת לכל העולין, שאם עלו\u0004 — \u0003לא ירדו.\u0004","\u0003יכול שאני מרבה\u0004 גם \u0003הרובע והנרבע, והמוקצה והנעבד, ואתנן ומחיר, וכלאים וטרפה ויוצא דופן? תלמוד לומר: \"זאת\",\u0004 למעט.","ושואלים: \u0003ומה ראית לרבות את אלו\u0004 שמנינו \u0003ולהוציא את אלו?\u0004 ומשיבים: \u0003אחר שריבה\u0004"],["\u0003הכתוב ומיעט,\u0004 וצריך אני להכריע, מה לרבות ומה למעט, \u0003מרבה אני את\u0004 כל \u0003אלו שהיה פסולן בקדש\u0004 במקדש, תוך כדי עבודה, שאם עלו לא ירדו, \u0003ומוציא\u0004 (ממעט) \u0003אני את אלו שלא היה פסולן בקודש,\u0004 שאם עלו ירדו.","\u0003ור' יהודה,\u0004 שאינו דורש כר' שמעון להכשיר כל שפסולו בקודש, ומכל מקום מסכים לדברי המשנה בענין הלן והטמא וכו', \u0003מייתי\u0004 \u0005[מביא]\u0006 \u0003לה\u0004 הסבר לשיטתו \u0003מהכא\u0004 \u0005[מכאן],\u0006 כפי ששנינו בברייתא, \u0003מפני מה אמרו: לן בדם\u0004 (דם שנפסל בלינה) שהוא \u0003כשר\u0004 כלומר, שאם עלה למזבח לא ירד —","\u0003שהרי לן כשר באימורין,\u0004 ומפני מה אמרו ש\u0003לן באימורין כשר\u0004 — \u0003שהרי לן כשר בבשר,\u0004 שבשר שלמים מותר באכילה לכתחילה ליום ולילה ויום, ואין לינת הלילה פוסלתו.","מפני מה אמרו ש\u0003יוצא\u0004 חוץ לעזרה כשר, שאם עלה לא ירד — לפי \u0003שהיוצא כשר בבמה\u0004 (בזמן שהיא מותרת) שהרי כל עיקרה של העבודה בבמה הוא בחוץ.","ומפני מה אמרו ש\u0003טמא\u0004 אם עלה לא ירד — \u0003הואיל והותר\u0004 הטמא \u0003לעבודת ציבור,\u0004 שאם הציבור או הכהנים טמאים, הותרה עבודת הציבור בטומאה.","הנשחט במחשבת \u0003חוץ לזמנו\u0004 אם עלה לא ירד — \u0003הואיל ו\u0004הוא \u0003מרצה\u0004 על כל פנים \u0003ל\u0004ענין \u0003פיגולו,\u0004 שהרי רק אם נעשית עבודת הקרבן כראוי, חל עליו דין פיגול.","הנשחט במחשבת \u0003חוץ למקומו\u0004 אם עלה לא ירד — \u0003הואיל ואיתקש\u0004 \u0005[והוקש]\u0006 בכתוב \u0003ל\u0004נשחט במחשבת \u0003חוץ לזמנו.\u0004","ומה שאמרו על קרבן \u0003שקבלו פסולין וזרקו את דמו\u0004 שאם עלה לא ירד — מדובר \u0003בהנך פסולי דחזו\u0004 \u0005[באותם פסולים שראויים]\u0006 \u0003לעבודת ציבור,\u0004 כגון כהן טמא.","ושואלים על הסברים אלו: \u0003וכי דנין דבר שלא בהכשרו\u0004 כלומר, להכשיר דבר שעושה שלא כראוי \u0003מדבר שבהכשרו\u0004 שכשר כך לכתחילה?","ומשיבים: ה\u0003תנא\u0004 על מה שהכתוב \u0003\"זאת תורת העלה\"\u0004 (ויקרא ו, ב) ש\u0003ריבה\u0004 בה הכתוב את כל הפסולים שלא ירדו \u0003סמיך ליה\u0004 \u0005[סומך עליה],\u0006 ולא הובאו נימוקים אלה אלא כדי להסביר מדוע לדעת ר' יהודה, אין ממעטים גם אותם \"מזאת\" \"היא\" ו\"העולה\".","ובענין בהמה שנשחטה בלילה, שלדעת ר' יהודה, גם אם עלתה — תרד, \u0003אמר ר' יוחנן: השוחט בהמה בלילה בפנים\u0004 במקדש, וחזר \u0003והעלה\u0004 אותה להקריבה \u0003בחוץ\u0004 לעזרה — \u0003חייב\u0004 על העלאה זו, ככל המקריב בחוץ."],["\u0003לא תהא\u0004 שחיטה בלילה \u0003פחותה משוחט בחוץ ומעלה בחוץ,\u0004 שחייב על ההעלאה, כמבואר במשנה להלן (זבחים קו,א), למרות שאינה מתקבלת בפנים, וגם אם עלתה תרד.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב חייא בר אבין\u0004 ממה ששנינו: \u0003השוחט עוף בפנים, ומעלה בחוץ\u0004 — \u0003פטור\u0004 על ההעלאה, שהרי עוף של קרבן נמלק ולא נשחט. אבל אם \u0003שחט\u0004 את העוף \u0003בחוץ, ומעלה בחוץ\u0004 — \u0003חייב.\u0004 ולפי דברי ר' יוחנן, גם כאן \u0003נימא\u0004 \u0005[נאמר]:\u0006 \u0003לא תהא\u0004 שחיטה בפנים \u0003פחותה משוחט ומעלה בחוץ,\u0004 ומדוע הוא פטור!","ואומרים: אכן, \u0003תיובתא\u0004 \u0005[קושיה חמורה\u0006 היא\u0005]\u0006 ונדחו דברי ר' יוחנן. \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 תירוץ לקושיה זו: אין מקום ללמוד משחיטת עוף בחוץ לשחיטת עוף בפנים, שכן \u0003שחיטת העוף בפנים\u0004 הרי זה כאילו \u0003מיקטל קטליה\u0004 \u0005[הרג אותו].\u0006 מה שאין כן בשחיטת בהמה בלילה בפנים, אף שהיא פסולה, הרי זו שחיטה, ויש ללומדה משחיטת חוץ.","ועוד בדינם של דברים שעלו על המזבח שלא כהלכתם, \u0003אמר עולא: אימורי\u0004 (חלקי הקרבן הנשרפים במזבח) \u0003קדשים קלים שהעלן\u0004 למזבח \u0003לפני זריקת דמן,\u0004 שהיא המקדשתם למזבח — \u0003לא ירדו,\u0004 כיון ש\u0003נעשו לחמו של מזבח.\u0004","\u0003אמר ר' זירא: אף אנן נמי תנינא\u0004 \u0005[אף אנו גם כן שנינו]\u0006 במשנתנו: \u0003שנשפך דמה, ושיצא דמה חוץ לקלעים\u0004 בכל אלו, אם עלו האימורים לא ירדו. ומעתה יש ללמוד: \u0003ומה התם\u0004 \u0005[שם]\u0006 ש\u0003אם בא לזרוק\u0004 את הדם \u0003אין לו\u0004 אפשרות \u0003לזרוק\u0004 ולהכשירם להקרבה, שהרי נשפך הדם, בכל זאת \u0003אמרת\u0004 \u0005[אומר אתה]:\u0006 \u0003אם עלו לא ירדו, הכא\u0004 \u0005[כאן]\u0006 שהדם קיים, ו\u0003אם בא לזרוק זורק\u0004 ומכשירם להקרבה, \u0003לא כל שכן\u0004 שאם עלו לא ירדו?","ודוחים: \u0003תרגמא\u0004 \u0005[תרגם,\u0006 הסבר \u0005אותה]\u0006 הלכה זו שבמשנה דווקא ב\u0003קדשי קדשים\u0004 שכן אימוריהם מקודשים למזבח אף לפני זריקת הדם, ולכן אם עלו לא ירדו. אבל אימורי קדשים קלים אינם ראויים כלל למזבח קודם זריקת הדם.","ומקשים: \u0003הרי\u0004 קרבן \u0003פסח,\u0004 שנזכר באותה רשימה של דברים שאם עלו לא ירדו, ש\u0003קדשים קלים הוא!\u0004 ודוחים: \u0003תרגמא\u0004 \u0005[תרגם,\u0006 הסבר\u0005]\u0006 שהוזכר שם פסח רק \u0003ב\u0004ענין אם נשחט \u0003שלא לשמן,\u0004 ולא לענין נשפך ויצא הדם.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003וכולן שעלו חיין לגבי מזבח\u0004 — \u0003ירדו,\u0004 ונדייק מכאן: \u0003הא\u0004 \u0005[אבל]\u0006 \u0003שחוטין\u0004 — \u0003לא ירדו\u0004 גם אם לא נזרק דמם. \u0003מאי לאו\u0004 \u0005[האם אין]\u0006 דיוק זה חל על כל הקדשים, \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 ב\u0003קדשי קדשים, לא שנא\u0004 \u0005[אינו שונה]\u0006 ב\u0003קדשים קלים?\u0004","ודוחים: \u0003לא,\u0004 אפשר לומר: \u0003הא\u0004 \u0005[אבל]\u0006 \u0003שחוטין\u0004 — \u0003מהן ירדו, מהן לא ירדו.\u0004 ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"כולן\" קתני\u0004 \u0005[שנה],\u0006 ועל כולם יש לדייק שאם היו שחוטים לא ירדו! ומשיבים: מה ששנינו \u0003\"כולם\"\u0004 מתייחס רק ל\u0003חיין,\u0004 להשמיענו שכל הקרבנות הכשרים שעלו למזבח — ירדו, ואין צורך לשוחטם על המזבח, ואינה מלמדת לגבי שחוטים.","ושואלים: ומדוע הוצרכה המשנה לאמר זאת? \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שירדו! ומשיבים: \u0003לעולם\u0004 מדובר על ה\u0003חיין,\u0004 אבל לא בבעלי חיים כשרים, אלא בבעלי מום \u0003בדוקין\u0004 (קרום) \u0003שבעין, ואליבא\u0004 \u0005[ולפי שיטתו]\u0006 של \u0003ר' עקיבא,\u0004 ש\u0003אמר\u0004 קודם לכן במשנה ש\u0003אם עלו לא ירדו,\u0004 ובאה המשנה להשמיענו כי בחיים מודה הוא שירדו.","ומקשים: \u0003במאי אוקימתא\u0004 \u0005[במה העמדת]\u0006 את ההלכה הזו במשנה — \u0003בפסולין, אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]:\u0006 \u0003וכן עולה שעלתה חיה לראש המזבח\u0004 — \u0003תרד, שחטה בראש המזבח\u0004 — \u0003יפשיט וינתח במקומה. ואי\u0004 \u0005[ואם]\u0006 \u0003פסולה\u0004 היא, כדבריך, יש לתמוה: וכי \u0003בת הפשט ונתוח היא?\u0004 הלוא \"והפשיט את העולה \u0003ונתח אתה\"\u0004 (ויקרא א, ו) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 \u0003\"אתה\"\u0004 — הרי זה מיעוט: \u0003כשרה ולא פסולה!\u0004","ומשיבים: \u0003סיפא אתאן\u0004 \u0005[בסוף,\u0006 בהלכה זו לגבי עולה, \u0005באנו]\u0006 \u0003לכשרה.\u0004 ושואלים: \u0003ומאי קמשמע לן\u0004 \u0005[מה משמיע לנו]?\u0006 ומשיבים: ש\u0003יש הפשט ונתוח\u0004 גם \u0003בראש המזבח,\u0004 ואין בכך גנאי.","ושואלים: \u0003ולמאן דאמר\u0004 \u0005[ול\u0006דעת \u0005מי שאומר]:\u0006 \u0003אין הפשט ונתוח בראש המזבח, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 ומשיבים: לשיטתו, \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 \u0003כגון שהיתה לו שעת הכושר ונפסלה,\u0004 שעלתה חיה, ושחטה בראש המזבח וזרק דמה, ואחר כך אירע בה פסול. \u0003ו\u0004משנה זו לדעת \u0003ר' אלעזר בר' שמעון היא,\u0004 ש\u0003אמר: כיון שנזרק הדם ו\u0004בכך \u0003הורצה בשר\u0004 להקרבה \u0003שעה אחת,\u0004 הרי אף שנפסלה לאחר מכן — \u0003יפשיטנה ועורה לכהנים,\u0004 ובשרה מוקטר.","ושואלים: \u0003ואלא,\u0004 אם בפסולה מדובר, \u0003דקתני\u0004 \u0005[מה שהוא שונה]\u0006 בתוספתא על משנתנו: \u0003כיצד עושה? מוריד את הקרבים למטה ומדיחן, למה לי?\u0004 כלומר, מדוע? הרי לאחר שמורידם שוב לא יעלו!","ומשיבים: אלא \u0003היכי נעביד\u0004 \u0005[כיצד נעשה]?\u0006 \u0003נקרבינהו בפרתייהו\u0004 \u0005[נקריב אותם עם הפרש שבתוכם]?\u0006 הלוא על כיוצא בזה כבר נאמר: \u0003\"הקריבהו נא לפחתך הירצך או הישא פניך\"\u0004 (מלאכי א, ח), שדבר המאוס לפני בשר ודם אין ראוי להקריבו לגבוה!","ומסבירים: \u0003אנן הכי קאמרינן\u0004 \u0005[אנו כך אומרים,\u0006 תמהים\u0005]:\u0006 הואיל ומורידים את הקרביים, \u0003מדיחן למה לי?\u0004 והרי כיון שפסולים הם, שוב אין מעלים אותם! ומשיבים: משום חשש \u0003דאי מיתרמי\u0004 \u0005[שאם מזדמן]\u0006 \u0003כהן אחרינא\u0004 \u0005[אחר]\u0006 \u0003ולא ידע\u0004 שהם פסולים — \u0003נסקינהו\u0004 \u0005[יעלה אותם]\u0006 כשהפרש בתוכם."],["ותמהים: \u0003ואנן ניקו נעביד להו\u0004 \u0005[ואנו נקום נעשה להם]\u0006 \u0003לכהנים מילתא דאתו בה\u0004 \u0005[דבר שיבואו בו]\u0006 \u0003לידי תקלה?!\u0004 שהרי כשאין הקרביים רחוצים לא יבואו להעלותה למזבח! ומשיבים: \u0003אפילו הכי עדיפא\u0004 \u0005[אפילו כך עדיף],\u0006 \u0003שלא יהו קדשי שמים מוטלים כנבילה.\u0004","בעניין זה שעסקנו בו, \u0003אמר ר' חייא בר אבא, בעי\u0004 \u0005[שאל\u0006 הסתפק\u0005]\u0006 \u0003ר' יוחנן: אימורי קדשים קלים שהעלן לפני זריקת דמן\u0004 (שהיא המתירה אותה בהקרבה), האם \u0003ירדו או לא ירדו?\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אמי\u0004 לר' יוחנן: עד שאתה דן בדינם של אלו לענין ירידה מהמזבח, \u0003ותיבעי\u0004 \u0005[ותישאל,\u0006 ותסתפק\u0005]\u0006 \u0003לך\u0004 האם העלאתם למזבח קידשתם לענין דין \u0003מעילה! אמר ליה\u0004 \u0005[לו]\u0006 בתשובה: לענין \u0003מעילה לא קמיבעיא\u0004 \u0005[נשאלה]\u0006 \u0003לי,\u0004 כי ודאי הוא ש\u0003זריקה הוא דקבעה להו\u0004 \u0005[שקובעת אותם]\u0006 \u0003ב\u0004דין \u0003מעילה,\u0004 ואין העלאתם למזבח מקדשתם לענין זה. ואולם \u0003כי קמיבעיא ליה\u0004 \u0005[כאשר נשאלה לו]\u0006 לר' יוחנן, היה זה רק האם יש בהם \u0003ירידה. ופשיט\u0004 \u0005[ופשט\u0006 ר' יוחנן ופתר את ספקו\u0005]:\u0006 הלכה היא שאם עלו \u0003לא ירדו, ו\u0004אולם \u0003אין בהן מעילה.\u0004","\u0003רב נחמן בר יצחק מתני הכי\u0004 \u0005[היה שונה כך]\u0006 את מהלך הדברים: \u0003אמר ר' חייא בר אבא, בעי\u0004 \u0005[שאל,\u0006 הסתפק\u0005]\u0006 \u0003ר' יוחנן: אימורי קדשים קלים שהעלן לפני זריקת דמן, יש בהן מעילה או לא? אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אמי: ותיבעי\u0004 \u0005[ושתישאל]\u0006 \u0003לך\u0004 בענין \u0003ירידה! אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ירידה לא קא מיבעיא\u0004 \u0005[נשאלה]\u0006 \u0003לי\u0004 משום שלאחר שעלו \u0003נעשו לחמו של מזבח, כי קמיבעיא\u0004 \u0005[כאשר נשאלה]\u0006 \u0003לי\u0004 היה זה בענין \u0003מעילה, ופשיט הכי\u0004 \u0005[ופשט\u0006 ר' יוחנן ופתר \u0005כך]:\u0006 \u0003לא ירדו, ואין בהן מעילה.\u0004","שנינו במשנה: \u0003ואלו לא היה פסולן\u0004 בקודש: הרובע והנרבע... ובעלי מומין, שאם עלו — ירדו, ור' עקיבא מכשיר בבעלי מומין.","\u0003אמר ר' יוחנן: לא הכשיר ר' עקיבא\u0004 כל בעלי מומים, שאם עלו לא ירדו, \u0003אלא\u0004 דווקא באלה שהיה בהם מום קטן, כגון \u0003בדוקין\u0004 (כעין קרומים) \u0003שבעין, הואיל וכשרים\u0004 מומים כאלה לכתחילה \u0003בעופות. והוא שקדם הקדשן את מומן,\u0004 שבשעת הקדשם היו ראויים למזבח, אלא שאחר כך נפל בהם מום. אבל אם קדם מומם להקדשם — גם אם עלו ירדו, שמתחילה לא היו ראויים להקרבה. \u0003ומודה ר' עקיבא בעולת נקבה,\u0004 שאם הקדיש נקבה לעולה, שגם אם עלתה — תרד. שהואיל ואין עולה באה אלא מן הזכרים, הרי כמו \u0003שקדם מומה להקדשה דמיא\u0004 \u0005[\u0006היא \u0005נחשבת].\u0006 ומביאים דיון שהוזכרו בו דברי ר' עקיבא כראיה.","\u0003בעי\u0004 \u0005[שאל\u0006 הסתפק\u0005]\u0006 \u0003ר' ירמיה:\u0004 האם \u0003יש\u0004 פסול \u0003נרבע בעופות, או אין נרבע בעופות?\u0004 ויסוד הספק: \u0003מי\u0004 \u0005[האם]\u0006 זה ש\u0003אמר\u0004 הכתוב: \"אדם כי יקריב... \u0003מן הבהמה\"\u0004 (ויקרא א, ב), ובאה לשון \"מן\" שבכתוב \u0003להוציא\u0004 (למעט) מכלל הכשרים להקרבה \u0003את הרובע\u0004 אדם \u0003והנרבע\u0004 על ידי אדם, האם יש ללמוד ממה שנלמדו רובע ונרבע כאחד, כי","\u0003כל היכא דאיתיה\u0004 \u0005[כל מקום שישנו]\u0006 \u0003ב\u0004איסור \u0003רובע איתיה\u0004 \u0005[ישנו]\u0006 גם \u0003בנרבע, כל היכא דליתיה\u0004 \u0005[כל מקום שאינו]\u0006 \u0003ב\u0004דין \u0003רובע ליתיה\u0004 \u0005[אינו]\u0006 \u0003ב\u0004דין \u0003נרבע.\u0004 ובעופות שאין בהם אפשרות שיהא רובע, אין בהם גם פסול נרבע. \u0003או דלמא\u0004 \u0005[שמא]\u0006 הנרבע פסול להקרבה, ש\u0003הרי\u0004 על כל פנים \u0003נעבדה בו עבירה?\u0004","\u0003אמר רבה: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו במשנתנו: \u0003ר' עקיבא מכשיר בבעלי מומין,\u0004 הואיל וכשרים בעופות. \u0003ואם איתא\u0004 \u0005[יש]\u0006 מקום לסברה זו, שנרבע כשר בעופות — \u0003נכשיר נמי\u0004 \u0005[שיכשיר גם כן]\u0006 \u0003בנרבע, הואיל ו\u0004נרבע \u0003כשר בעופות.\u0004 \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שאין נרבע בעופות כשר להקרבה.","\u0003אמר רב נחמן בר יצחק: אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו\u0006 בברייתא\u0005]:\u0006 העוף \u0003הנרבע, והמוקצה והנעבד, ואתנן, ומחיר,\u0004 \u0003וטומטום, ואנדרוגינוס\u0004 — \u0003כולן\u0004 אם נמלקו, הרי כזית מהם \u0003מטמאין בגדים\u0004 בהיותם ב\u0003בית הבליעה\u0004 של האוכלם, כדין כל נבלת העוף. ומתוך שבכלל הפסולים נמנה גם עוף הנרבע, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שיש פסול נרבע בעוף.","שנינו במשנה, \u0003ר' חנינא סגן הכהנים\u0004 אומר: דוחה היה אבא את בעלי מומין מעל גבי המזבח. ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]\u0006 כאן? הרי זו היא דעת תנא קמא, שאמר שאם עלו — ירדו! ומשיבים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 \u0003מעשה קא משמע לן\u0004 \u0005[משמיע לנו],\u0006 שאין זו רק הלכה בלבד, אלא כך נעשה מעשה בפועל. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"דוחה\"\u0004 שאמר שם — שהיה מוריד אותם מן המזבח \u0003כלאחר יד,\u0004 ולא בפרהסיה כדרך בזיון.","שנינו במשנה לגבי הקרבנות הפסולים שאם עלו לא ירדו: \u0003כשם שאם עלה\u0004 לא ירד, כך אם ירד — אין מעלים אותו. \u0003אמר עולא: לא שנו אלא שלא משלה\u0004 (אחזה) \u0003בהן האור\u0004 אש המזבח, \u0003אבל משלה בהן האור,\u0004 גם אם ירדו — \u0003יעלו.\u0004","\u0003רב מרי מתני ארישא\u0004 \u0005[היה שונה\u0006 את דבריו אלה של עולא \u0005על ההתחלה,\u0006 על משנתנו\u0005]\u0006 כפי שהסברנו. \u0003רב חנינא מסורא מתני אסיפא\u0004 \u0005[היה שונה\u0006 זאת \u0005על הסוף,\u0006 על המשנה הבאה\u0005]\u0006 ששנינו בה: \u0003העצמות והגידין, והקרנים והטלפים\u0004 של קרבן עולה, שקרב כליל על המזבח, \u0003בזמן שמחוברין\u0004 לבהמה — \u0003יעלו, פרשו\u0004 מבשרה — \u0003לא יעלו. אמר עולא: לא שנו\u0004 שאם פרשו לא יעלו, \u0003אלא שלא משלה בהן האור, אבל משלה בהן האור,\u0004 גם אם פרשו מבשרה — \u0003יעלו.\u0004","ומעירים: \u0003מאן דמתני אסיפא\u0004 \u0005[מי שהיה שונה\u0006 את דברי עולא \u0005על הסוף,\u0006 לגבי עצמות וגידים שפרשו\u0005],\u0006 שאם אחזה בהן האור יעלו, למרות שאינם בני הקטרה כשלעצמם, \u0003כל שכן\u0004 שהוא שונה אותם \u0003ארישא\u0004 \u0005[על ההתחלה,\u0006 על משנתנו\u0005]\u0006 שעוסקת בדברים שהם בני הקטרה אלא שנפסלו. \u0003ו\u0004אולם \u0003מאן דמתני ארישא\u0004 \u0005[מי ששונה\u0006 את דברי עולא \u0005על ההתחלה],\u0006 יש לומר כי דווקא פסולים שאחזה בהם האש, גם אם ירדו יעלו, \u0003אבל אסיפא\u0004 \u0005[על הסוף]\u0006 אינו מודה, כי עצמות וגידים \u0003לאו\u0004 \u0005[לא]\u0006 \u0003בני הקטרה\u0004 (הקרבה) \u0003נינהו\u0004 \u0005[הם]\u0006 כלל.","\u0003ואלו\u0004 הם הדברים שאף \u0003אם עלו\u0004 למזבח \u0003ירדו\u0004 כיון שאינם ראויים כלל למזבח: \u0003בשר קדשי קדשים\u0004 (אשם וחטאת) שנאכל לכהנים, \u0003ובשר קדשים קלים\u0004 שנאכל לבעלים, \u0003ומותר\u0004 מנחת \u0003העומר\u0004 שמביאים מן השעורים למחרת הפסח, לאחר שהקטירו ממנה את הקומץ, \u0003ושתי הלחם\u0004 הבאים בחג השבועות, \u0003ולחם הפנים, ושירי\u0004 (שאריות) \u0003מנחות\u0004 לאחר הקמיצה מהם, שכל אלו נאכלים לכהנים, \u0003והקטורת\u0004 שעלתה על המזבח החיצון, ולא על מזבח הזהב שבהיכל, כהלכתה.","ועוד בדינם של חלקי קרבן עולה שאינם ראויים למזבח: \u0003הצמר שבראשי כבשים\u0004 (הבאים לקרבן עולה), \u0003ושער שבזקן תישים\u0004 שהוקרבו, \u0003והעצמות, והגידים, והקרנים, והטלפים\u0004 (קצות הרגלים, הפרסות), כל אלה, \u0003בזמן שהם מחוברים\u0004 לבשר הזבח — \u0003יעלו\u0004 על המזבח ויוקרבו עם הזבח עצמו, \u0003ש\u0004כן \u0003נאמר: \"והקטיר הכהן את הכל\u0004 המזבחה\" (ויקרא א, ט). ואולם אם \u0003פירשו\u0004 (נפרדו) מבשר הזבח עצמו — \u0003לא יעלו, שנאמר: \"ועשית עלתיך הבשר והדם\"\u0004 (דברים יב, כז), ולא דברים אחרים.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003\"והקטיר הכהן את הכל המזבחה\"\u0004 (ויקרא א, ט) — הרי לשון זו (\"הכל\") באה \u0003לרבות\u0004 בכלל ההקרבה גם את \u0003העצמות והגידים, והקרנים והטלפים. יכול אפילו פרשו\u0004 מן העולה יוקרבו? \u0003תלמוד לומר: \"ועשית עלתיך הבשר והדם\"\u0004 (דברים יב, כז).","ומצד שני, \u0003אי\u0004 \u0005[אם]\u0006 אתה מדקדק במה שכתוב \u0003בשר ודם,\u0004"]]};
